window.FC_BANK=[{"t":1,"c":"Art. 90 Introduction","f":"What is the purpose of the NEC?","b":"Practical safeguarding of persons and property from hazards arising from the use of electricity.","r":"NEC 90.1(A)"},{"t":1,"c":"Art. 90 Introduction","f":"Does following the NEC guarantee an efficient or convenient installation?","b":"No. A compliant, properly maintained installation is essentially free from hazard, but not necessarily efficient, convenient, or adequate for good service or future expansion.","r":"NEC 90.1(B)"},{"t":1,"c":"Art. 90 Introduction","f":"Name some installations the NEC does NOT cover.","b":"Ships and watercraft (other than floating buildings), railway rolling stock, aircraft, and automotive vehicles other than mobile homes and RVs; underground mines.","r":"NEC 90.2(B)"},{"t":1,"c":"Art. 90 Introduction","f":"Can the AHJ waive a Code requirement?","b":"Yes. The AHJ may waive specific requirements or permit alternate methods where equivalent safety is secured.","r":"NEC 90.4"},{"t":1,"c":"Art. 90 Introduction","f":"What do the terms 'shall' and 'shall not' mean in the NEC?","b":"They mark mandatory rules. 'Shall be permitted' and 'shall not be required' mark permissive rules.","r":"NEC 90.5(A), (B)"},{"t":1,"c":"Art. 90 Introduction","f":"Are Informational Notes enforceable?","b":"No. Informational Notes are explanatory material only, not requirements.","r":"NEC 90.5(C)"},{"t":1,"c":"Art. 90 Introduction","f":"Which NEC chapters apply generally, and which supplement or modify?","b":"Chapters 1 through 4 apply generally. Chapters 5, 6, and 7 supplement or modify 1 through 4. Chapter 8 stands alone unless referenced. Chapter 9 tables apply as referenced.","r":"NEC 90.3"},{"t":1,"c":"Art. 90 Introduction","f":"Are the Annexes part of the enforceable Code?","b":"No. Annexes are informational only and not enforceable unless adopted.","r":"NEC 90.3"},{"t":1,"c":"Art. 100 Definitions","f":"Define ampacity.","b":"The maximum current a conductor can carry continuously under the conditions of use without exceeding its temperature rating.","r":"NEC 100"},{"t":1,"c":"Art. 100 Definitions","f":"Define branch circuit.","b":"The circuit conductors between the final overcurrent device protecting the circuit and the outlet(s).","r":"NEC 100"},{"t":1,"c":"Art. 100 Definitions","f":"Define feeder.","b":"All circuit conductors between the service equipment (or source of a separately derived system or other supply) and the final branch-circuit overcurrent device.","r":"NEC 100"},{"t":1,"c":"Art. 100 Definitions","f":"Define continuous load.","b":"A load where the maximum current is expected to continue for 3 hours or more.","r":"NEC 100"},{"t":1,"c":"Art. 100 Definitions","f":"Define 'readily accessible.'","b":"Capable of being reached quickly for operation, renewal, or inspection without having to climb over or remove obstacles or use portable ladders.","r":"NEC 100"},{"t":1,"c":"Art. 100 Definitions","f":"Define overload.","b":"Operation of equipment above its normal full-load rating, or a conductor above its ampacity, long enough to cause damage or dangerous overheating. A short circuit or ground fault is not an overload.","r":"NEC 100"},{"t":1,"c":"Art. 100 Definitions","f":"Define overcurrent.","b":"Any current in excess of the rated current of equipment or the ampacity of a conductor. It may result from overload, short circuit, or ground fault.","r":"NEC 100"},{"t":1,"c":"Art. 100 Definitions","f":"Define 'wet location.'","b":"Underground or in concrete slabs in direct contact with earth; locations subject to saturation with water; and unprotected locations exposed to weather.","r":"NEC 100"},{"t":1,"c":"Art. 100 Definitions","f":"Define 'damp location.'","b":"Partially protected locations (under canopies, marquees, roofed open porches) and interior locations with moderate moisture, such as some basements and barns.","r":"NEC 100"},{"t":1,"c":"Art. 100 Definitions","f":"What is the difference between 'listed' and 'labeled'?","b":"Listed: included in a list by an organization acceptable to the AHJ that periodically inspects production. Labeled: has a label or mark of such an organization attached.","r":"NEC 100"},{"t":1,"c":"Art. 100 Definitions","f":"Define 'qualified person.'","b":"One who has skills and knowledge related to the construction and operation of the equipment and installation, and has received safety training to recognize and avoid the hazards involved.","r":"NEC 100"},{"t":1,"c":"Art. 100 Definitions","f":"Define 'dwelling unit.'","b":"A single unit providing complete and independent living facilities for one or more persons, including permanent provisions for living, sleeping, cooking, and sanitation.","r":"NEC 100"},{"t":1,"c":"Art. 100 Definitions","f":"What is a multiwire branch circuit?","b":"Two or more ungrounded conductors with voltage between them, and a grounded (neutral) conductor with equal voltage to each ungrounded conductor.","r":"NEC 100"},{"t":1,"c":"Art. 110 Requirements for Electrical Installations","f":"What must be done with listed or labeled equipment?","b":"It must be installed and used in accordance with any instructions included in the listing or labeling.","r":"NEC 110.3(B)"},{"t":1,"c":"Art. 110 Requirements for Electrical Installations","f":"What must equipment intended to interrupt fault current have?","b":"An interrupting rating at nominal circuit voltage at least equal to the current available at its line terminals.","r":"NEC 110.9"},{"t":1,"c":"Art. 110 Requirements for Electrical Installations","f":"What temperature rating applies to terminals on circuits of 100 A or less (or 14 to 1 AWG)?","b":"Use conductors rated 60 degrees C or higher, sized to the 60 degrees C ampacity unless the equipment is listed otherwise.","r":"NEC 110.14(C)(1)"},{"t":1,"c":"Art. 110 Requirements for Electrical Installations","f":"What temperature rating applies to terminals for circuits over 100 A (or larger than 1 AWG)?","b":"Conductors rated 75 degrees C or higher.","r":"NEC 110.14(C)(1)"},{"t":1,"c":"Art. 110 Requirements for Electrical Installations","f":"How must terminal tightening torque be determined?","b":"By the torque value marked on the equipment or in the installation instructions, using a calibrated torque tool.","r":"NEC 110.14(D)"},{"t":1,"c":"Art. 110 Requirements for Electrical Installations","f":"How is the high leg marked on a 4-wire delta system?","b":"Orange outer finish or other effective means; it is the conductor with the higher voltage to ground (midpoint of one phase grounded).","r":"NEC 110.15"},{"t":1,"c":"Art. 110 Requirements for Electrical Installations","f":"Must disconnecting means be marked?","b":"Yes. Each disconnect must be legibly marked to indicate its purpose unless the purpose is evident.","r":"NEC 110.22(A)"},{"t":1,"c":"Art. 110 Requirements for Electrical Installations","f":"Can wooden plugs be used to mount electrical equipment in masonry?","b":"No. Wooden plugs driven into holes in masonry, concrete, or plaster shall not be used.","r":"NEC 110.13(A)"},{"t":1,"c":"Art. 110 Requirements for Electrical Installations","f":"What must be done with unused openings in boxes and enclosures?","b":"They must be effectively closed to afford protection substantially equivalent to the wall of the equipment.","r":"NEC 110.12(A)"},{"t":1,"c":"Art. 110 Requirements for Electrical Installations","f":"What does 110.12 require for the quality of work?","b":"Equipment installed in a neat and workmanlike manner.","r":"NEC 110.12"},{"t":1,"c":"Art. 110 Requirements for Electrical Installations","f":"At what voltage must live parts be guarded against accidental contact?","b":"50 volts or more.","r":"NEC 110.27(A)"},{"t":1,"c":"Art. 110 Requirements for Electrical Installations","f":"Which equipment needs an arc-flash hazard warning label?","b":"In other than dwelling units, switchboards, switchgear, panelboards, industrial control panels, meter socket enclosures, and motor control centers likely to be examined, adjusted, serviced, or maintained while energized.","r":"NEC 110.16(A)"},{"t":1,"c":"Art. 110 Requirements for Electrical Installations","f":"What must be marked on service equipment other than in dwelling units?","b":"The maximum available fault current and the date the calculation was made.","r":"NEC 110.24(A)"},{"t":1,"c":"Art. 110 Requirements for Electrical Installations","f":"Working space depth for 0-150 V to ground, any condition?","b":"3 ft (900 mm).","r":"NEC Table 110.26(A)(1)"},{"t":1,"c":"Art. 200 Use and Identification of Grounded Conductors","f":"What colors identify a grounded conductor 6 AWG or smaller?","b":"White or gray outer finish, or three continuous white or gray stripes on other than green insulation.","r":"NEC 200.6(A)"},{"t":1,"c":"Art. 200 Use and Identification of Grounded Conductors","f":"How may a grounded conductor 4 AWG or larger be identified?","b":"White or gray finish, three continuous stripes, or distinctive white marking at terminations at the time of installation.","r":"NEC 200.6(B)"},{"t":1,"c":"Art. 200 Use and Identification of Grounded Conductors","f":"When can a white conductor be used as an ungrounded conductor?","b":"In cable used as a switch loop or similar, and it must be permanently reidentified (not white, gray, or green) wherever visible and accessible.","r":"NEC 200.7(C)(1)"},{"t":1,"c":"Art. 200 Use and Identification of Grounded Conductors","f":"How are grounded-conductor terminals identified?","b":"Substantially white in color (or marked W or White).","r":"NEC 200.9, 200.10"},{"t":1,"c":"Art. 200 Use and Identification of Grounded Conductors","f":"Can polarity be reversed at a connection?","b":"No. A grounded conductor shall not be attached to a terminal so as to reverse the designated polarity.","r":"NEC 200.11"},{"t":1,"c":"Art. 200 Use and Identification of Grounded Conductors","f":"Can a neutral be shared by more than one branch circuit or feeder set?","b":"Not unless specifically permitted. Neutral conductors shall not be used for more than one branch circuit, multiwire branch circuit, or set of ungrounded feeder conductors.","r":"NEC 200.4(A)"},{"t":1,"c":"Art. 200 Use and Identification of Grounded Conductors","f":"What is required when grounded conductors of different systems share a raceway or box?","b":"Each grounded conductor must be identified by system.","r":"NEC 200.6(D)"},{"t":1,"c":"Art. 210 Branch Circuits","f":"Standard branch-circuit ratings for other than individual loads?","b":"15, 20, 30, 40, and 50 amperes.","r":"NEC 210.3"},{"t":1,"c":"Art. 210 Branch Circuits","f":"Minimum copper conductor size for 15, 20, 30, 40, 50 A branch circuits?","b":"14, 12, 10, 8, and 6 AWG.","r":"NEC Table 210.24"},{"t":1,"c":"Art. 210 Branch Circuits","f":"How must a multiwire branch circuit be disconnected?","b":"Simultaneously disconnect all ungrounded conductors where the circuit originates.","r":"NEC 210.4(B)"},{"t":1,"c":"Art. 210 Branch Circuits","f":"How must multiwire branch circuit conductors be grouped in a panelboard?","b":"Ungrounded and grounded conductors grouped by cable ties or similar means in at least one location.","r":"NEC 210.4(D)"},{"t":1,"c":"Art. 210 Branch Circuits","f":"Maximum voltage for lighting and small cord-and-plug loads in dwelling units?","b":"120 volts nominal between conductors (for luminaires and cord-and-plug loads of 1440 VA or less or under 1/4 hp).","r":"NEC 210.6(A)"},{"t":1,"c":"Art. 210 Branch Circuits","f":"Branch-circuit conductor and OCPD sizing for continuous loads?","b":"125% of the continuous load plus 100% of the noncontinuous load.","r":"NEC 210.19(A)(1), 210.20(A)"},{"t":1,"c":"Art. 210 Branch Circuits","f":"Maximum cord-and-plug load on a receptacle on a multi-receptacle circuit?","b":"80% of the receptacle rating.","r":"NEC 210.21(B)(2)"},{"t":1,"c":"Art. 210 Branch Circuits","f":"What receptacle ratings may a 20 A circuit with multiple receptacles serve?","b":"15 A or 20 A receptacles.","r":"NEC Table 210.21(B)(3)"},{"t":1,"c":"Art. 210 Branch Circuits","f":"Dwelling GFCI: which areas require it for 125-250 V receptacles?","b":"Bathrooms, garages and accessory buildings, outdoors, crawl spaces, basements, kitchens, within 6 ft of sinks, boathouses, bathtubs/showers (within 6 ft), laundry areas, indoor damp and wet locations.","r":"NEC 210.8(A)"},{"t":1,"c":"Art. 210 Branch Circuits","f":"Non-dwelling GFCI locations (125-250 V receptacles)?","b":"Bathrooms, kitchens, rooftops, outdoors, sinks (within 6 ft), indoor wet locations, locker rooms with showers, garages and service bays, crawl spaces, unfinished basements, laundry areas.","r":"NEC 210.8(B)"},{"t":1,"c":"Art. 210 Branch Circuits","f":"Are dishwasher outlets in dwellings GFCI-protected?","b":"Yes, outlets that supply dishwashers in dwelling units require GFCI protection.","r":"NEC 210.8(D)"},{"t":1,"c":"Art. 210 Branch Circuits","f":"Which dwelling unit outdoor outlets need GFCI protection?","b":"Outdoor outlets on single-phase circuits of 150 V to ground or less and 50 A or less, including HVAC equipment.","r":"NEC 210.8(F)"},{"t":1,"c":"Art. 210 Branch Circuits","f":"Which dwelling rooms require AFCI protection on 15 and 20 A, 120 V circuits?","b":"Kitchens, family, dining, and living rooms, parlors, libraries, dens, bedrooms, sunrooms, recreation rooms, closets, hallways, laundry areas, or similar rooms or areas.","r":"NEC 210.12(A)"},{"t":1,"c":"Art. 210 Branch Circuits","f":"How many small-appliance branch circuits are required in a dwelling?","b":"At least two 20 A circuits for kitchen, pantry, breakfast room, and dining room receptacles.","r":"NEC 210.11(C)(1)"},{"t":1,"c":"Art. 210 Branch Circuits","f":"Required laundry branch circuit?","b":"At least one 20 A branch circuit for laundry receptacle outlets, with no other outlets.","r":"NEC 210.11(C)(2)"},{"t":1,"c":"Art. 210 Branch Circuits","f":"Required bathroom branch circuit?","b":"At least one 20 A branch circuit for bathroom receptacle outlets, with no other outlets.","r":"NEC 210.11(C)(3)"},{"t":1,"c":"Art. 215 Feeders","f":"What does Article 215 cover?","b":"Installation requirements and the size and ampacity of feeders supplying branch-circuit loads.","r":"NEC 215.1"},{"t":1,"c":"Art. 215 Feeders","f":"Feeder conductor minimum ampacity with continuous loads?","b":"125% of the continuous load plus 100% of the noncontinuous load.","r":"NEC 215.2(A)(1)"},{"t":1,"c":"Art. 215 Feeders","f":"Feeder overcurrent protection rating with continuous loads?","b":"Not less than the noncontinuous load plus 125% of the continuous load.","r":"NEC 215.3"},{"t":1,"c":"Art. 215 Feeders","f":"How many sets of feeders can share a common neutral?","b":"Two or three sets of 3-wire feeders, or two sets of 4-wire or 5-wire feeders.","r":"NEC 215.4(A)"},{"t":1,"c":"Art. 215 Feeders","f":"When is ground-fault protection of equipment required on feeders?","b":"On each feeder disconnect rated 1000 A or more on a solidly grounded wye system of more than 150 V to ground but not over 1000 V phase-to-phase.","r":"NEC 215.10"},{"t":1,"c":"Art. 215 Feeders","f":"How must feeder conductors be identified when more than one nominal voltage system is present?","b":"Ungrounded conductors identified by phase or line and system at all termination, connection, and splice points.","r":"NEC 215.12(C)"},{"t":1,"c":"Art. 215 Feeders","f":"Does a feeder need an equipment grounding conductor?","b":"Yes, where it supplies branch circuits that require one, a feeder must include or provide an equipment grounding conductor.","r":"NEC 215.6"},{"t":1,"c":"Art. 220 Branch-Circuit","f":"Dwelling general lighting load per square foot?","b":"3 VA per sq ft.","r":"NEC Table 220.12"},{"t":1,"c":"Art. 220 Branch-Circuit","f":"General lighting load for office buildings?","b":"3.5 VA per sq ft.","r":"NEC Table 220.12"},{"t":1,"c":"Art. 220 Branch-Circuit","f":"General lighting load for warehouses?","b":"0.25 VA per sq ft.","r":"NEC Table 220.12"},{"t":1,"c":"Art. 220 Branch-Circuit","f":"General lighting load for schools, stores?","b":"3 VA per sq ft each.","r":"NEC Table 220.12"},{"t":1,"c":"Art. 220 Branch-Circuit","f":"General lighting load for hospitals and restaurants?","b":"2 VA per sq ft each.","r":"NEC Table 220.12"},{"t":1,"c":"Art. 220 Branch-Circuit","f":"General lighting load for churches?","b":"1 VA per sq ft.","r":"NEC Table 220.12"},{"t":1,"c":"Art. 220 Branch-Circuit","f":"Load for each single receptacle yoke in non-dwelling occupancies?","b":"180 VA.","r":"NEC 220.14(I)"},{"t":1,"c":"Art. 220 Branch-Circuit","f":"Load for multioutlet assemblies not likely used simultaneously?","b":"Each 5 ft or fraction counts as one outlet of 180 VA.","r":"NEC 220.14(H)(1)"},{"t":1,"c":"Art. 220 Branch-Circuit","f":"Load for multioutlet assemblies likely used simultaneously?","b":"Each 1 ft or fraction counts as 180 VA.","r":"NEC 220.14(H)(2)"},{"t":1,"c":"Art. 220 Branch-Circuit","f":"Dwelling small-appliance branch circuit load?","b":"1500 VA for each of the two (or more) 20 A small-appliance circuits.","r":"NEC 220.52(A)"},{"t":1,"c":"Art. 220 Branch-Circuit","f":"Dwelling laundry circuit load?","b":"1500 VA.","r":"NEC 220.52(B)"},{"t":1,"c":"Art. 220 Branch-Circuit","f":"Dwelling lighting demand factors?","b":"First 3000 VA at 100%, 3001 to 120,000 VA at 35%, remainder over 120,000 VA at 25%.","r":"NEC Table 220.42"},{"t":1,"c":"Art. 220 Branch-Circuit","f":"Hospital lighting demand factors?","b":"First 50,000 VA at 40%, remainder at 20%.","r":"NEC Table 220.42"},{"t":1,"c":"Art. 220 Branch-Circuit","f":"Warehouse lighting demand factors?","b":"First 12,500 VA at 100%, remainder at 50%.","r":"NEC Table 220.42"},{"t":1,"c":"Art. 220 Branch-Circuit","f":"Show window lighting load?","b":"200 VA per linear foot of show window.","r":"NEC 220.43(A)"},{"t":1,"c":"Art. 220 Branch-Circuit","f":"Track lighting load (non-dwelling)?","b":"150 VA for every 2 ft of lighting track or fraction.","r":"NEC 220.43(B)"},{"t":1,"c":"Art. 225 Outside Branch Circuits and Feeders","f":"Minimum conductor size for overhead spans up to 50 ft?","b":"10 AWG copper or 8 AWG aluminum.","r":"NEC 225.6(A)(1)"},{"t":1,"c":"Art. 225 Outside Branch Circuits and Feeders","f":"Minimum conductor size for overhead spans over 50 ft?","b":"8 AWG copper or 6 AWG aluminum.","r":"NEC 225.6(A)(2)"},{"t":1,"c":"Art. 225 Outside Branch Circuits and Feeders","f":"Clearance over areas accessible to pedestrians only (150 V to ground or less)?","b":"10 ft above finished grade.","r":"NEC 225.18"},{"t":1,"c":"Art. 225 Outside Branch Circuits and Feeders","f":"Clearance over residential property and driveways (300 V to ground or less)?","b":"12 ft.","r":"NEC 225.18"},{"t":1,"c":"Art. 225 Outside Branch Circuits and Feeders","f":"Clearance over those areas when voltage exceeds 300 V to ground?","b":"15 ft.","r":"NEC 225.18"},{"t":1,"c":"Art. 225 Outside Branch Circuits and Feeders","f":"Clearance over public streets, alleys, roads, and parking areas subject to truck traffic?","b":"18 ft.","r":"NEC 225.18"},{"t":1,"c":"Art. 225 Outside Branch Circuits and Feeders","f":"Vertical clearance of overhead conductors above a roof?","b":"8 ft above the roof surface (reduced to 3 ft for roof slopes of 4 in 12 or more).","r":"NEC 225.19(A)"},{"t":1,"c":"Art. 225 Outside Branch Circuits and Feeders","f":"Clearance of open conductors from windows, doors, porches, balconies, and fire escapes?","b":"3 ft from the sides and bottom (conductors above the top of a window may be closer).","r":"NEC 225.19(D)(1)"},{"t":1,"c":"Art. 225 Outside Branch Circuits and Feeders","f":"How many supplies may a building or structure have?","b":"One feeder or branch circuit, except as permitted by 225.30(A) through (F).","r":"NEC 225.30"},{"t":1,"c":"Art. 225 Outside Branch Circuits and Feeders","f":"Maximum number of disconnects for each building supply?","b":"Six switches or six circuit breakers.","r":"NEC 225.33(A)"},{"t":1,"c":"Art. 225 Outside Branch Circuits and Feeders","f":"Where must a building disconnect be located?","b":"At a readily accessible location outside or inside nearest the point of entrance of the conductors.","r":"NEC 225.32"},{"t":1,"c":"Art. 225 Outside Branch Circuits and Feeders","f":"What type of disconnecting means is required at the building?","b":"A circuit breaker, molded-case switch, or switch suitable for use as service equipment.","r":"NEC 225.36"},{"t":1,"c":"Art. 225 Outside Branch Circuits and Feeders","f":"What identification is needed when a building has more than one feeder?","b":"A permanent plaque or directory at each feeder disconnect showing all other feeders or branch circuits, their location, and the area served.","r":"NEC 225.37"},{"t":1,"c":"Art. 225 Outside Branch Circuits and Feeders","f":"Raceway entering a building from underground distribution?","b":"It must be sealed per 300.5(G).","r":"NEC 225.27"},{"t":1,"c":"Art. 230 Services","f":"How many services may a building have?","b":"One, except as permitted in 230.2(A) through (D) (fire pumps, emergency systems, multiple occupancy, capacity, different characteristics).","r":"NEC 230.2"},{"t":1,"c":"Art. 230 Services","f":"May service conductors pass through the interior of another building?","b":"No. Service conductors supplying a building shall not pass through the interior of another building.","r":"NEC 230.3"},{"t":1,"c":"Art. 230 Services","f":"What other conductors may share a service raceway?","b":"Only service conductors, with limited exceptions such as grounding and bonding conductors.","r":"NEC 230.7"},{"t":1,"c":"Art. 230 Services","f":"Minimum overhead service conductor size?","b":"8 AWG copper or 6 AWG aluminum (12 AWG hard-drawn copper for limited loads on a single branch circuit).","r":"NEC 230.23(B)"},{"t":1,"c":"Art. 230 Services","f":"Minimum clearance of service conductors above a roof?","b":"8 ft vertical clearance above the roof surface (3 ft for 4 in 12 slopes; 18 in at overhanging edge up to 300 V).","r":"NEC 230.24(A)"},{"t":1,"c":"Art. 230 Services","f":"Service drop clearance over pedestrian-only areas (150 V to ground)?","b":"10 ft.","r":"NEC 230.24(B)(1)"},{"t":1,"c":"Art. 230 Services","f":"Service drop clearance over residential property and driveways (300 V to ground)?","b":"12 ft.","r":"NEC 230.24(B)(2)"},{"t":1,"c":"Art. 230 Services","f":"Service drop clearance over streets, alleys, and truck traffic areas?","b":"18 ft.","r":"NEC 230.24(B)(4)"},{"t":1,"c":"Art. 230 Services","f":"Minimum clearance from windows, doors, porches, and fire escapes for open service conductors?","b":"3 ft.","r":"NEC 230.9(A)"},{"t":1,"c":"Art. 230 Services","f":"Minimum height of the service-drop point of attachment?","b":"10 ft above finished grade.","r":"NEC 230.26"},{"t":1,"c":"Art. 230 Services","f":"Which conductors may attach to a service mast?","b":"Only power service-drop conductors; the mast must be adequately strong or braced.","r":"NEC 230.28"},{"t":1,"c":"Art. 230 Services","f":"Minimum ampacity of service conductors for a one-family dwelling?","b":"100 A, 3-wire.","r":"NEC 230.42(B)"},{"t":1,"c":"Art. 230 Services","f":"Support spacing for service-entrance cable?","b":"Within 12 in of the service head, gooseneck, or enclosure, and every 30 in.","r":"NEC 230.51(A)"},{"t":1,"c":"Art. 230 Services","f":"Service head requirements?","b":"Rain-tight, located above the point of attachment, with each conductor in a separately bushed opening and drip loops.","r":"NEC 230.54"},{"t":1,"c":"Art. 240 Overcurrent Protection","f":"Maximum OCPD for 14, 12, 10 AWG copper?","b":"15 A, 20 A, 30 A.","r":"NEC 240.4(D)"},{"t":1,"c":"Art. 240 Overcurrent Protection","f":"Maximum OCPD for 12 and 10 AWG aluminum or copper-clad aluminum?","b":"15 A and 25 A.","r":"NEC 240.4(D)"},{"t":1,"c":"Art. 240 Overcurrent Protection","f":"When may you round up to the next standard OCPD rating?","b":"When the conductor ampacity does not match a standard rating, the circuit is not multioutlet receptacle circuits for portable loads, and the next rating does not exceed 800 A.","r":"NEC 240.4(B)"},{"t":1,"c":"Art. 240 Overcurrent Protection","f":"OCPD for conductors protected above 800 A?","b":"The conductor ampacity must be equal to or greater than the OCPD rating.","r":"NEC 240.4(C)"},{"t":1,"c":"Art. 240 Overcurrent Protection","f":"List standard OCPD ratings through 100 A.","b":"15, 20, 25, 30, 35, 40, 45, 50, 60, 70, 80, 90, 100.","r":"NEC 240.6(A)"},{"t":1,"c":"Art. 240 Overcurrent Protection","f":"List standard OCPD ratings above 100 A.","b":"110, 125, 150, 175, 200, 225, 250, 300, 350, 400, 450, 500, 600, 700, 800, 1000, 1200, 1600, 2000, 2500, 3000, 4000, 5000, 6000.","r":"NEC 240.6(A)"},{"t":1,"c":"Art. 240 Overcurrent Protection","f":"Feeder tap of 10 ft: ampacity requirement?","b":"At least 1/10 of the rating of the overcurrent device protecting the feeder, and not less than the load.","r":"NEC 240.21(B)(1)"},{"t":1,"c":"Art. 240 Overcurrent Protection","f":"Feeder tap of 25 ft: ampacity requirement?","b":"At least 1/3 of the rating of the overcurrent device protecting the feeder.","r":"NEC 240.21(B)(2)"},{"t":1,"c":"Art. 240 Overcurrent Protection","f":"Maximum height of a switch or breaker handle?","b":"6 ft 7 in above the floor or working platform, measured to the center of the grip in its highest position.","r":"NEC 240.24(A)"},{"t":1,"c":"Art. 240 Overcurrent Protection","f":"Where must OCPDs not be located?","b":"Not in bathrooms of dwelling units, not in the vicinity of easily ignitible material such as clothes closets, and not over steps.","r":"NEC 240.24"},{"t":1,"c":"Art. 240 Overcurrent Protection","f":"Must overcurrent devices be readily accessible?","b":"Yes, with limited exceptions.","r":"NEC 240.24(A)"},{"t":1,"c":"Art. 240 Overcurrent Protection","f":"Where must a fuse or breaker be placed?","b":"In series with each ungrounded conductor.","r":"NEC 240.15(A)"},{"t":1,"c":"Art. 240 Overcurrent Protection","f":"Edison-base fuses use?","b":"Only replacements in existing installations where there is no evidence of overfusing or tampering.","r":"NEC 240.51(B)"},{"t":1,"c":"Art. 240 Overcurrent Protection","f":"Type S fuse ratings?","b":"0-15 A, 16-20 A, and 21-30 A.","r":"NEC 240.53"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"Why are electrical systems grounded?","b":"To limit voltage from lightning, line surges, or contact with higher-voltage lines, and to stabilize voltage to ground during normal operation.","r":"NEC 250.4(A)(1)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"Can the earth be used as the effective ground-fault current path?","b":"No. The earth shall not be considered an effective ground-fault current path.","r":"NEC 250.4(A)(5)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"What must the ground-fault current path be?","b":"Permanent, low impedance, and capable of carrying the maximum fault current, to facilitate operation of the overcurrent device.","r":"NEC 250.4(A)(5), 250.2"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"Where is the main bonding jumper installed?","b":"At the service, between the grounded conductor and the equipment grounding conductor (service enclosure).","r":"NEC 250.24(B)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"Is the neutral bonded to ground on the load side of the service disconnect?","b":"No. The grounded conductor shall not be connected to ground on the load side of the service disconnect.","r":"NEC 250.24(A)(5)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"Where may the grounding electrode conductor connect at a service?","b":"At any accessible point from the load end of the service drop or lateral to and including the grounded conductor terminal at the service disconnect.","r":"NEC 250.24(A)(1)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"Which conductor is grounded in single-phase 3-wire systems?","b":"The neutral (the grounded conductor).","r":"NEC 250.26"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"Where is the system bonding jumper installed for a separately derived system?","b":"At the same single point as the grounding electrode conductor connection, at the source or first disconnect.","r":"NEC 250.30(A)(1)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"Can a feeder to a second building have a neutral bonded to ground there?","b":"No for new work. With a 4-wire feeder, the neutral is isolated from the ground at the second building, and an EGC is run.","r":"NEC 250.32(B)(1)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"Which electrodes must be bonded together if present?","b":"Metal underground water pipe, building steel, concrete-encased electrode, ground ring, rod and pipe, other listed electrodes, plate electrodes.","r":"NEC 250.50, 250.52(A)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"Metal underground water pipe as an electrode: condition?","b":"Must be in direct contact with earth for 10 ft or more, and be supplemented by an additional electrode.","r":"NEC 250.52(A)(1), 250.53(D)(2)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"Concrete-encased electrode requirements?","b":"20 ft of 1/2 in minimum steel rebar, or 20 ft of bare copper 4 AWG or larger, encased in at least 2 in of concrete near the bottom of a foundation in contact with earth.","r":"NEC 250.52(A)(3)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"Ground ring requirements?","b":"At least 20 ft of bare copper 2 AWG or larger, buried at least 30 in deep, encircling the building.","r":"NEC 250.52(A)(4)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"Rod electrode minimum length?","b":"8 ft in contact with the soil.","r":"NEC 250.52(A)(5)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"Plate electrode minimum size?","b":"At least 2 sq ft exposed to soil; iron 1/4 in thick; nonferrous 0.06 in thick.","r":"NEC 250.52(A)(7)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"What may NOT be used as a grounding electrode?","b":"Metal underground gas piping and aluminum electrodes.","r":"NEC 250.52(B)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"When must a single rod, pipe, or plate be supplemented?","b":"A single electrode with more than 25 ohms resistance must be supplemented by an additional electrode.","r":"NEC 250.53(A)(2)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"Minimum spacing between rod electrodes?","b":"6 ft apart.","r":"NEC 250.53(B)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"How must a rod be driven if rock is encountered?","b":"At an oblique angle not over 45 degrees from vertical, or buried in a trench at least 30 in deep.","r":"NEC 250.53(G)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"Aluminum grounding electrode conductor restriction?","b":"Not in direct contact with masonry or earth, and not terminated within 18 in of the earth.","r":"NEC 250.64(A)"},{"t":1,"c":"Art. 250 Grounding and Bonding","f":"Physical protection of a grounding electrode conductor?","b":"6 AWG not exposed to damage may run on the surface if fastened; smaller than 6 AWG must be in conduit or cable armor.","r":"NEC 250.64(B)"},{"t":1,"c":"Art. 300 Wiring Methods","f":"What must be run together in the same raceway, cable, or trench?","b":"All conductors of the same circuit, including the equipment grounding and bonding conductors.","r":"NEC 300.3(B)"},{"t":1,"c":"Art. 300 Wiring Methods","f":"Cables through bored holes in wood framing: minimum distance from edge?","b":"1-1/4 in from the nearest edge, or protect with a steel plate or sleeve at least 1/16 in thick.","r":"NEC 300.4(A)(1)"},{"t":1,"c":"Art. 300 Wiring Methods","f":"Cables in notches in wood framing?","b":"Protect with a steel plate at least 1/16 in thick, installed before wall finish is applied.","r":"NEC 300.4(A)(2)"},{"t":1,"c":"Art. 300 Wiring Methods","f":"Minimum cover for direct-buried cables (general)?","b":"24 in.","r":"NEC Table 300.5"},{"t":1,"c":"Art. 300 Wiring Methods","f":"Minimum cover for rigid metal conduit or IMC buried?","b":"6 in.","r":"NEC Table 300.5"},{"t":1,"c":"Art. 300 Wiring Methods","f":"Minimum cover for PVC conduit buried (general)?","b":"18 in.","r":"NEC Table 300.5"},{"t":1,"c":"Art. 300 Wiring Methods","f":"Minimum cover for residential 120 V, 20 A or less GFCI-protected branch circuits?","b":"12 in.","r":"NEC Table 300.5"},{"t":1,"c":"Art. 300 Wiring Methods","f":"Protection of cables emerging from grade?","b":"Enclosed or in raceway from the minimum cover depth up to at least 8 ft above finished grade.","r":"NEC 300.5(D)(1)"},{"t":1,"c":"Art. 300 Wiring Methods","f":"What is a wet location raceway interior?","b":"The interior of raceways installed in wet locations above grade is considered a wet location.","r":"NEC 300.9"},{"t":1,"c":"Art. 300 Wiring Methods","f":"Is electrical continuity of metal raceways required?","b":"Yes. Metal raceways, cable armor, and enclosures shall be metallically joined into a continuous electrical conductor.","r":"NEC 300.10"},{"t":1,"c":"Art. 300 Wiring Methods","f":"Can raceways or cables be supported by ceiling support wires?","b":"Not by the wires of a fire-rated ceiling assembly; independent support is required, unless identified for it.","r":"NEC 300.11(A)"},{"t":1,"c":"Art. 300 Wiring Methods","f":"Splices inside raceways?","b":"Not permitted. Conductors must be continuous between outlets, boxes, or devices.","r":"NEC 300.13(A)"},{"t":1,"c":"Art. 300 Wiring Methods","f":"Device removal and the multiwire neutral?","b":"Removing a device shall not interrupt the continuity of the grounded conductor of a multiwire circuit.","r":"NEC 300.13(B)"},{"t":1,"c":"Art. 300 Wiring Methods","f":"Minimum free conductor length at outlet boxes?","b":"At least 6 in of free conductor, with at least 3 in outside the box opening.","r":"NEC 300.14"},{"t":1,"c":"Art. 310 Conductors for General Wiring","f":"Conductor materials permitted?","b":"Copper, aluminum, or copper-clad aluminum, solid or stranded.","r":"NEC 310.3(A)"},{"t":1,"c":"Art. 310 Conductors for General Wiring","f":"Smallest conductors in raceways that must be stranded?","b":"8 AWG and larger installed in raceway must be stranded, with exceptions.","r":"NEC 310.3(C)"},{"t":1,"c":"Art. 310 Conductors for General Wiring","f":"Minimum size for conductors run in parallel?","b":"1/0 AWG or larger.","r":"NEC 310.10(G)"},{"t":1,"c":"Art. 310 Conductors for General Wiring","f":"What must be identical for parallel conductors?","b":"Same length, material, size in circular mil area, insulation type, and termination method.","r":"NEC 310.10(G)"},{"t":1,"c":"Art. 310 Conductors for General Wiring","f":"Table 310.16 ambient temperature basis?","b":"30 degrees C (86 degrees F), with no more than three current-carrying conductors in a raceway or cable.","r":"NEC Table 310.16"},{"t":1,"c":"Art. 310 Conductors for General Wiring","f":"Copper 12 AWG ampacity at 60, 75, 90 degrees C?","b":"20, 25, 30 A.","r":"NEC Table 310.16"},{"t":1,"c":"Art. 310 Conductors for General Wiring","f":"Copper 10 AWG ampacity at 60, 75, 90 degrees C?","b":"30, 35, 40 A.","r":"NEC Table 310.16"},{"t":1,"c":"Art. 310 Conductors for General Wiring","f":"Copper 14 AWG ampacity at 60, 75, 90 degrees C?","b":"15, 20, 25 A.","r":"NEC Table 310.16"},{"t":1,"c":"Art. 310 Conductors for General Wiring","f":"Copper 8 AWG ampacity at 60, 75, 90 degrees C?","b":"40, 50, 55 A.","r":"NEC Table 310.16"},{"t":1,"c":"Art. 310 Conductors for General Wiring","f":"Copper 6 AWG ampacity at 60, 75, 90 degrees C?","b":"55, 65, 75 A.","r":"NEC Table 310.16"},{"t":1,"c":"Art. 310 Conductors for General Wiring","f":"Copper 4 AWG ampacity at 60, 75, 90 degrees C?","b":"70, 85, 95 A.","r":"NEC Table 310.16"},{"t":1,"c":"Art. 310 Conductors for General Wiring","f":"Copper 3 AWG ampacity at 60, 75, 90 degrees C?","b":"85, 100, 115 A.","r":"NEC Table 310.16"},{"t":1,"c":"Art. 310 Conductors for General Wiring","f":"Copper 2 AWG ampacity at 60, 75, 90 degrees C?","b":"95, 115, 130 A.","r":"NEC Table 310.16"},{"t":1,"c":"Art. 310 Conductors for General Wiring","f":"Copper 1 AWG ampacity at 60, 75, 90 degrees C?","b":"110, 130, 145 A.","r":"NEC Table 310.16"},{"t":1,"c":"Art. 312 Cabinets","f":"What does Article 312 cover?","b":"Installation and construction of cabinets, cutout boxes, and meter socket enclosures.","r":"NEC 312.1"},{"t":1,"c":"Art. 312 Cabinets","f":"Wet location enclosures: wall spacing?","b":"Enclosures in wet locations mounted on a surface must have at least 1/4 in air space between enclosure and wall.","r":"NEC 312.2"},{"t":1,"c":"Art. 312 Cabinets","f":"Flush cabinet setback in noncombustible walls?","b":"Front edge not set back more than 1/4 in from the finished surface.","r":"NEC 312.3"},{"t":1,"c":"Art. 312 Cabinets","f":"Maximum gap around cabinets in noncombustible surfaces?","b":"No more than 1/8 in at the edge of the cabinet or cutout box.","r":"NEC 312.4"},{"t":1,"c":"Art. 312 Cabinets","f":"Must cabinet openings be closed?","b":"Unused openings shall be effectively closed, and cables must be secured to the cabinet.","r":"NEC 312.5(A), (C)"},{"t":1,"c":"Art. 312 Cabinets","f":"Fill limit for wiring space in switch and OCPD enclosures?","b":"Conductors may not fill more than 40% of the cross-sectional area of the space at any cross section; splices and taps no more than 75%.","r":"NEC 312.8"},{"t":1,"c":"Art. 312 Cabinets","f":"Wire-bending space in enclosures?","b":"Must meet minimums in Table 312.6(A) according to conductor size.","r":"NEC 312.6"},{"t":1,"c":"Art. 312 Cabinets","f":"Required space in cabinets?","b":"Approved space to accommodate all conductors without crowding.","r":"NEC 312.7"},{"t":1,"c":"Art. 314 Outlet, Device, Pull, and Junction Boxes","f":"Volume allowance for 14 AWG conductor in a box?","b":"2.00 cubic inches.","r":"NEC Table 314.16(B)"},{"t":1,"c":"Art. 314 Outlet, Device, Pull, and Junction Boxes","f":"Volume allowance for 12 AWG conductor in a box?","b":"2.25 cubic inches.","r":"NEC Table 314.16(B)"},{"t":1,"c":"Art. 314 Outlet, Device, Pull, and Junction Boxes","f":"Volume allowance for 10 AWG conductor in a box?","b":"2.50 cubic inches.","r":"NEC Table 314.16(B)"},{"t":1,"c":"Art. 314 Outlet, Device, Pull, and Junction Boxes","f":"Volume allowance for 8 AWG conductor in a box?","b":"3.00 cubic inches.","r":"NEC Table 314.16(B)"},{"t":1,"c":"Art. 314 Outlet, Device, Pull, and Junction Boxes","f":"Volume allowance for 6 AWG conductor in a box?","b":"5.00 cubic inches.","r":"NEC Table 314.16(B)"},{"t":1,"c":"Art. 314 Outlet, Device, Pull, and Junction Boxes","f":"Box fill: how are devices (switch or receptacle) counted?","b":"Each yoke or strap counts as two conductors, based on the largest conductor connected to the device.","r":"NEC 314.16(B)(4)"},{"t":1,"c":"Art. 314 Outlet, Device, Pull, and Junction Boxes","f":"Box fill: how are internal cable clamps counted?","b":"One or more clamps count as a single conductor volume, based on the largest conductor in the box.","r":"NEC 314.16(B)(2)"},{"t":1,"c":"Art. 314 Outlet, Device, Pull, and Junction Boxes","f":"Box fill: how are equipment grounding conductors counted?","b":"All EGCs together count as one conductor, based on the largest EGC in the box.","r":"NEC 314.16(B)(5)"},{"t":1,"c":"Art. 314 Outlet, Device, Pull, and Junction Boxes","f":"Box fill: support fittings (fixture studs, hickeys)?","b":"Each type of fitting counts as one conductor volume, based on the largest conductor in the box.","r":"NEC 314.16(B)(3)"},{"t":1,"c":"Art. 314 Outlet, Device, Pull, and Junction Boxes","f":"Box fill: conductors that do not leave the box?","b":"A conductor no part of which leaves the box (like a pigtail) is not counted.","r":"NEC 314.16(B)(1)"},{"t":1,"c":"Art. 314 Outlet, Device, Pull, and Junction Boxes","f":"Volume of a 4 x 1-1/2 in square box?","b":"21.0 cubic inches.","r":"NEC Table 314.16(A)"},{"t":1,"c":"Art. 314 Outlet, Device, Pull, and Junction Boxes","f":"Volume of a 4 x 2-1/8 in square box?","b":"30.3 cubic inches.","r":"NEC Table 314.16(A)"},{"t":1,"c":"Art. 314 Outlet, Device, Pull, and Junction Boxes","f":"Volume of a 3 x 2 x 3-1/2 in device box?","b":"18.0 cubic inches.","r":"NEC Table 314.16(A)"},{"t":1,"c":"Art. 314 Outlet, Device, Pull, and Junction Boxes","f":"Setback of boxes in noncombustible walls?","b":"Not more than 1/4 in from the finished surface.","r":"NEC 314.20"},{"t":1,"c":"Art. 320 Armored Cable","f":"How is Type AC cable constructed?","b":"Insulated conductors in a flexible interlocked metal armor with an internal bonding strip of copper or aluminum in contact with the armor.","r":"NEC 320.100"},{"t":1,"c":"Art. 320 Armored Cable","f":"Securing Type AC cable?","b":"Within 12 in of every box, cabinet, or fitting, and at intervals not over 4.5 ft.","r":"NEC 320.30(B)"},{"t":1,"c":"Art. 320 Armored Cable","f":"Minimum bending radius for Type AC?","b":"5 times the diameter of the cable.","r":"NEC 320.24"},{"t":1,"c":"Art. 320 Armored Cable","f":"What is required at AC cable terminations?","b":"A fitting at each end, with an insulating bushing or anti-short protection between the conductors and the armor.","r":"NEC 320.40"},{"t":1,"c":"Art. 320 Armored Cable","f":"Where is Type AC permitted?","b":"Dry locations, exposed or concealed, including cable trays. It is not permitted in damp or wet locations or where exposed to corrosive conditions.","r":"NEC 320.10, 320.12"},{"t":1,"c":"Art. 320 Armored Cable","f":"Exposed AC cable routing?","b":"Must closely follow the surface of the building finish or running boards.","r":"NEC 320.15"},{"t":1,"c":"Art. 322 Flat Cable Assemblies","f":"What is Type FC?","b":"A flat cable assembly used as a branch circuit to supply suitable tap devices for lighting, small appliances, or small power loads.","r":"NEC 322.10"},{"t":1,"c":"Art. 322 Flat Cable Assemblies","f":"Conductors in Type FC cable?","b":"Special stranded 10 AWG copper conductors.","r":"NEC 322.104"},{"t":1,"c":"Art. 324 Flat Conductor Cable","f":"What is Type FCC?","b":"A flat conductor cable system for installation under carpet squares, with its own connectors and shielding.","r":"NEC 324.1, 324.10"},{"t":1,"c":"Art. 324 Flat Conductor Cable","f":"Floor covering over FCC?","b":"Carpet squares no larger than 36 in (914 mm) square.","r":"NEC 324.41"},{"t":1,"c":"Art. 324 Flat Conductor Cable","f":"Voltage and current limits for FCC branch circuits?","b":"300 V nominal between conductors and 20 A circuit rating.","r":"NEC 324.10"},{"t":1,"c":"Art. 324 Flat Conductor Cable","f":"Where is FCC not permitted?","b":"Outdoors or in wet locations, in corrosive areas, hazardous locations, and in residential, school, and hospital buildings.","r":"NEC 324.12"},{"t":1,"c":"Art. 328 Medium Voltage Cable","f":"What is Type MV cable?","b":"Single or multiconductor solid dielectric insulated cable rated 2001 volts or higher.","r":"NEC 328.2"},{"t":1,"c":"Art. 328 Medium Voltage Cable","f":"What systems may Type MV serve?","b":"Power systems rated up to 35 kV nominal.","r":"NEC 328.10"},{"t":1,"c":"Art. 330 Metal-Clad Cable","f":"Securing Type MC cable?","b":"Within 12 in of every box, cabinet, or fitting, and at intervals not over 6 ft.","r":"NEC 330.30(B)"},{"t":1,"c":"Art. 330 Metal-Clad Cable","f":"Minimum bending radius for MC with interlocked or corrugated sheath?","b":"7 times the external diameter of the sheath.","r":"NEC 330.24(B)(2)"},{"t":1,"c":"Art. 330 Metal-Clad Cable","f":"Where is Type MC permitted?","b":"Services, feeders, and branch circuits; exposed or concealed; indoors or outdoors; in cable trays; direct burial or concrete if identified.","r":"NEC 330.10"},{"t":1,"c":"Art. 330 Metal-Clad Cable","f":"MC cable fittings and terminations?","b":"Fittings must be listed and identified for MC cable; an anti-short bushing protects conductors from the armor edge.","r":"NEC 330.40"},{"t":1,"c":"Art. 330 Metal-Clad Cable","f":"Does MC cable provide an EGC?","b":"It must provide an adequate path for fault current per 250.4(A)(5); some types include a separate equipment grounding conductor.","r":"NEC 330.108"},{"t":1,"c":"Art. 332 Mineral-Insulated Metal-Sheathed Cable","f":"What is Type MI cable?","b":"Conductors insulated with highly compressed refractory mineral insulation, enclosed in a liquidtight, gastight continuous copper or alloy steel sheath.","r":"NEC 332.2"},{"t":1,"c":"Art. 332 Mineral-Insulated Metal-Sheathed Cable","f":"Securing Type MI cable?","b":"Supported at intervals not exceeding 6 ft.","r":"NEC 332.30"},{"t":1,"c":"Art. 332 Mineral-Insulated Metal-Sheathed Cable","f":"Minimum bend radius for MI up to 3/4 in diameter?","b":"5 times the external diameter of the cable.","r":"NEC 332.24"},{"t":1,"c":"Art. 332 Mineral-Insulated Metal-Sheathed Cable","f":"Minimum bend radius for MI over 3/4 up to 1 in diameter?","b":"10 times.","r":"NEC 332.24"},{"t":1,"c":"Art. 332 Mineral-Insulated Metal-Sheathed Cable","f":"Minimum bend radius for MI over 1 in diameter?","b":"12 times.","r":"NEC 332.24"},{"t":1,"c":"Art. 332 Mineral-Insulated Metal-Sheathed Cable","f":"What must be installed at MI cable ends?","b":"Moisture-proof seals (end seals), since the insulation absorbs moisture.","r":"NEC 332.40"},{"t":1,"c":"Art. 332 Mineral-Insulated Metal-Sheathed Cable","f":"Where is Type MI permitted?","b":"Services, feeders, branch circuits; wet or dry, embedded in masonry, concrete, or fill; hazardous locations as allowed.","r":"NEC 332.10"},{"t":1,"c":"Art. 334 Nonmetallic-Sheathed Cable","f":"Where is Type NM permitted?","b":"One- and two-family dwellings and their attached/detached garages and storage buildings, and multifamily or other structures of Types III, IV, and V construction.","r":"NEC 334.10"},{"t":1,"c":"Art. 334 Nonmetallic-Sheathed Cable","f":"Securing NM cable?","b":"Within 12 in of every box, cabinet, or fitting, and every 4.5 ft.","r":"NEC 334.30"},{"t":1,"c":"Art. 334 Nonmetallic-Sheathed Cable","f":"NM cable at a single-gang nonmetallic box without clamps?","b":"Secured within 8 in of the box, measured along the sheath.","r":"NEC 334.30(C)"},{"t":1,"c":"Art. 334 Nonmetallic-Sheathed Cable","f":"Minimum bending radius for NM cable?","b":"5 times the diameter of the cable.","r":"NEC 334.24"},{"t":1,"c":"Art. 334 Nonmetallic-Sheathed Cable","f":"NM ampacity temperature column?","b":"60 degrees C column of Table 310.16 (90 degrees C permitted only for derating).","r":"NEC 334.80"},{"t":1,"c":"Art. 334 Nonmetallic-Sheathed Cable","f":"Conductor sizes in NM cable?","b":"14 AWG through 2 AWG copper, or 12 AWG through 2 AWG aluminum or copper-clad aluminum.","r":"NEC 334.104"},{"t":1,"c":"Art. 334 Nonmetallic-Sheathed Cable","f":"NM cable in unfinished basements: running boards?","b":"6 AWG and larger or 3-conductor 8 AWG and larger can be secured directly to joists; smaller sizes go through bored holes or on running boards.","r":"NEC 334.15(C)"},{"t":1,"c":"Art. 334 Nonmetallic-Sheathed Cable","f":"NM insulation temperature (NM-B)?","b":"90 degrees C conductors, but the ampacity is limited to the 60 degrees C column.","r":"NEC 334.112, 334.80"},{"t":1,"c":"Art. 334 Nonmetallic-Sheathed Cable","f":"NM cable exposed work?","b":"Must closely follow the surface of the building finish and be protected from physical damage.","r":"NEC 334.15"},{"t":1,"c":"Art. 336 Power and Control Tray Cable","f":"What is Type TC cable?","b":"Factory assembly of two or more insulated conductors, with or without associated bare or covered grounding conductors, under a nonmetallic jacket, for use in cable trays.","r":"NEC 336.2"},{"t":1,"c":"Art. 336 Power and Control Tray Cable","f":"Where is Type TC permitted?","b":"In cable trays, raceways, and outdoors supported by a messenger, for power, lighting, control, and signal circuits.","r":"NEC 336.10"},{"t":1,"c":"Art. 336 Power and Control Tray Cable","f":"Conductor sizes in Type TC?","b":"18 AWG through 1000 kcmil copper.","r":"NEC 336.104"},{"t":1,"c":"Art. 336 Power and Control Tray Cable","f":"Bending radius for TC cable up to 1 in diameter?","b":"4 times the overall diameter.","r":"NEC 336.24"},{"t":1,"c":"Art. 338 Service-Entrance Cable","f":"What is Type SE used for?","b":"Service-entrance cable for above-ground services, and for interior wiring when installed per Article 334.","r":"NEC 338.10"},{"t":1,"c":"Art. 338 Service-Entrance Cable","f":"What is Type USE?","b":"Underground service-entrance cable, permitted for direct burial.","r":"NEC 338.2"},{"t":1,"c":"Art. 338 Service-Entrance Cable","f":"Can SE cable be used underground?","b":"No. Type SE shall not be used underground; use Type USE.","r":"NEC 338.12(A)"},{"t":1,"c":"Art. 338 Service-Entrance Cable","f":"Interior branch circuit wiring with SE cable?","b":"Must follow the NM installation rules of Article 334, and all circuit conductors must be insulated (no bare neutral).","r":"NEC 338.10(B)(4)"},{"t":1,"c":"Art. 338 Service-Entrance Cable","f":"Bending radius for SE and USE?","b":"5 times the diameter of the cable.","r":"NEC 338.24"},{"t":1,"c":"Art. 340 Underground Feeder and Branch-Circuit Cable","f":"What is Type UF cable?","b":"Moisture, fungus, and corrosion resistant cable permitted for direct burial.","r":"NEC 340.10"},{"t":1,"c":"Art. 340 Underground Feeder and Branch-Circuit Cable","f":"Where is Type UF permitted?","b":"Underground including direct burial, in wet, dry, or corrosive locations; also interior wiring per Article 334.","r":"NEC 340.10"},{"t":1,"c":"Art. 340 Underground Feeder and Branch-Circuit Cable","f":"Where is Type UF not permitted?","b":"As service-entrance cable, in commercial garages, theaters, hoistways, hazardous locations, embedded in concrete, or exposed to direct sunlight unless identified as sunlight resistant.","r":"NEC 340.12"},{"t":1,"c":"Art. 340 Underground Feeder and Branch-Circuit Cable","f":"Ampacity temperature column for UF?","b":"60 degrees C column.","r":"NEC 340.80"},{"t":1,"c":"Art. 340 Underground Feeder and Branch-Circuit Cable","f":"Minimum bending radius for UF?","b":"5 times the diameter of the cable.","r":"NEC 340.24"},{"t":1,"c":"Art. 340 Underground Feeder and Branch-Circuit Cable","f":"Direct-burial cover for UF cable?","b":"24 in, or 12 in for residential 120 V, 20 A or less GFCI-protected branch circuits.","r":"NEC Table 300.5"},{"t":1,"c":"Art. 342 Intermediate Metal Conduit","f":"Trade sizes of IMC?","b":"Minimum 1/2 in; maximum 4 in.","r":"NEC 342.20"},{"t":1,"c":"Art. 342 Intermediate Metal Conduit","f":"IMC support spacing?","b":"Within 3 ft of each box, conduit body, or termination, and at intervals not over 10 ft.","r":"NEC 342.30"},{"t":1,"c":"Art. 342 Intermediate Metal Conduit","f":"Maximum bends between pull points?","b":"Not more than four quarter bends (360 degrees total).","r":"NEC 342.26"},{"t":1,"c":"Art. 342 Intermediate Metal Conduit","f":"Can IMC serve as the equipment grounding conductor?","b":"Yes, IMC is an approved EGC.","r":"NEC 342.60, 250.118"},{"t":1,"c":"Art. 342 Intermediate Metal Conduit","f":"Where may IMC be used?","b":"Under all atmospheric conditions and occupancies, with corrosion protection as required.","r":"NEC 342.10"},{"t":1,"c":"Art. 342 Intermediate Metal Conduit","f":"Reaming IMC cut ends?","b":"All cut ends must be reamed or finished to remove rough edges.","r":"NEC 342.28"},{"t":1,"c":"Art. 344 Rigid Metal Conduit","f":"Trade sizes of RMC?","b":"Minimum 1/2 in; maximum 6 in.","r":"NEC 344.20"},{"t":1,"c":"Art. 344 Rigid Metal Conduit","f":"RMC support spacing?","b":"Within 3 ft of each box or termination, and at intervals not over 10 ft.","r":"NEC 344.30"},{"t":1,"c":"Art. 344 Rigid Metal Conduit","f":"Maximum support spacing for 1 in RMC with threaded couplings?","b":"12 ft.","r":"NEC Table 344.30(B)(2)"},{"t":1,"c":"Art. 344 Rigid Metal Conduit","f":"Maximum support spacing for 2 in RMC with threaded couplings?","b":"16 ft.","r":"NEC Table 344.30(B)(2)"},{"t":1,"c":"Art. 344 Rigid Metal Conduit","f":"Maximum support spacing for 3 in and larger RMC with threaded couplings?","b":"20 ft.","r":"NEC Table 344.30(B)(2)"},{"t":1,"c":"Art. 344 Rigid Metal Conduit","f":"Maximum bends in one run of RMC?","b":"Not more than four quarter bends (360 degrees) between pull points.","r":"NEC 344.26"},{"t":1,"c":"Art. 344 Rigid Metal Conduit","f":"Are running threads permitted at couplings?","b":"No. Running threads shall not be used on conduit for connection at couplings.","r":"NEC 344.42(B)"},{"t":1,"c":"Art. 344 Rigid Metal Conduit","f":"Is RMC permitted as an EGC?","b":"Yes.","r":"NEC 344.60, 250.118"},{"t":1,"c":"Art. 344 Rigid Metal Conduit","f":"Bushing required for large conductors entering a raceway?","b":"Conductors 4 AWG or larger need an identified fitting with a smooth, rounded insulating surface.","r":"NEC 300.4(G)"},{"t":1,"c":"Art. 348 Flexible Metal Conduit","f":"Trade sizes of FMC?","b":"Minimum 1/2 in (3/8 in permitted in limited cases); maximum 4 in.","r":"NEC 348.20"},{"t":1,"c":"Art. 348 Flexible Metal Conduit","f":"FMC support spacing?","b":"Within 12 in of each box or termination, and at intervals not over 4.5 ft.","r":"NEC 348.30(A)"},{"t":1,"c":"Art. 348 Flexible Metal Conduit","f":"Maximum unsupported FMC length where flexibility is required (1/2 to 1-1/4 in)?","b":"3 ft.","r":"NEC 348.30(A) Exc."},{"t":1,"c":"Art. 348 Flexible Metal Conduit","f":"Maximum unsupported FMC length for 1-1/2 to 2 in?","b":"4 ft.","r":"NEC 348.30(A) Exc."},{"t":1,"c":"Art. 348 Flexible Metal Conduit","f":"Maximum unsupported FMC length for 2-1/2 in and larger?","b":"5 ft.","r":"NEC 348.30(A) Exc."},{"t":1,"c":"Art. 348 Flexible Metal Conduit","f":"Where is FMC not permitted?","b":"Wet locations (unless conductors are listed for it), hoistways, storage-battery rooms, underground or embedded in concrete, and where subject to physical damage.","r":"NEC 348.12"},{"t":1,"c":"Art. 348 Flexible Metal Conduit","f":"Maximum bends in one FMC run?","b":"Not more than four quarter bends (360 degrees) between pull points.","r":"NEC 348.26"},{"t":1,"c":"Art. 350 Liquidtight Flexible Metal Conduit","f":"Trade sizes of LFMC?","b":"Minimum 1/2 in (3/8 in limited cases); maximum 4 in.","r":"NEC 350.20"},{"t":1,"c":"Art. 350 Liquidtight Flexible Metal Conduit","f":"LFMC support spacing?","b":"Within 12 in of each box or termination, and at intervals not over 4.5 ft.","r":"NEC 350.30"},{"t":1,"c":"Art. 350 Liquidtight Flexible Metal Conduit","f":"Where is LFMC used?","b":"Exposed or concealed where flexibility or protection from liquids, vapors, or solids is required; direct burial if marked.","r":"NEC 350.10"},{"t":1,"c":"Art. 350 Liquidtight Flexible Metal Conduit","f":"LFMC as an EGC: size limit?","b":"Only trade sizes through 1-1/4 in, with a 6 ft maximum length and OCPD limits (20 A for 3/8-1/2 in; 60 A for 3/4-1-1/4 in).","r":"NEC 250.118"},{"t":1,"c":"Art. 350 Liquidtight Flexible Metal Conduit","f":"Maximum bends in one LFMC run?","b":"Not more than four quarter bends (360 degrees).","r":"NEC 350.26"},{"t":1,"c":"Art. 352 Rigid PVC Conduit","f":"Trade sizes of PVC conduit?","b":"Minimum 1/2 in; maximum 6 in.","r":"NEC 352.20"},{"t":1,"c":"Art. 352 Rigid PVC Conduit","f":"PVC support for 1/2 to 1 in?","b":"Every 3 ft.","r":"NEC Table 352.30"},{"t":1,"c":"Art. 352 Rigid PVC Conduit","f":"PVC support for 1-1/4 to 2 in?","b":"Every 5 ft.","r":"NEC Table 352.30"},{"t":1,"c":"Art. 352 Rigid PVC Conduit","f":"PVC support for 2-1/2 to 3 in?","b":"Every 6 ft.","r":"NEC Table 352.30"},{"t":1,"c":"Art. 352 Rigid PVC Conduit","f":"PVC support for 3-1/2 to 5 in?","b":"Every 7 ft.","r":"NEC Table 352.30"},{"t":1,"c":"Art. 352 Rigid PVC Conduit","f":"PVC support for 6 in?","b":"Every 8 ft.","r":"NEC Table 352.30"},{"t":1,"c":"Art. 352 Rigid PVC Conduit","f":"PVC support near boxes?","b":"Within 3 ft of each box, conduit body, or termination.","r":"NEC 352.30(A)"},{"t":1,"c":"Art. 352 Rigid PVC Conduit","f":"PVC in areas subject to physical damage?","b":"Schedule 80 PVC is required; Schedule 40 is not for use where subject to physical damage.","r":"NEC 352.10(F), 352.12"},{"t":1,"c":"Art. 352 Rigid PVC Conduit","f":"Expansion fittings for PVC?","b":"Required where the length change from temperature is 1/4 in or more in a straight run.","r":"NEC 352.44"},{"t":1,"c":"Art. 352 Rigid PVC Conduit","f":"Is PVC conduit an EGC?","b":"No. A separate equipment grounding conductor must be installed.","r":"NEC 352.60"},{"t":1,"c":"Art. 352 Rigid PVC Conduit","f":"Maximum bends in one PVC run?","b":"Not more than four quarter bends (360 degrees) between pull points.","r":"NEC 352.26"},{"t":1,"c":"Art. 352 Rigid PVC Conduit","f":"Where must PVC bushings be installed?","b":"Where the conduit enters a box or enclosure without integral bushing, to protect the wire.","r":"NEC 352.46"},{"t":1,"c":"Art. 353 High Density Polyethylene Conduit","f":"What is HDPE conduit?","b":"A nonmetallic raceway of high density polyethylene, used underground, buried or concrete encased.","r":"NEC 353.2, 353.10"},{"t":1,"c":"Art. 353 High Density Polyethylene Conduit","f":"Trade sizes of HDPE conduit?","b":"Minimum 1/2 in; maximum 6 in.","r":"NEC 353.20"},{"t":1,"c":"Art. 353 High Density Polyethylene Conduit","f":"Where is HDPE conduit not permitted?","b":"Where exposed, and in hazardous (classified) locations.","r":"NEC 353.12"},{"t":1,"c":"Art. 353 High Density Polyethylene Conduit","f":"Is HDPE conduit an EGC?","b":"No. A separate equipment grounding conductor is required.","r":"NEC 353.60"},{"t":1,"c":"Art. 354 Nonmetallic Underground Conduit with Conductors","f":"What is NUCC?","b":"Factory-assembled nonmetallic, smooth-wall underground conduit with conductors inside.","r":"NEC 354.2"},{"t":1,"c":"Art. 354 Nonmetallic Underground Conduit with Conductors","f":"Where is NUCC permitted?","b":"Direct burial, encased in concrete, in cinder fill, and in underground corrosive locations.","r":"NEC 354.10"},{"t":1,"c":"Art. 355 Reinforced Thermosetting Resin Conduit","f":"What is RTRC?","b":"Reinforced thermosetting resin conduit, a nonmetallic raceway of fiberglass and resin.","r":"NEC 355.2"},{"t":1,"c":"Art. 355 Reinforced Thermosetting Resin Conduit","f":"Trade sizes of RTRC?","b":"Minimum 1/2 in; maximum 6 in.","r":"NEC 355.20"},{"t":1,"c":"Art. 355 Reinforced Thermosetting Resin Conduit","f":"Is RTRC an EGC?","b":"No. A separate equipment grounding conductor is required.","r":"NEC 355.60"},{"t":1,"c":"Art. 355 Reinforced Thermosetting Resin Conduit","f":"Where is RTRC permitted?","b":"Concealed, in corrosive areas, cinder fill, wet or dry locations, underground, and exposed where not subject to physical damage.","r":"NEC 355.10"},{"t":1,"c":"Art. 356 Liquidtight Flexible Nonmetallic Conduit","f":"LFNC types?","b":"LFNC-A, LFNC-B, and LFNC-C, differing in wall construction.","r":"NEC 356.2"},{"t":1,"c":"Art. 356 Liquidtight Flexible Nonmetallic Conduit","f":"Is LFNC an EGC?","b":"No. A separate equipment grounding conductor is required.","r":"NEC 356.60"},{"t":1,"c":"Art. 356 Liquidtight Flexible Nonmetallic Conduit","f":"LFNC securing?","b":"Within 12 in of each box or termination, and at intervals not over 3 ft.","r":"NEC 356.30"},{"t":1,"c":"Art. 356 Liquidtight Flexible Nonmetallic Conduit","f":"Trade sizes of LFNC?","b":"Minimum 3/8 in; maximum 4 in.","r":"NEC 356.20"},{"t":1,"c":"Art. 358 Electrical Metallic Tubing","f":"Trade sizes of EMT?","b":"Minimum 1/2 in; maximum 4 in.","r":"NEC 358.20"},{"t":1,"c":"Art. 358 Electrical Metallic Tubing","f":"EMT support spacing?","b":"Within 3 ft of each box or termination, and at intervals not over 10 ft.","r":"NEC 358.30"},{"t":1,"c":"Art. 358 Electrical Metallic Tubing","f":"Maximum bends in one EMT run?","b":"Not more than four quarter bends (360 degrees) between pull points.","r":"NEC 358.26"},{"t":1,"c":"Art. 358 Electrical Metallic Tubing","f":"Can EMT be an equipment grounding conductor?","b":"Yes.","r":"NEC 358.60, 250.118"},{"t":1,"c":"Art. 358 Electrical Metallic Tubing","f":"Can EMT be threaded?","b":"Not unless it is listed for that. Cut ends must be reamed.","r":"NEC 358.28"},{"t":1,"c":"Art. 358 Electrical Metallic Tubing","f":"Can EMT support luminaires?","b":"No, except conduit bodies no larger than the largest trade size of the tubing.","r":"NEC 358.12"},{"t":1,"c":"Art. 358 Electrical Metallic Tubing","f":"Where can EMT be used?","b":"Exposed or concealed; protected for corrosion if in direct earth or concrete contact, unless identified.","r":"NEC 358.10"},{"t":1,"c":"Arts. 342-358 Raceway Fill","f":"Raceway fill for one conductor?","b":"53% of cross-sectional area.","r":"NEC Ch. 9 Table 1"},{"t":1,"c":"Arts. 342-358 Raceway Fill","f":"Raceway fill for two conductors?","b":"31%.","r":"NEC Ch. 9 Table 1"},{"t":1,"c":"Arts. 342-358 Raceway Fill","f":"Raceway fill for three or more conductors?","b":"40%.","r":"NEC Ch. 9 Table 1"},{"t":1,"c":"Arts. 342-358 Raceway Fill","f":"Raceway fill for nipples 24 in or shorter?","b":"60% of cross-sectional area.","r":"NEC Ch. 9 Table 1 Note 4"},{"t":1,"c":"Art. 380 Multioutlet Assembly","f":"What is a multioutlet assembly?","b":"A surface, flush, or freestanding raceway designed to hold conductors and receptacles, assembled in the field or at the factory.","r":"NEC 380.2"},{"t":1,"c":"Art. 380 Multioutlet Assembly","f":"Where may multioutlet assemblies be used?","b":"In dry locations.","r":"NEC 380.10"},{"t":1,"c":"Art. 380 Multioutlet Assembly","f":"Dry wall pass-through for multioutlet assembly?","b":"May extend through dry partitions if no outlets are within the partition and the cover is accessible on both sides.","r":"NEC 380.76"},{"t":1,"c":"Art. 380 Multioutlet Assembly","f":"Load calculation for multioutlet assemblies?","b":"Each 5 ft or fraction counts as one 180 VA outlet; 1 ft or fraction if heavy simultaneous use is likely.","r":"NEC 220.14(H)"},{"t":1,"c":"Art. 392 Cable Trays","f":"What is a cable tray system?","b":"A unit or assembly of sections and fittings forming a structural system to securely fasten or support cables and raceways.","r":"NEC 392.2"},{"t":1,"c":"Art. 392 Cable Trays","f":"Name common cable tray types.","b":"Ladder, ventilated trough, ventilated channel, solid bottom, single rail, and wire mesh.","r":"NEC 392.2"},{"t":1,"c":"Art. 392 Cable Trays","f":"Minimum size of single conductors in a cable tray?","b":"1/0 AWG or larger.","r":"NEC 392.10(B)(1)"},{"t":1,"c":"Art. 392 Cable Trays","f":"Maximum rung spacing for single conductors 1/0 to 4/0 AWG in ladder trays?","b":"9 in.","r":"NEC 392.10(B)(1)(c)"},{"t":1,"c":"Art. 392 Cable Trays","f":"When may a metal cable tray be an EGC?","b":"When it is continuous, listed and marked, and meets the minimum cross-section metal area in Table 392.60(A), with bonding jumpers across discontinuities.","r":"NEC 392.60(A)"},{"t":1,"c":"Art. 392 Cable Trays","f":"Are cable trays required to be accessible?","b":"Yes. They shall be exposed and accessible, except as permitted for covered or limited-access locations.","r":"NEC 392.18"},{"t":1,"c":"Art. 400 Flexible Cords and Cables","f":"Uses permitted for flexible cords?","b":"Pendants, portable lamps and appliances, wiring of luminaires, elevators and cranes, stationary equipment for frequent interchange, and moving parts, data processing cable.","r":"NEC 400.10(A)"},{"t":1,"c":"Art. 400 Flexible Cords and Cables","f":"Name uses of flexible cords that are NOT permitted.","b":"Substitute for fixed wiring; through walls, ceilings, floors, doorways, windows; attached to building surfaces; concealed behind walls, ceilings, floors.","r":"NEC 400.12"},{"t":1,"c":"Art. 400 Flexible Cords and Cables","f":"Are splices allowed in flexible cord?","b":"No, only continuous lengths without splice or tap, except repairs of hard-service and junior hard-service cord 14 AWG and larger using proper splices.","r":"NEC 400.36"},{"t":1,"c":"Art. 400 Flexible Cords and Cables","f":"Grounding conductor color in flexible cords?","b":"Green, or green with one or more yellow stripes.","r":"NEC 400.23(A)"},{"t":1,"c":"Art. 400 Flexible Cords and Cables","f":"What does cord type S mean?","b":"Hard service cord rated 600 V; SJ is junior hard service rated 300 V.","r":"NEC Table 400.4"},{"t":1,"c":"Art. 400 Flexible Cords and Cables","f":"Letters in cord designations: J, T, O?","b":"J junior service (300 V); T thermoplastic; O oil-resistant outer jacket.","r":"NEC Table 400.4"},{"t":1,"c":"Art. 400 Flexible Cords and Cables","f":"Ampacity of flexible cords?","b":"Taken from Table 400.5(A)(1); adjustment factors apply for more than three current-carrying conductors.","r":"NEC 400.5"},{"t":1,"c":"Art. 404 Switches","f":"Three-way and four-way switches: which conductor?","b":"All switching must be done in the ungrounded circuit conductor only.","r":"NEC 404.2(A)"},{"t":1,"c":"Art. 404 Switches","f":"Switch disconnecting the grounded conductor?","b":"Not allowed unless it simultaneously disconnects all conductors, or the grounded one cannot open before the ungrounded conductors.","r":"NEC 404.2(B)"},{"t":1,"c":"Art. 404 Switches","f":"Grounded conductor at switch locations?","b":"Required where switches control lighting loads, with specific exceptions (such as raceways with room for a future neutral).","r":"NEC 404.2(C)"},{"t":1,"c":"Art. 404 Switches","f":"Maximum height of switch handles?","b":"6 ft 7 in above floor or working platform (center of grip at its highest position).","r":"NEC 404.8(A)"},{"t":1,"c":"Art. 404 Switches","f":"Switch ON and OFF indication?","b":"Must be marked; where the handle moves vertically, up is ON.","r":"NEC 404.7"},{"t":1,"c":"Art. 404 Switches","f":"Grounding of snap switches?","b":"Snap switches, including dimmers, must be effectively grounded and bonded to the box by an EGC.","r":"NEC 404.9(B)"},{"t":1,"c":"Art. 404 Switches","f":"AC general-use snap switch: motor load limit?","b":"Motor loads must not exceed 80% of the switch's ampere rating at rated voltage.","r":"NEC 404.14(A)"},{"t":1,"c":"Art. 404 Switches","f":"Marking for 20 A or less switches connected to aluminum conductors?","b":"Marked CO/ALR.","r":"NEC 404.14(C)"},{"t":1,"c":"Art. 404 Switches","f":"AC-DC general-use switch: inductive load limit?","b":"Inductive loads must not exceed 50% of ampere rating at the applied voltage.","r":"NEC 404.14(B)"},{"t":1,"c":"Art. 406 Receptacles","f":"Receptacles on 15 and 20 A branch circuits: type?","b":"Must be of the grounding type.","r":"NEC 406.4(A)"},{"t":1,"c":"Art. 406 Receptacles","f":"Replacement where no EGC exists: options?","b":"Nongrounding-type receptacle, GFCI-type receptacle marked 'No Equipment Ground,' or a grounding-type receptacle protected by GFCI marked 'GFCI Protected' and 'No Equipment Ground.'","r":"NEC 406.4(D)(2)"},{"t":1,"c":"Art. 406 Receptacles","f":"Tamper-resistant receptacles: where are they required?","b":"125 V, 15 and 20 A nonlocking receptacles in dwelling units, guest rooms, child care and school facilities, dormitories, and similar occupancies.","r":"NEC 406.12"},{"t":1,"c":"Art. 406 Receptacles","f":"Receptacles in countertops?","b":"Not in a face-up position unless a listed countertop receptacle assembly.","r":"NEC 406.5(E)"},{"t":1,"c":"Art. 406 Receptacles","f":"Receptacle location relative to bathtub or shower?","b":"Not within a zone 3 ft horizontally and 8 ft vertically from the top of the tub rim or shower threshold.","r":"NEC 406.9(C)"},{"t":1,"c":"Art. 406 Receptacles","f":"Receptacles in damp locations?","b":"Enclosure must be weatherproof when the receptacle is covered (plug not inserted).","r":"NEC 406.9(A)"},{"t":1,"c":"Art. 406 Receptacles","f":"Receptacles in wet locations (15/20 A, 125/250 V)?","b":"Enclosure must be weatherproof whether or not a plug is inserted (in-use cover).","r":"NEC 406.9(B)(1)"},{"t":1,"c":"Art. 406 Receptacles","f":"Receptacles controlled by automatic means (occupancy sensors)?","b":"Must be permanently marked with a symbol and visible after installation.","r":"NEC 406.3(E)"},{"t":1,"c":"Art. 408 Switchboards, Switchgear, and Panelboards","f":"Define a panelboard.","b":"A single panel or group of panel units with buses and overcurrent devices, designed to be placed in a cabinet or cutout box against a wall, and accessible only from the front.","r":"NEC 100"},{"t":1,"c":"Art. 408 Switchboards, Switchgear, and Panelboards","f":"Phase arrangement of busbars?","b":"A, B, C from front to back, top to bottom, or left to right; B phase is the high leg on a 4-wire delta.","r":"NEC 408.3(F)"},{"t":1,"c":"Art. 408 Switchboards, Switchgear, and Panelboards","f":"High-leg marking in panelboards?","b":"The higher-voltage phase (B) is identified by orange color or other effective marking.","r":"NEC 408.3(F)"},{"t":1,"c":"Art. 408 Switchboards, Switchgear, and Panelboards","f":"Circuit directory requirement?","b":"Every circuit and modification must be legibly identified with a clear, specific purpose; not dependent on transient conditions of occupancy.","r":"NEC 408.4(A)"},{"t":1,"c":"Art. 408 Switchboards, Switchgear, and Panelboards","f":"Source marking for panelboards?","b":"In other than one- and two-family dwellings, panelboards fed by a feeder must be marked to show where the power originates.","r":"NEC 408.4(B)"},{"t":1,"c":"Art. 408 Switchboards, Switchgear, and Panelboards","f":"Panelboard rating and OCPD rule?","b":"Each panelboard shall be protected by an overcurrent device rated not greater than the panelboard rating.","r":"NEC 408.36"},{"t":1,"c":"Art. 408 Switchboards, Switchgear, and Panelboards","f":"Panelboard enclosures: dead-front?","b":"Panelboards shall be dead-front and mounted in cabinets or enclosures designed for the purpose.","r":"NEC 408.38"},{"t":1,"c":"Art. 408 Switchboards, Switchgear, and Panelboards","f":"Panelboard grounding?","b":"Metal cabinets are connected to an EGC; an EGC terminal bar is bonded to the cabinet; the neutral bar is isolated except at the service.","r":"NEC 408.40"},{"t":1,"c":"Art. 408 Switchboards, Switchgear, and Panelboards","f":"Grounded conductor terminations at panelboards?","b":"Each grounded conductor terminates in an individual terminal not used for another conductor (unless identified).","r":"NEC 408.41"},{"t":1,"c":"Art. 408 Switchboards, Switchgear, and Panelboards","f":"Panelboard orientation?","b":"Shall not be installed in a face-up or face-down orientation.","r":"NEC 408.43"},{"t":1,"c":"Art. 408 Switchboards, Switchgear, and Panelboards","f":"Limits on overcurrent devices in panelboards?","b":"Physical means must prevent installing more overcurrent devices than the panelboard is rated and listed for.","r":"NEC 408.54"},{"t":1,"c":"Art. 408 Switchboards, Switchgear, and Panelboards","f":"Minimum rating of a panelboard?","b":"Not less than the minimum feeder capacity required for the load calculated under Article 220.","r":"NEC 408.30"},{"t":1,"c":"Art. 410 Luminaires, Lampholders, and Lamps","f":"Luminaire zone near bathtubs and showers?","b":"No cord-connected, hanging, pendant, track, or paddle fan parts within 3 ft horizontally and 8 ft vertically from the tub rim or shower threshold.","r":"NEC 410.10(D)"},{"t":1,"c":"Art. 410 Luminaires, Lampholders, and Lamps","f":"Luminaires in wet and damp locations?","b":"Installed so water cannot enter or accumulate; marked 'Suitable for Wet Locations' or 'Suitable for Damp Locations' as appropriate.","r":"NEC 410.10(A)"},{"t":1,"c":"Art. 410 Luminaires, Lampholders, and Lamps","f":"Closet storage space (clothes closets)?","b":"Floor to 6 ft or the highest rod, and 24 in from sides and back, continuing up at 12 in or shelf width (whichever is greater) to the ceiling.","r":"NEC 410.2, 410.16(A)"},{"t":1,"c":"Art. 410 Luminaires, Lampholders, and Lamps","f":"Luminaires not permitted in closets?","b":"Incandescent luminaires with open or partially enclosed lamps, and pendant luminaires or lampholders.","r":"NEC 410.16(B)"},{"t":1,"c":"Art. 410 Luminaires, Lampholders, and Lamps","f":"Closet clearance for surface-mounted incandescent or LED luminaires?","b":"12 in from the nearest point of the storage space.","r":"NEC 410.16(C)(1)"},{"t":1,"c":"Art. 410 Luminaires, Lampholders, and Lamps","f":"Closet clearance for surface-mounted fluorescent luminaires?","b":"6 in from the storage space.","r":"NEC 410.16(C)(2)"},{"t":1,"c":"Art. 410 Luminaires, Lampholders, and Lamps","f":"Closet clearance for recessed luminaires?","b":"6 in from the storage space.","r":"NEC 410.16(C)(3), (4)"},{"t":1,"c":"Art. 410 Luminaires, Lampholders, and Lamps","f":"Suspended ceiling luminaire support?","b":"Framing members must be securely fastened to each other and to the structure; luminaires fastened to the framing by mechanical means (bolts, screws, rivets, or listed clips).","r":"NEC 410.36(B)"},{"t":1,"c":"Art. 410 Luminaires, Lampholders, and Lamps","f":"Recessed luminaire clearance from combustibles?","b":"1/2 in, unless identified for contact.","r":"NEC 410.116(A)(1)"},{"t":1,"c":"Art. 410 Luminaires, Lampholders, and Lamps","f":"Track lighting: where is it NOT permitted?","b":"Where subject to physical damage, wet or damp, corrosive, concealed, through walls, within tub/shower zones, or in hazardous areas.","r":"NEC 410.151(C)"},{"t":1,"c":"Art. 410 Luminaires, Lampholders, and Lamps","f":"Track lighting: minimum height above floor?","b":"5 ft, unless protected from damage or operating at 30 V or less.","r":"NEC 410.151(C)(8)"},{"t":1,"c":"Art. 410 Luminaires, Lampholders, and Lamps","f":"Track lighting: fastening?","b":"A section of 4 ft or shorter needs two supports; continuous rows need one additional support for each 4 ft section.","r":"NEC 410.154"},{"t":1,"c":"Art. 410 Luminaires, Lampholders, and Lamps","f":"Luminaire exposed metal parts?","b":"Must be connected to an equipment grounding conductor.","r":"NEC 410.42"},{"t":1,"c":"Art. 422 Appliances","f":"Branch circuit rating for an individual appliance?","b":"Not less than the marked rating of the appliance.","r":"NEC 422.10(A)"},{"t":1,"c":"Art. 422 Appliances","f":"Storage-type water heater of 120 gallons or less: circuit sizing?","b":"Branch circuit rating at least 125% of the nameplate rating (treated as a continuous load).","r":"NEC 422.13"},{"t":1,"c":"Art. 422 Appliances","f":"OCPD for a non-motor appliance rated over 13.3 A with no marked OCPD?","b":"Not over 150% of the appliance rating.","r":"NEC 422.11(E)(3)"},{"t":1,"c":"Art. 422 Appliances","f":"Cord length for a food waste disposer (cord-and-plug)?","b":"At least 18 in and no more than 36 in.","r":"NEC 422.16(B)(1)"},{"t":1,"c":"Art. 422 Appliances","f":"Cord length for built-in dishwashers and trash compactors?","b":"3 ft to 4 ft, measured from the back of the appliance.","r":"NEC 422.16(B)(2)"},{"t":1,"c":"Art. 422 Appliances","f":"Disconnect for a permanently connected appliance rated 300 VA or less (or 1/8 hp)?","b":"The branch-circuit switch or circuit breaker can serve as the disconnecting means.","r":"NEC 422.31(A)"},{"t":1,"c":"Art. 422 Appliances","f":"Disconnect for permanently connected appliances over 300 VA?","b":"A disconnect within sight of the appliance or capable of being locked in the open position.","r":"NEC 422.31(B)"},{"t":1,"c":"Art. 422 Appliances","f":"Cord-and-plug appliances: disconnecting means?","b":"The attachment plug and receptacle may serve as the disconnecting means.","r":"NEC 422.33"},{"t":1,"c":"Art. 422 Appliances","f":"Which cord-and-plug appliances need GFCI protection?","b":"Automotive vacuums, drinking water coolers, high-pressure spray washers, tire inflation machines, vending machines, among others.","r":"NEC 422.5(A)"},{"t":1,"c":"Art. 422 Appliances","f":"Required appliance nameplate information?","b":"Identifying name and rating in volts and amperes, or volts and watts.","r":"NEC 422.60"},{"t":1,"c":"Art. 424 Fixed Electric Space-Heating Equipment","f":"Branch circuit sizing for fixed electric heating?","b":"Branch-circuit conductors and overcurrent devices at least 125% of the heating load (including motors).","r":"NEC 424.3(B)"},{"t":1,"c":"Art. 424 Fixed Electric Space-Heating Equipment","f":"Resistance heating element subdivision?","b":"Equipment over 48 A must have elements subdivided into loads of 48 A or less, each protected at not more than 60 A.","r":"NEC 424.22(B)"},{"t":1,"c":"Art. 424 Fixed Electric Space-Heating Equipment","f":"Heating cable separation from surface luminaire boxes?","b":"At least 8 in from the edge of outlet and junction boxes used for surface luminaires.","r":"NEC 424.39"},{"t":1,"c":"Art. 424 Fixed Electric Space-Heating Equipment","f":"Heating cable separation from recessed luminaires and openings?","b":"At least 2 in.","r":"NEC 424.39"},{"t":1,"c":"Art. 424 Fixed Electric Space-Heating Equipment","f":"Spacing between adjacent runs of heating cable?","b":"Not closer than 1-1/2 in on centers.","r":"NEC 424.41(D)"},{"t":1,"c":"Art. 424 Fixed Electric Space-Heating Equipment","f":"GFCI protection for heated floors?","b":"Required for electric heating cables in floors of bathrooms, kitchens, and hydromassage tub locations.","r":"NEC 424.44(G)"},{"t":1,"c":"Art. 424 Fixed Electric Space-Heating Equipment","f":"Baseboard heaters and receptacles?","b":"Receptacle outlets may be installed above a baseboard heater only if the heater is identified for use with them.","r":"NEC 424.9"},{"t":1,"c":"Art. 430 Motors, Motor Circuits, and Controllers","f":"Which current is used to size motor branch circuits conductors and protection?","b":"The full-load current from NEC Tables 430.247 through 430.250, not the nameplate.","r":"NEC 430.6(A)(1)"},{"t":1,"c":"Art. 430 Motors, Motor Circuits, and Controllers","f":"Which current is used for motor overload protection?","b":"The nameplate full-load current (FLA).","r":"NEC 430.6(A)(2)"},{"t":1,"c":"Art. 430 Motors, Motor Circuits, and Controllers","f":"Branch-circuit conductor size for a single continuous-duty motor?","b":"125% of the motor full-load current.","r":"NEC 430.22"},{"t":1,"c":"Art. 430 Motors, Motor Circuits, and Controllers","f":"Conductor size for several motors on a feeder?","b":"125% of the largest motor FLC plus the sum of the FLCs of the other motors.","r":"NEC 430.24"},{"t":1,"c":"Art. 430 Motors, Motor Circuits, and Controllers","f":"Separate overload device for motors with service factor 1.15 or more?","b":"Not over 125% of nameplate FLA.","r":"NEC 430.32(A)(1)"},{"t":1,"c":"Art. 430 Motors, Motor Circuits, and Controllers","f":"Overload device for motors with temperature rise 40 degrees C or less?","b":"Not over 125% of nameplate FLA.","r":"NEC 430.32(A)(1)"},{"t":1,"c":"Art. 430 Motors, Motor Circuits, and Controllers","f":"Overload device for all other motors?","b":"Not over 115% of nameplate FLA.","r":"NEC 430.32(A)(1)"},{"t":1,"c":"Art. 430 Motors, Motor Circuits, and Controllers","f":"Short-circuit protection: nontime-delay fuse maximum?","b":"300% of full-load current.","r":"NEC Table 430.52"},{"t":1,"c":"Art. 430 Motors, Motor Circuits, and Controllers","f":"Short-circuit protection: dual-element time-delay fuse maximum?","b":"175% of FLC.","r":"NEC Table 430.52"},{"t":1,"c":"Art. 430 Motors, Motor Circuits, and Controllers","f":"Short-circuit protection: inverse time circuit breaker maximum?","b":"250% of FLC.","r":"NEC Table 430.52"},{"t":1,"c":"Art. 430 Motors, Motor Circuits, and Controllers","f":"Short-circuit protection: instantaneous-trip breaker maximum?","b":"800% of FLC.","r":"NEC Table 430.52"},{"t":1,"c":"Art. 430 Motors, Motor Circuits, and Controllers","f":"If the protection is too small to start the motor, how high may it go?","b":"Nontime-delay fuses 400%, time-delay fuses 225%, inverse time breakers 400% (FLC 100 A or less) or 300% (over 100 A).","r":"NEC 430.52(C)(1) Exc. 2"},{"t":1,"c":"Art. 430 Motors, Motor Circuits, and Controllers","f":"Feeder protection for several motors?","b":"The largest branch-circuit short-circuit device of any motor plus the sum of the FLCs of the other motors.","r":"NEC 430.62(A)"},{"t":1,"c":"Art. 430 Motors, Motor Circuits, and Controllers","f":"Minimum ampere rating of a motor disconnecting means?","b":"At least 115% of the motor full-load current.","r":"NEC 430.110"},{"t":1,"c":"Art. 430 Motors, Motor Circuits, and Controllers","f":"What does 'in sight from' mean?","b":"Visible and not more than 50 ft distant.","r":"NEC Art. 100"},{"t":1,"c":"Art. 430 Motors, Motor Circuits, and Controllers","f":"Where must the motor controller disconnect be located?","b":"Within sight of the controller location.","r":"NEC 430.102(A)"},{"t":1,"c":"Art. 440 Air-Conditioning and Refrigerating Equipment","f":"Hermetic motor-compressor nameplate must show?","b":"Rated-load current (RLC), locked-rotor current, voltage, frequency, phases, and branch-circuit selection current if different.","r":"NEC 440.4(A)"},{"t":1,"c":"Art. 440 Air-Conditioning and Refrigerating Equipment","f":"Multimotor equipment nameplate markings?","b":"Minimum circuit ampacity (MCA) and maximum overcurrent protective device (MOCP).","r":"NEC 440.4(B)"},{"t":1,"c":"Art. 440 Air-Conditioning and Refrigerating Equipment","f":"Sizing basis for motor-compressor circuits?","b":"The marked rated-load current or branch-circuit selection current, whichever is greater, not horsepower.","r":"NEC 440.6(A)"},{"t":1,"c":"Art. 440 Air-Conditioning and Refrigerating Equipment","f":"Minimum disconnecting means rating for a motor-compressor?","b":"At least 115% of the nameplate RLC or branch-circuit selection current, whichever is greater.","r":"NEC 440.12(A)"},{"t":1,"c":"Art. 440 Air-Conditioning and Refrigerating Equipment","f":"Location of the air conditioner disconnect?","b":"Within sight from and readily accessible from the equipment; may be on or within the unit.","r":"NEC 440.14"},{"t":1,"c":"Art. 440 Air-Conditioning and Refrigerating Equipment","f":"Branch-circuit conductors for a single motor-compressor?","b":"At least 125% of the RLC or branch-circuit selection current, whichever is greater.","r":"NEC 440.32"},{"t":1,"c":"Art. 440 Air-Conditioning and Refrigerating Equipment","f":"Maximum short-circuit and ground-fault protection for a motor-compressor?","b":"175% of RLC or branch-circuit selection current, whichever is greater; up to 225% if needed to start.","r":"NEC 440.22(A)"},{"t":1,"c":"Art. 440 Air-Conditioning and Refrigerating Equipment","f":"Room air conditioner on its own circuit (cord-and-plug)?","b":"Load must not exceed 80% of the branch-circuit rating.","r":"NEC 440.62(B)"},{"t":1,"c":"Art. 440 Air-Conditioning and Refrigerating Equipment","f":"Room air conditioner sharing a circuit with lights and receptacles?","b":"Air conditioner rating must not exceed 50% of the branch-circuit rating.","r":"NEC 440.62(C)"},{"t":1,"c":"Art. 440 Air-Conditioning and Refrigerating Equipment","f":"Maximum cord length for a room air conditioner?","b":"10 ft for 120 V; 6 ft for 208 or 240 V.","r":"NEC 440.64"},{"t":1,"c":"Art. 440 Air-Conditioning and Refrigerating Equipment","f":"Room air conditioner cord-and-plug protection?","b":"Single-phase cord-and-plug room air conditioners require LCDI or AFCI protection.","r":"NEC 440.65"},{"t":1,"c":"Art. 445 Generators","f":"Generator conductor ampacity from terminals to first distribution device?","b":"At least 115% of the generator nameplate current rating.","r":"NEC 445.13(A)"},{"t":1,"c":"Art. 445 Generators","f":"Overload protection of constant-voltage generators?","b":"By inherent design, circuit breakers, fuses, or other acceptable overcurrent protection.","r":"NEC 445.12"},{"t":1,"c":"Art. 445 Generators","f":"Disconnecting means for generators?","b":"Generator and all protective devices and controls must be able to be disconnected from the circuits it supplies.","r":"NEC 445.18(A)"},{"t":1,"c":"Art. 445 Generators","f":"Shutdown of the prime mover?","b":"Generators must have provisions to shut down the prime mover.","r":"NEC 445.18(B)"},{"t":1,"c":"Art. 445 Generators","f":"GFCI on portable generators?","b":"125 V, 15 and 20 A receptacles on portable generators of 15 kW or smaller need listed GFCI protection.","r":"NEC 445.20"},{"t":1,"c":"Art. 445 Generators","f":"Generator nameplate information?","b":"Manufacturer, frequency, phases, kW or kVA rating, power factor, volts and amperes, ambient, temperature rise, insulation class, and time rating.","r":"NEC 445.11"},{"t":1,"c":"Art. 445 Generators","f":"Live parts of generators operating over 50 V?","b":"Must not be exposed to accidental contact where accessible to unqualified persons.","r":"NEC 445.14"},{"t":1,"c":"Art. 450 Transformers","f":"Primary-only protection for transformers 1000 V or less (primary 9 A or more)?","b":"Not over 125% of rated primary current.","r":"NEC Table 450.3(B)"},{"t":1,"c":"Art. 450 Transformers","f":"Primary-only protection if primary current is under 9 A?","b":"Not over 167% of rated primary current.","r":"NEC Table 450.3(B)"},{"t":1,"c":"Art. 450 Transformers","f":"Primary-only protection if primary current is under 2 A?","b":"Not over 300% of rated primary current.","r":"NEC Table 450.3(B)"},{"t":1,"c":"Art. 450 Transformers","f":"Primary protection when secondary protection is also provided?","b":"Not over 250% of rated primary current.","r":"NEC Table 450.3(B)"},{"t":1,"c":"Art. 450 Transformers","f":"Secondary protection (secondary current 9 A or more)?","b":"Not over 125% of rated secondary current.","r":"NEC Table 450.3(B)"},{"t":1,"c":"Art. 450 Transformers","f":"Disconnecting means for transformers?","b":"Located in sight of the transformer unless its location is field marked on the transformer.","r":"NEC 450.14"},{"t":1,"c":"Art. 450 Transformers","f":"Ventilation of transformers?","b":"Ventilating openings must not be blocked by walls or obstructions; required clearances are marked on the transformer.","r":"NEC 450.9"},{"t":1,"c":"Art. 450 Transformers","f":"Dry-type transformer in a hollow space?","b":"Allowed for 1000 V or less and 50 kVA or less, if accessible and with adequate ventilation.","r":"NEC 450.13(B)"},{"t":1,"c":"Art. 450 Transformers","f":"Dry-type transformers 112.5 kVA or less indoors?","b":"Separate from combustible material by at least 12 in unless a fire-resistant, heat-insulated barrier is used.","r":"NEC 450.21(A)"},{"t":1,"c":"Art. 450 Transformers","f":"Dry-type transformers over 112.5 kVA indoors?","b":"Installed in a transformer room of fire-resistant construction rated 1 hour (with exceptions).","r":"NEC 450.21(B)"},{"t":1,"c":"Art. 450 Transformers","f":"Vault construction for oil-insulated transformers?","b":"Walls, roof, and floors with a minimum fire resistance of 3 hours.","r":"NEC 450.42"},{"t":1,"c":"Art. 450 Transformers","f":"Nameplate of a transformer must include?","b":"Manufacturer, kVA, frequency, primary and secondary voltage, impedance (25 kVA and larger), clearances, and insulation temperature class.","r":"NEC 450.11"},{"t":1,"c":"Art. 450 Transformers","f":"Transformer exposed metal parts?","b":"Noncurrent-carrying metal parts must be grounded.","r":"NEC 450.10"},{"t":1,"c":"Art. 480 Stationary Standby Batteries","f":"What does Article 480 cover?","b":"All stationary installations of storage batteries.","r":"NEC 480.1"},{"t":1,"c":"Art. 480 Stationary Standby Batteries","f":"What is a storage battery?","b":"A battery made of one or more rechargeable cells of the lead-acid, nickel-cadmium, or other rechargeable electrochemical types.","r":"NEC 480.2"},{"t":1,"c":"Art. 480 Stationary Standby Batteries","f":"What is a sealed cell or battery?","b":"One with no provision for routine addition of water or electrolyte, or for external measurement of electrolyte specific gravity.","r":"NEC 480.2"},{"t":1,"c":"Art. 480 Stationary Standby Batteries","f":"What is a valve-regulated lead-acid (VRLA) battery?","b":"A sealed lead-acid battery with a valve that opens to vent the cell when internal pressure exceeds ambient by a set amount.","r":"NEC 480.2"},{"t":1,"c":"Art. 480 Stationary Standby Batteries","f":"Must storage batteries be listed?","b":"Storage batteries and battery management equipment must be listed (or otherwise approved per Article 480).","r":"NEC 480.3"},{"t":1,"c":"Art. 480 Stationary Standby Batteries","f":"Disconnecting means for stationary batteries?","b":"A disconnecting means is required for all ungrounded conductors derived from a stationary battery system over 30 V.","r":"NEC 480.7"},{"t":1,"c":"Art. 480 Stationary Standby Batteries","f":"Ventilation of battery locations?","b":"Provisions must ensure sufficient diffusion and ventilation of gases to prevent accumulation of an explosive mixture.","r":"NEC 480.10(A)"},{"t":1,"c":"Art. 480 Stationary Standby Batteries","f":"Working space about battery systems?","b":"Must comply with 110.26, measured from the edge of the battery rack.","r":"NEC 480.10(C)"},{"t":1,"c":"Art. 500 Hazardous Locations - General","f":"What does Class I cover?","b":"Locations where flammable gases, flammable liquid-produced vapors, or combustible liquid-produced vapors may be present in ignitible concentrations.","r":"NEC 500.5(B)"},{"t":1,"c":"Art. 500 Hazardous Locations - General","f":"What does Class II cover?","b":"Locations that are hazardous because of the presence of combustible dust.","r":"NEC 500.5(C)"},{"t":1,"c":"Art. 500 Hazardous Locations - General","f":"What does Class III cover?","b":"Locations hazardous because of easily ignitible fibers or flyings, but not likely suspended in the air in ignitible quantities.","r":"NEC 500.5(D)"},{"t":1,"c":"Art. 500 Hazardous Locations - General","f":"Division 1 versus Division 2?","b":"Division 1: hazard exists under normal operating conditions (or frequent repair/leakage). Division 2: hazard exists only under abnormal conditions, such as container failure.","r":"NEC 500.5"},{"t":1,"c":"Art. 500 Hazardous Locations - General","f":"Class I Group A material?","b":"Acetylene.","r":"NEC 500.6(A)"},{"t":1,"c":"Art. 500 Hazardous Locations - General","f":"Class I Group B materials?","b":"Hydrogen and similar gases (butadiene, ethylene oxide, propylene oxide).","r":"NEC 500.6(A)"},{"t":1,"c":"Art. 500 Hazardous Locations - General","f":"Class I Group C materials?","b":"Ethylene, cyclopropane, ethyl ether.","r":"NEC 500.6(A)"},{"t":1,"c":"Art. 500 Hazardous Locations - General","f":"Class I Group D materials?","b":"Gasoline, acetone, ammonia, benzene, butane, ethanol, methane (natural gas), propane.","r":"NEC 500.6(A)"},{"t":1,"c":"Art. 500 Hazardous Locations - General","f":"Class II Group E?","b":"Combustible metal dusts, such as aluminum and magnesium.","r":"NEC 500.6(B)"},{"t":1,"c":"Art. 500 Hazardous Locations - General","f":"Class II Group F?","b":"Carbonaceous dusts, such as coal, carbon black, and coke.","r":"NEC 500.6(B)"},{"t":1,"c":"Art. 500 Hazardous Locations - General","f":"Class II Group G?","b":"Other combustible dusts, such as flour, grain, starch, wood, and plastic.","r":"NEC 500.6(B)"},{"t":1,"c":"Art. 500 Hazardous Locations - General","f":"What must be marked on hazardous-location equipment?","b":"Class, division (or zone), group, and the operating temperature or temperature class.","r":"NEC 500.8(C)"},{"t":1,"c":"Art. 500 Hazardous Locations - General","f":"Threaded conduit engagement at explosionproof equipment?","b":"At least five threads fully engaged.","r":"NEC 500.8(E)"},{"t":1,"c":"Art. 501 Class I Locations","f":"Class I, Division 1 wiring methods?","b":"Threaded rigid metal conduit or threaded steel IMC, Type MI cable with listed fittings, or Type MC-HL cable with listed fittings (where permitted).","r":"NEC 501.10(A)"},{"t":1,"c":"Art. 501 Class I Locations","f":"Additional wiring methods permitted in Class I, Division 2?","b":"Rigid metal conduit, IMC, enclosed gasketed busways and wireways, Type MC, PLTC, and ITC cables, among others.","r":"NEC 501.10(B)"},{"t":1,"c":"Art. 501 Class I Locations","f":"When is a conduit seal required at an enclosure?","b":"When the enclosure contains arcing or sparking devices (switches, breakers, relays), or when the entry is trade size 2 or larger and the enclosure has terminals, splices, or taps.","r":"NEC 501.15(A)(1)"},{"t":1,"c":"Art. 501 Class I Locations","f":"Maximum distance of a seal from the enclosure?","b":"18 in.","r":"NEC 501.15(A)(1)"},{"t":1,"c":"Art. 501 Class I Locations","f":"Minimum thickness of sealing compound?","b":"Not less than the trade size of the sealing fitting and in no case less than 5/8 in.","r":"NEC 501.15(C)(3)"},{"t":1,"c":"Art. 501 Class I Locations","f":"Fill limit in a sealing fitting?","b":"Conductors should not fill more than 25% of the cross section of the same-size rigid metal conduit unless the seal is identified for more.","r":"NEC 501.15(C)(6)"},{"t":1,"c":"Art. 501 Class I Locations","f":"Can splices or taps be made in seal fittings?","b":"No. Splices and taps shall not be made in fittings intended only for sealing.","r":"NEC 501.15(C)(4)"},{"t":1,"c":"Art. 501 Class I Locations","f":"Bonding in Class I locations?","b":"Locknut-bushing and double-locknut connections cannot be relied on; use bonding jumpers or equivalent devices.","r":"NEC 501.30(A)"},{"t":1,"c":"Art. 501 Class I Locations","f":"Flexible cord in Class I, Division 1?","b":"Extra-hard-usage cord, with an additional grounding conductor, listed for the location, with listed seals.","r":"NEC 501.140(A)"},{"t":1,"c":"Art. 502 Class II Locations","f":"Class II, Division 1 wiring methods?","b":"Threaded rigid metal conduit or threaded steel IMC, Type MC-HL, or Type MI cable with listed dusttight fittings.","r":"NEC 502.10(A)"},{"t":1,"c":"Art. 502 Class II Locations","f":"Dust seal options between dust-ignitionproof and non-dust-ignitionproof enclosures?","b":"A permanent and effective seal, a horizontal raceway at least 10 ft long, or a vertical raceway at least 5 ft long extending downward from the dust-ignitionproof enclosure.","r":"NEC 502.15"},{"t":1,"c":"Art. 502 Class II Locations","f":"Class II, Division 2 wiring methods?","b":"Rigid metal conduit, IMC, EMT, dusttight wireways, Type MC or MI cable with listed fittings, among others.","r":"NEC 502.10(B)"},{"t":1,"c":"Art. 503 Class III Locations","f":"What is Class III, Division 1?","b":"Locations where easily ignitible fibers or flyings are handled, manufactured, or used.","r":"NEC 500.5(D)(1)"},{"t":1,"c":"Art. 503 Class III Locations","f":"What is Class III, Division 2?","b":"Locations where easily ignitible fibers are stored or handled other than in manufacturing.","r":"NEC 500.5(D)(2)"},{"t":1,"c":"Art. 503 Class III Locations","f":"Examples of Class III locations?","b":"Textile mills, cotton gins, clothing manufacturing, and woodworking plants.","r":"NEC 503.1"},{"t":1,"c":"Art. 503 Class III Locations","f":"Class III, Division 1 wiring methods?","b":"Rigid metal conduit, IMC, EMT, dusttight wireways, and Type MC or MI cable with listed fittings.","r":"NEC 503.10(A)"},{"t":1,"c":"Art. 504 Intrinsically Safe Systems","f":"What is an intrinsically safe system?","b":"Circuits that cannot release enough electrical or thermal energy under normal or fault conditions to ignite a hazardous atmosphere.","r":"NEC 504.1, 500.7(E)"},{"t":1,"c":"Art. 504 Intrinsically Safe Systems","f":"Separation of intrinsically safe wiring from other wiring?","b":"Not in the same raceway, tray, or cable as non-IS conductors, or separated by at least 2 in or a grounded metal or insulating partition.","r":"NEC 504.30(A)"},{"t":1,"c":"Art. 504 Intrinsically Safe Systems","f":"How is intrinsically safe wiring labeled?","b":"Permanently affixed labels reading 'Intrinsic Safety Wiring' at intervals of not over 25 ft.","r":"NEC 504.80"},{"t":1,"c":"Art. 504 Intrinsically Safe Systems","f":"Color for intrinsically safe conductors?","b":"Light blue may be used if no other conductors in the enclosure are light blue.","r":"NEC 504.80(C)"},{"t":1,"c":"Arts. 505-506 Zone Classification","f":"Class I, Zone 0?","b":"Ignitible concentrations of flammable gases or vapors are present continuously or for long periods.","r":"NEC 505.5(B)(1)"},{"t":1,"c":"Arts. 505-506 Zone Classification","f":"Class I, Zone 1?","b":"Ignitible concentrations are likely during normal operation, or may exist frequently due to repair, maintenance, or leakage.","r":"NEC 505.5(B)(2)"},{"t":1,"c":"Arts. 505-506 Zone Classification","f":"Class I, Zone 2?","b":"Ignitible concentrations are not likely during normal operation and, if they occur, exist only briefly.","r":"NEC 505.5(B)(3)"},{"t":1,"c":"Arts. 505-506 Zone Classification","f":"Which article covers combustible dusts and fibers using the Zone system?","b":"Article 506 (Zones 20, 21, and 22).","r":"NEC 506.1"},{"t":1,"c":"Art. 510 Hazardous Locations - Specific","f":"What do Articles 511 through 517 cover?","b":"Occupancies or parts that are or may become hazardous because of flammable gases, vapors, volatile liquids, combustible dust, or fibers.","r":"NEC 510.1"},{"t":1,"c":"Art. 511 Commercial Garages, Repair and Storage","f":"Classified area in a major repair garage?","b":"The area up to 18 in above the floor is Class I, Division 2 (for the ventilated or unventilated floor area).","r":"NEC 511.3(C)"},{"t":1,"c":"Art. 511 Commercial Garages, Repair and Storage","f":"Wiring above Class I locations in garages?","b":"Fixed wiring above Class I locations must be in metal raceways, rigid nonmetallic conduit, ENT, flexible metal conduit, or MC, AC, or similar cable.","r":"NEC 511.7(B)"},{"t":1,"c":"Art. 511 Commercial Garages, Repair and Storage","f":"Raceways embedded in a garage floor?","b":"Raceways embedded in or under the floor are considered within the Class I location above the floor if they lead into or through that area.","r":"NEC 511.7(A)(1)"},{"t":1,"c":"Art. 511 Commercial Garages, Repair and Storage","f":"GFCI in garages?","b":"All 125 V, 15 and 20 A receptacles for diagnostic equipment, hand tools, or portable lighting require GFCI protection.","r":"NEC 511.12"},{"t":1,"c":"Art. 513 Aircraft Hangars","f":"Classified area in aircraft hangars?","b":"The area up to 18 in above the floor is Class I, Division 2, plus areas near aircraft engines and fuel tanks.","r":"NEC 513.3"},{"t":1,"c":"Art. 513 Aircraft Hangars","f":"GFCI in aircraft hangars?","b":"125 V, 15 and 20 A receptacles used for diagnostic equipment, hand tools, or portable lighting require GFCI protection.","r":"NEC 513.12"},{"t":1,"c":"Art. 514 Motor Fuel Dispensing Facilities","f":"Classification inside a fuel dispenser?","b":"The area within the dispenser enclosure is Class I, Division 1.","r":"NEC Table 514.3(B)(1)"},{"t":1,"c":"Art. 514 Motor Fuel Dispensing Facilities","f":"Circuit disconnects at dispensers?","b":"Each circuit leading to or through dispensing equipment needs a switch or means to simultaneously disconnect all conductors, including the grounded conductor.","r":"NEC 514.11"},{"t":1,"c":"Art. 514 Motor Fuel Dispensing Facilities","f":"Emergency shutoff at fuel stations?","b":"A clearly identified emergency shutoff at least 20 ft but not more than 100 ft from the dispensers it serves.","r":"NEC 514.11"},{"t":1,"c":"Art. 514 Motor Fuel Dispensing Facilities","f":"Underground wiring at fuel stations?","b":"Threaded rigid or intermediate metal conduit (or approved cable), or PVC with at least 2 ft cover with rigid metal at transitions.","r":"NEC 514.8"},{"t":1,"c":"Arts. 515-516 Bulk Storage Plants and Finishing Processes","f":"What is a bulk storage plant?","b":"A property where flammable liquids are received and stored or blended in bulk for distribution by tank vessel, pipeline, tank car, tank vehicle, or container.","r":"NEC 515.1"},{"t":1,"c":"Arts. 515-516 Bulk Storage Plants and Finishing Processes","f":"What does Article 516 cover?","b":"Spray application, dipping, coating, and printing processes using flammable or combustible liquids or materials.","r":"NEC 516.1"},{"t":1,"c":"Art. 517 Health Care Facilities","f":"Category 1 patient care space?","b":"Critical care: failure of equipment or system is likely to cause major injury or death.","r":"NEC 517.2"},{"t":1,"c":"Art. 517 Health Care Facilities","f":"Category 2 patient care space?","b":"General care: failure is likely to cause minor injury.","r":"NEC 517.2"},{"t":1,"c":"Art. 517 Health Care Facilities","f":"Category 3 patient care space?","b":"Basic care: failure is not likely to cause injury.","r":"NEC 517.2"},{"t":1,"c":"Art. 517 Health Care Facilities","f":"Category 4 patient care space?","b":"Support: failure is not likely to have any impact on patients.","r":"NEC 517.2"},{"t":1,"c":"Art. 517 Health Care Facilities","f":"Patient vicinity?","b":"Space about the bed extending 6 ft beyond the bed perimeter and at least 7 ft 6 in above the floor.","r":"NEC 517.2"},{"t":1,"c":"Art. 517 Health Care Facilities","f":"Grounding of patient care space branch circuits?","b":"Redundant grounding: a metal raceway or cable armor as an EGC plus an insulated copper EGC.","r":"NEC 517.13"},{"t":1,"c":"Art. 517 Health Care Facilities","f":"Branch circuits to each general care patient bed?","b":"At least two: one from the emergency system and one from the normal system.","r":"NEC 517.18(A)"},{"t":1,"c":"Art. 517 Health Care Facilities","f":"Receptacles per bed in critical care spaces?","b":"At least 14 receptacles.","r":"NEC 517.19(B)"},{"t":1,"c":"Art. 517 Health Care Facilities","f":"Essential electrical system branches in hospitals?","b":"Life safety branch and critical branch (emergency system), and the equipment system.","r":"NEC 517.30"},{"t":1,"c":"Art. 517 Health Care Facilities","f":"Time for emergency system restoration?","b":"Within 10 seconds of loss of normal power.","r":"NEC 517.31"},{"t":1,"c":"Art. 517 Health Care Facilities","f":"Ground-fault protection in hospitals?","b":"Where provided at the service or feeder, another level is required downstream, with at least 6 cycles separation.","r":"NEC 517.17"},{"t":1,"c":"Art. 517 Health Care Facilities","f":"Wet procedure locations?","b":"Must be protected by GFCI or an isolated power system.","r":"NEC 517.20"},{"t":1,"c":"Art. 517 Health Care Facilities","f":"Line isolation monitor alarm threshold?","b":"Alarms when total hazard current reaches 5 mA.","r":"NEC 517.160(B)"},{"t":1,"c":"Art. 518 Assembly Occupancies","f":"What is an assembly occupancy?","b":"A building or portion intended for gathering of 100 or more persons for civic, political, travel, religious, social, or recreational purposes, or awaiting transportation.","r":"NEC 518.2(A)"},{"t":1,"c":"Art. 518 Assembly Occupancies","f":"Fixed wiring methods in assembly occupancies?","b":"Metal raceways, flexible metal raceways, nonmetallic raceways encased in at least 2 in of concrete, MC, AC, or MI cable (with limited NM use in Type III, IV, V).","r":"NEC 518.4"},{"t":1,"c":"Art. 518 Assembly Occupancies","f":"Examples of assembly occupancies?","b":"Auditoriums, theaters, churches, restaurants, gymnasiums, courtrooms, museums, dance halls, skating rinks, and transportation waiting areas.","r":"NEC 518.2"},{"t":1,"c":"Art. 590 Temporary Installations","f":"When is temporary wiring permitted?","b":"During construction, remodeling, maintenance, repair, or demolition of buildings, structures, or equipment.","r":"NEC 590.3(A)"},{"t":1,"c":"Art. 590 Temporary Installations","f":"Time limit for temporary holiday decorative lighting?","b":"90 days.","r":"NEC 590.3(B)"},{"t":1,"c":"Art. 590 Temporary Installations","f":"Temporary wiring for emergencies and tests?","b":"Permitted during emergencies and for tests, experiments, and developmental work.","r":"NEC 590.3(C)"},{"t":1,"c":"Art. 590 Temporary Installations","f":"When must temporary wiring be removed?","b":"Immediately upon completion of the purpose for which it was installed.","r":"NEC 590.3(D)"},{"t":1,"c":"Art. 590 Temporary Installations","f":"Receptacles on temporary installations?","b":"All receptacles must be of the grounding type, and receptacles on construction sites cannot be on a circuit that supplies temporary lighting.","r":"NEC 590.4(D)"},{"t":1,"c":"Art. 590 Temporary Installations","f":"Disconnecting means for temporary circuits?","b":"Suitable switches or plug connectors must disconnect all ungrounded conductors of each temporary circuit.","r":"NEC 590.4(E)"},{"t":1,"c":"Art. 590 Temporary Installations","f":"Lamp protection in temporary lighting?","b":"General illumination lamps must be protected from contact or breakage, by elevation at least 7 ft above the working surface or a guard.","r":"NEC 590.4(F)"},{"t":1,"c":"Art. 590 Temporary Installations","f":"Support of temporary cables and cords?","b":"Supported at intervals that protect them from physical damage, using staples, straps, ties, or similar fittings.","r":"NEC 590.4(J)"},{"t":1,"c":"Art. 590 Temporary Installations","f":"GFCI protection on construction sites?","b":"All 125 V, 15, 20, and 30 A receptacles not part of the permanent wiring and used by employees need GFCI protection; also 125 to 250 V, 15 to 100 A.","r":"NEC 590.6(A)"},{"t":1,"c":"Art. 590 Temporary Installations","f":"Alternative to GFCI for temporary power?","b":"An assured equipment grounding conductor program for other outlets.","r":"NEC 590.6(B)(2)"},{"t":1,"c":"Art. 600 Electric Signs and Outline Lighting","f":"Sign and outline lighting listing requirement?","b":"Fixed, mobile, and portable signs, outline lighting, and retrofit kits must be listed and labeled.","r":"NEC 600.3"},{"t":1,"c":"Art. 600 Electric Signs and Outline Lighting","f":"Required sign branch circuit?","b":"Each commercial building and occupancy with a ground-level public entrance must have at least one 20 A branch circuit for sign or outline lighting, with no other loads.","r":"NEC 600.5(A)"},{"t":1,"c":"Art. 600 Electric Signs and Outline Lighting","f":"Sign circuit load calculation?","b":"1200 VA for each required sign circuit.","r":"NEC 220.14(F)"},{"t":1,"c":"Art. 600 Electric Signs and Outline Lighting","f":"Maximum rating of sign branch circuits?","b":"Branch circuits supplying incandescent and ballast or transformer-type discharge lighting signs shall not exceed 20 A.","r":"NEC 600.5(B)"},{"t":1,"c":"Art. 600 Electric Signs and Outline Lighting","f":"Disconnect for a sign?","b":"Each sign must have a disconnecting means that opens all ungrounded conductors, within sight of the sign.","r":"NEC 600.6(A)"},{"t":1,"c":"Art. 600 Electric Signs and Outline Lighting","f":"Disconnect not in sight of the sign?","b":"It must be capable of being locked in the open position.","r":"NEC 600.6(A)(1)"},{"t":1,"c":"Art. 600 Electric Signs and Outline Lighting","f":"Sign grounding?","b":"Signs and outline lighting systems must be grounded and bonded.","r":"NEC 600.7"},{"t":1,"c":"Art. 600 Electric Signs and Outline Lighting","f":"Vehicle exposure of signs?","b":"Signs must be at least 14 ft above areas accessible to vehicles unless protected from physical damage.","r":"NEC 600.9(A)"},{"t":1,"c":"Art. 600 Electric Signs and Outline Lighting","f":"Sign temperature at adjacent combustibles?","b":"Adjacent combustible materials must not be subjected to temperatures above 90 degrees C (194 degrees F).","r":"NEC 600.9(B)"},{"t":1,"c":"Art. 600 Electric Signs and Outline Lighting","f":"Wet location signs?","b":"Must be weatherproof and have drain holes.","r":"NEC 600.9(D)"},{"t":1,"c":"Art. 600 Electric Signs and Outline Lighting","f":"Portable and mobile signs GFCI?","b":"Must have factory-installed GFCI protection for personnel in the cord or attachment plug.","r":"NEC 600.10(C)"},{"t":1,"c":"Art. 600 Electric Signs and Outline Lighting","f":"Definition of outline lighting?","b":"An arrangement of incandescent lamps or electric discharge tubing to outline or call attention to features such as a building shape or window decoration.","r":"NEC 600.2"},{"t":1,"c":"Art. 625 Electric Vehicle Power Transfer Systems","f":"What does Article 625 cover?","b":"Conductors and equipment external to the vehicle that connect an EV to a supply of electricity, and the installation of EV charging equipment.","r":"NEC 625.1"},{"t":1,"c":"Art. 625 Electric Vehicle Power Transfer Systems","f":"Define EVSE.","b":"The conductors, connectors, plugs, fittings, devices, and apparatus installed specifically to deliver energy from the premises wiring to the electric vehicle.","r":"NEC 625.2"},{"t":1,"c":"Art. 625 Electric Vehicle Power Transfer Systems","f":"Branch circuit for EV charging outlets?","b":"Each outlet must be supplied by an individual branch circuit with no other outlets.","r":"NEC 625.40"},{"t":1,"c":"Art. 625 Electric Vehicle Power Transfer Systems","f":"Overcurrent protection sizing for EVSE?","b":"Treated as a continuous load: not less than 125% of the maximum EVSE load.","r":"NEC 625.41"},{"t":1,"c":"Art. 625 Electric Vehicle Power Transfer Systems","f":"When does EVSE need a disconnect?","b":"EVSE rated over 60 A or over 150 V to ground needs a readily accessible, lockable disconnecting means.","r":"NEC 625.43"},{"t":1,"c":"Art. 625 Electric Vehicle Power Transfer Systems","f":"Mounting height of EV coupling means indoors?","b":"Between 18 in and 4 ft above the floor.","r":"NEC 625.50"},{"t":1,"c":"Art. 625 Electric Vehicle Power Transfer Systems","f":"Mounting height of EV coupling means outdoors?","b":"Not less than 24 in and not more than 4 ft above grade.","r":"NEC 625.50"},{"t":1,"c":"Art. 625 Electric Vehicle Power Transfer Systems","f":"Maximum EV cable length?","b":"25 ft, unless provided with a cable management system.","r":"NEC 625.17"},{"t":1,"c":"Art. 625 Electric Vehicle Power Transfer Systems","f":"GFCI for EV charging receptacles?","b":"Receptacles installed for the connection of EV charging require GFCI protection for personnel.","r":"NEC 625.54"},{"t":1,"c":"Art. 625 Electric Vehicle Power Transfer Systems","f":"Weatherproofing EV receptacles?","b":"Receptacles in wet locations need weatherproof enclosures whether or not the plug is inserted.","r":"NEC 625.56"},{"t":1,"c":"Art. 680 Swimming Pools","f":"Permanently installed pool?","b":"Constructed in the ground or partially in ground, any pool capable of holding water deeper than 42 in, and all indoor pools regardless of depth.","r":"NEC 680.2"},{"t":1,"c":"Art. 680 Swimming Pools","f":"Storable pool?","b":"Above ground, holds water to a maximum depth of 42 in, or has nonmetallic molded polymeric or inflatable walls regardless of dimensions.","r":"NEC 680.2"},{"t":1,"c":"Art. 680 Swimming Pools","f":"Clearance of service drops over pools?","b":"Insulated cables on a grounded messenger (0 to 750 V): 22.5 ft above water level or edge of water; others 25 ft.","r":"NEC Table 680.9(A)"},{"t":1,"c":"Art. 680 Swimming Pools","f":"Underground wiring near pools?","b":"Not under the pool or within 5 ft horizontally from the inside wall, unless necessary to supply pool equipment.","r":"NEC 680.10"},{"t":1,"c":"Art. 680 Swimming Pools","f":"Minimum burial for RMC or IMC near pools?","b":"6 in.","r":"NEC Table 680.10"},{"t":1,"c":"Art. 680 Swimming Pools","f":"Minimum burial for nonmetallic raceways near pools?","b":"18 in.","r":"NEC Table 680.10"},{"t":1,"c":"Art. 680 Swimming Pools","f":"Pool equipment maintenance disconnect?","b":"Readily accessible, within sight of the equipment, and at least 5 ft horizontally from the inside wall of the pool unless separated by a permanent barrier.","r":"NEC 680.12"},{"t":1,"c":"Art. 680 Swimming Pools","f":"GFCI for pool pump motors?","b":"Outlets supplying pool pump motors on single-phase 120 to 240 V circuits rated 60 A or less require GFCI protection.","r":"NEC 680.21(C)"},{"t":1,"c":"Art. 680 Swimming Pools","f":"EGC for pool motor circuits?","b":"An insulated copper equipment grounding conductor, not smaller than 12 AWG, is required.","r":"NEC 680.21(A)"},{"t":1,"c":"Art. 680 Swimming Pools","f":"Receptacle for pool circulation pumps?","b":"At least 10 ft from the inside wall of the pool (5 ft if single locking-type, GFCI, individual circuit).","r":"NEC 680.22(A)(1)"},{"t":1,"c":"Art. 680 Swimming Pools","f":"Required general-purpose receptacle near a pool?","b":"At least one 125 V, 15 or 20 A receptacle between 6 ft and 20 ft from the inside wall.","r":"NEC 680.22(A)(3)"},{"t":1,"c":"Art. 680 Swimming Pools","f":"Wet-niche luminaires over 15 V?","b":"Over 15 V but not over 150 V requires GFCI protection; luminaires over 150 V are not permitted; 15 V or less uses a listed transformer.","r":"NEC 680.23(A)"},{"t":1,"c":"Art. 680 Swimming Pools","f":"Minimum depth of wet-niche luminaires?","b":"Top of lens at least 18 in below normal water level, unless listed for less (not less than 4 in).","r":"NEC 680.23(A)"},{"t":1,"c":"Art. 690 Solar Photovoltaic Systems","f":"Maximum PV system voltage is based on what?","b":"The sum of series-connected module rated open-circuit voltages, corrected for the lowest expected ambient temperature.","r":"NEC 690.7"},{"t":1,"c":"Art. 690 Solar Photovoltaic Systems","f":"Maximum circuit current for PV source circuits?","b":"125% of the sum of parallel-connected module short-circuit currents (Isc x 1.25).","r":"NEC 690.8(A)"},{"t":1,"c":"Art. 690 Solar Photovoltaic Systems","f":"Conductor and OCPD sizing from the maximum current?","b":"Another 125% applies, giving about 156% of Isc, for conductors and overcurrent protective devices.","r":"NEC 690.8(B)"},{"t":1,"c":"Art. 690 Solar Photovoltaic Systems","f":"Rapid shutdown: controlled conductors outside the array boundary?","b":"Reduced to 30 V or less within 30 seconds of initiation.","r":"NEC 690.12(B)(1)"},{"t":1,"c":"Art. 690 Solar Photovoltaic Systems","f":"Rapid shutdown: conductors inside the array boundary?","b":"Reduced to 80 V or less within 30 seconds.","r":"NEC 690.12(B)(2)"},{"t":1,"c":"Art. 690 Solar Photovoltaic Systems","f":"Rapid shutdown label wording at service equipment?","b":"'SOLAR PV SYSTEM EQUIPPED WITH RAPID SHUTDOWN,' capital letters at least 3/8 in high, white on red, reflective.","r":"NEC 690.56(C)"},{"t":1,"c":"Art. 690 Solar Photovoltaic Systems","f":"PV system disconnecting means marking?","b":"Each PV system disconnect must be permanently marked to identify it as a PV system disconnecting means.","r":"NEC 690.13(B)"},{"t":1,"c":"Art. 690 Solar Photovoltaic Systems","f":"DC arc-fault protection threshold?","b":"Required for PV circuits with maximum system voltage of 80 V dc or greater between any two conductors.","r":"NEC 690.11"},{"t":1,"c":"Art. 690 Solar Photovoltaic Systems","f":"Who may install PV systems?","b":"Only qualified persons.","r":"NEC 690.4(C)"},{"t":1,"c":"Art. 690 Solar Photovoltaic Systems","f":"PV dc conductors inside a building?","b":"Over 30 V or 8 A: in metal raceways, Type MC cable, or metal enclosures from the point of penetration to the first readily accessible disconnect.","r":"NEC 690.31(G)"},{"t":1,"c":"Art. 690 Solar Photovoltaic Systems","f":"Exposed outdoor PV source circuit wiring?","b":"PV wire or PV cable, or other listed conductors suitable for the location.","r":"NEC 690.31"},{"t":1,"c":"Art. 690 Solar Photovoltaic Systems","f":"Interactive point of interconnection marking?","b":"Marked at an accessible location at the disconnecting means as a power source, with rated ac output current and nominal operating ac voltage.","r":"NEC 690.54"},{"t":1,"c":"Art. 700 Emergency Systems","f":"Define emergency systems.","b":"Systems legally required and classed as emergency, providing automatic illumination and power essential for safety to human life.","r":"NEC 700.2"},{"t":1,"c":"Art. 700 Emergency Systems","f":"Required time to restore emergency power?","b":"Automatically available within 10 seconds of loss of normal power.","r":"NEC 700.12"},{"t":1,"c":"Art. 700 Emergency Systems","f":"Battery source capacity?","b":"Must supply the total load for at least 1-1/2 hours without voltage falling below 87-1/2% of normal.","r":"NEC 700.12(A)"},{"t":1,"c":"Art. 700 Emergency Systems","f":"Emergency system testing?","b":"A complete system test upon installation and periodic tests and maintenance on an AHJ-acceptable schedule, with written records.","r":"NEC 700.3, 700.4"},{"t":1,"c":"Art. 700 Emergency Systems","f":"Capacity of the alternate source?","b":"Sufficient to supply all equipment to be operated at one time.","r":"NEC 700.5"},{"t":1,"c":"Art. 700 Emergency Systems","f":"Marking of emergency enclosures?","b":"All boxes and enclosures for emergency circuits (including transfer switches and panels) must be permanently marked as part of an emergency system.","r":"NEC 700.10(A)"},{"t":1,"c":"Art. 700 Emergency Systems","f":"Emergency wiring separation?","b":"Emergency circuit wiring must be kept entirely independent of all other wiring and equipment, with limited exceptions.","r":"NEC 700.10(B)(1)"},{"t":1,"c":"Art. 700 Emergency Systems","f":"Sign at service equipment for emergency sources?","b":"A sign indicating the type and location of on-site emergency power sources, unless the source is in sight of the service.","r":"NEC 700.8"},{"t":1,"c":"Art. 700 Emergency Systems","f":"Emergency illumination design?","b":"The failure of any single lighting element must not leave any space requiring emergency illumination in total darkness.","r":"NEC 700.16"},{"t":1,"c":"Art. 700 Emergency Systems","f":"Overcurrent device coordination in emergency systems?","b":"Emergency system overcurrent devices must be selectively coordinated with all supply-side overcurrent devices.","r":"NEC 700.32"},{"t":1,"c":"Art. 705 Interconnected Electric Power Production Sources","f":"What does Article 705 cover?","b":"Installation of one or more electric power production sources operating in parallel with a primary source such as the utility.","r":"NEC 705.1"},{"t":1,"c":"Art. 705 Interconnected Electric Power Production Sources","f":"Load-side busbar rule for inverter connections?","b":"The sum of 125% of the inverter output current and the OCPD protecting the busbar must not exceed 120% of the busbar ampacity (when the breaker is at the opposite end from the main).","r":"NEC 705.12"},{"t":1,"c":"Art. 705 Interconnected Electric Power Production Sources","f":"Loss of the primary source?","b":"The power production source must automatically disconnect from the primary source and not reconnect until it is restored.","r":"NEC 705.40"},{"t":1,"c":"Art. 705 Interconnected Electric Power Production Sources","f":"Disconnect for each power source?","b":"A means must disconnect all ungrounded conductors of the power source from other systems, readily accessible and lockable open.","r":"NEC 705.20"},{"t":1,"c":"Art. 705 Interconnected Electric Power Production Sources","f":"Overcurrent protection for circuits fed by multiple sources?","b":"Overcurrent devices must be located to provide protection from all sources.","r":"NEC 705.30"},{"t":1,"c":"Art. 705 Interconnected Electric Power Production Sources","f":"Supply-side connections?","b":"Permitted ahead of the service disconnecting means using listed equipment and methods in 705.11.","r":"NEC 705.11"},{"t":1,"c":"Art. 725 Class 1, 2 and 3 circuits","f":"Class 1 power-limited circuit source limits?","b":"Not more than 30 V and 1000 VA.","r":"NEC 725.41(A)"},{"t":1,"c":"Art. 725 Class 1, 2 and 3 circuits","f":"Maximum voltage for Class 1 remote-control and signaling circuits?","b":"600 V.","r":"NEC 725.41(B)"},{"t":1,"c":"Art. 725 Class 1, 2 and 3 circuits","f":"Overcurrent protection of 18 AWG Class 1 conductors?","b":"7 A.","r":"NEC 725.43"},{"t":1,"c":"Art. 725 Class 1, 2 and 3 circuits","f":"Overcurrent protection of 16 AWG Class 1 conductors?","b":"10 A.","r":"NEC 725.43"},{"t":1,"c":"Art. 725 Class 1, 2 and 3 circuits","f":"Can Class 1 and power conductors share a raceway?","b":"Only where the equipment powered is functionally associated.","r":"NEC 725.48(B)"},{"t":1,"c":"Art. 725 Class 1, 2 and 3 circuits","f":"Class 2 and 3 separation from power circuits?","b":"Not in the same cable, enclosure, or raceway as electric light, power, Class 1, or NPLFA conductors, unless separated by a barrier or other exceptions.","r":"NEC 725.136(A)"},{"t":1,"c":"Art. 725 Class 1, 2 and 3 circuits","f":"Mechanical execution of work for low-voltage circuits?","b":"Installed neatly and workmanlike, supported by the building structure, not by raceways.","r":"NEC 725.24"},{"t":1,"c":"Art. 725 Class 1, 2 and 3 circuits","f":"Class 2 and 3 cable markings: plenum, riser, general, limited use?","b":"CL2P/CL3P (plenum), CL2R/CL3R (riser), CL2/CL3 (general), CL2X/CL3X (limited use).","r":"NEC 725.179"},{"t":1,"c":"Art. 725 Class 1, 2 and 3 circuits","f":"Wiring on the supply side of a Class 2 or 3 power source?","b":"Installed per Chapters 1 through 4 as for power wiring.","r":"NEC 725.130"},{"t":1,"c":"Art. 760 Fire Alarm Systems","f":"What does Article 760 cover?","b":"Installation of wiring and equipment of fire alarm systems, including all circuits controlled and powered by the fire alarm system.","r":"NEC 760.1"},{"t":1,"c":"Art. 760 Fire Alarm Systems","f":"NPLFA source maximum voltage?","b":"600 V.","r":"NEC 760.41"},{"t":1,"c":"Art. 760 Fire Alarm Systems","f":"NPLFA overcurrent protection of 18 AWG and 16 AWG?","b":"7 A and 10 A respectively.","r":"NEC 760.43"},{"t":1,"c":"Art. 760 Fire Alarm Systems","f":"Identification of fire alarm circuits?","b":"Fire alarm circuits must be identified at terminal and junction locations to prevent unintentional interference during testing and servicing.","r":"NEC 760.30"},{"t":1,"c":"Art. 760 Fire Alarm Systems","f":"PLFA separation from power conductors?","b":"Open conductors must be separated at least 2 in from electric light, power, Class 1, and NPLFA conductors.","r":"NEC 760.136(A)"},{"t":1,"c":"Art. 760 Fire Alarm Systems","f":"Marking of power-limited fire alarm circuits?","b":"Durably marked as power-limited where plainly visible at terminations.","r":"NEC 760.124"},{"t":1,"c":"Art. 800 Communications Systems - General","f":"Primary protector location?","b":"In, on, or immediately adjacent to the building and as close as practicable to the cable entrance.","r":"NEC 800.90(B)"},{"t":1,"c":"Art. 800 Communications Systems - General","f":"Where is a primary protector required?","b":"On each circuit run partly or entirely in aerial wire or cable not confined within a block.","r":"NEC 800.90(A)"},{"t":1,"c":"Art. 800 Communications Systems - General","f":"Primary protector in hazardous locations?","b":"Shall not be located in any hazardous (classified) location.","r":"NEC 800.90(C)"},{"t":1,"c":"Art. 800 Communications Systems - General","f":"Minimum size of the communications bonding conductor?","b":"14 AWG copper.","r":"NEC 800.100(A)"},{"t":1,"c":"Art. 800 Communications Systems - General","f":"Maximum length of the bonding conductor in dwellings?","b":"20 ft, and as short as practicable.","r":"NEC 800.100(A)(4)"},{"t":1,"c":"Art. 800 Communications Systems - General","f":"Communications grounding electrode if none exists?","b":"A rod at least 5 ft long and 1/2 in in diameter, among other listed options.","r":"NEC 800.100(C)"},{"t":1,"c":"Art. 800 Communications Systems - General","f":"Bonding separate communications and power electrodes?","b":"A 6 AWG copper conductor connects them where separate electrodes are used.","r":"NEC 800.100(D)"},{"t":1,"c":"Art. 800 Communications Systems - General","f":"Separation of communications cables from power conductors?","b":"At least 2 in from open electric light, power, Class 1, or NPLFA conductors, unless separated or in raceway.","r":"NEC 800.133(A)(2)"},{"t":1,"c":"Art. 800 Communications Systems - General","f":"Communications cable types?","b":"CMP plenum, CMR riser, CM or CMG general purpose, CMX limited use.","r":"NEC 800.179"},{"t":1,"c":"Art. 800 Communications Systems - General","f":"Abandoned communications cables?","b":"The accessible portion of abandoned cables must be removed.","r":"NEC 800.25"},{"t":1,"c":"Art. 800 Communications Systems - General","f":"Mechanical execution of work for communications?","b":"Installed neatly and workmanlike, supported so cable is not damaged; raceways not used as support.","r":"NEC 800.24"},{"t":2,"c":"Art. 242 Overvoltage protection","f":"What does Article 242 cover?","b":"Overvoltage protection: surge-protective devices (SPDs) and surge arresters, for permanent installations.","r":"NEC 242.1"},{"t":2,"c":"Art. 242 Overvoltage protection","f":"Where can a Type 1 SPD be installed, and where a Type 2?","b":"Type 1: line or load side of the service disconnect. Type 2: load side of the service disconnect, such as at a panelboard.","r":"NEC 242.12"},{"t":2,"c":"Art. 242 Overvoltage protection","f":"Where is a Type 3 SPD installed?","b":"At the point of utilization, at least 30 ft (10 m) of conductor length from the service or separately derived system overcurrent device.","r":"NEC 242.12"},{"t":2,"c":"Art. 242 Overvoltage protection","f":"What is a Type 4 SPD?","b":"A component assembly: one or more Type 5 components with a disconnect means, in a single enclosure or assembly, evaluated as a unit.","r":"NEC 242.12"},{"t":2,"c":"Art. 242 Overvoltage protection","f":"Must SPDs be listed?","b":"Yes. SPDs must be listed.","r":"NEC 242.6"},{"t":2,"c":"Art. 360 Flexible metallic tubing","f":"What is the minimum trade size of FMT?","b":"1/2 in. (metric designator 16), with limited allowances for 3/8 in.","r":"NEC 360.20"},{"t":2,"c":"Art. 360 Flexible metallic tubing","f":"What is the maximum length of FMT in a run?","b":"6 ft (1.8 m).","r":"NEC 360.12"},{"t":2,"c":"Art. 360 Flexible metallic tubing","f":"What is the FMT support spacing?","b":"Secured at intervals not over 4-1/2 ft (1.35 m) and within 1 ft (300 mm) of each box, unless fished or in a permitted exception.","r":"NEC 360.30"},{"t":2,"c":"Art. 360 Flexible metallic tubing","f":"How many degrees of bends are allowed between pull points in FMT?","b":"No more than the equivalent of four quarter bends (360 degrees) between pull points.","r":"NEC 360.24"},{"t":2,"c":"Art. 362 Electrical nonmetallic tubing","f":"What are the ENT trade size limits?","b":"Minimum 1/2 in. (16), maximum 2 in. (53).","r":"NEC 362.20"},{"t":2,"c":"Art. 362 Electrical nonmetallic tubing","f":"What is the ENT support spacing?","b":"Secured at intervals not over 3 ft (900 mm) and within 3 ft of each outlet box, junction box, device box, cabinet or fitting.","r":"NEC 362.30"},{"t":2,"c":"Art. 362 Electrical nonmetallic tubing","f":"Where may ENT be used in a building without a thermal barrier?","b":"Concealed in walls, floors and ceilings of buildings not exceeding three floors above grade; also in or under concrete slabs and encased in concrete.","r":"NEC 362.10"},{"t":2,"c":"Art. 362 Electrical nonmetallic tubing","f":"What ambient temperature limit applies to ENT?","b":"It is not permitted in ambient temperatures over 50 degrees C (122 degrees F) unless listed for a higher temperature.","r":"NEC 362.12"},{"t":2,"c":"Art. 362 Electrical nonmetallic tubing","f":"How many degrees of bends are allowed between pull points in ENT?","b":"No more than 360 degrees total between pull points.","r":"NEC 362.24"},{"t":2,"c":"Art. 366 Auxiliary gutters","f":"What is the fill limit for conductors in a sheet metal auxiliary gutter?","b":"Conductors must not fill more than 20 percent of the gutter cross-sectional area.","r":"NEC 366.22"},{"t":2,"c":"Art. 366 Auxiliary gutters","f":"When does ampacity adjustment apply in an auxiliary gutter?","b":"When there are more than 30 current-carrying conductors at any cross section. Signal and control conductors are not counted.","r":"NEC 366.23"},{"t":2,"c":"Art. 366 Auxiliary gutters","f":"What is the maximum length of an auxiliary gutter beyond the equipment it supplements?","b":"30 ft (9 m). Longer runs must be treated as a wireway.","r":"NEC 366.12"},{"t":2,"c":"Art. 366 Auxiliary gutters","f":"What is the support spacing for sheet metal and nonmetallic auxiliary gutters?","b":"Metal: every 5 ft (1.5 m). Nonmetallic: every 3 ft (900 mm).","r":"NEC 366.30"},{"t":2,"c":"Art. 366 Auxiliary gutters","f":"What is the fill limit for splices and taps in an auxiliary gutter?","b":"Splices and taps must not fill more than 75 percent of the gutter area at that point.","r":"NEC 366.56"},{"t":2,"c":"Art. 368 Busways","f":"What does Article 368 cover?","b":"Busways and associated fittings, including feeder and plug-in types, plus busway branches.","r":"NEC 368.1"},{"t":2,"c":"Art. 368 Busways","f":"What is the standard busway support spacing?","b":"At least every 5 ft (1.5 m) unless the busway is designed and marked for other spacing.","r":"NEC 368.30"},{"t":2,"c":"Art. 368 Busways","f":"What protection is required where a busway passes through a floor?","b":"Totally enclosed, with a minimum of 6 ft (1.8 m) above the floor, for protection from physical damage.","r":"NEC 368.10"},{"t":2,"c":"Art. 368 Busways","f":"Where is overcurrent protection required for a busway that reduces in ampacity?","b":"At the point where it reduces in size, unless it meets the specific exceptions.","r":"NEC 368.17"},{"t":2,"c":"Art. 370 Cablebus","f":"What is cablebus?","b":"An assembly of insulated conductors with fittings and terminations in a completely enclosed, ventilated, protective metal housing.","r":"NEC 370.2"},{"t":2,"c":"Art. 376 Metal wireways","f":"What is the conductor fill limit in a metal wireway?","b":"Conductors must not fill more than 20 percent of the interior cross-sectional area.","r":"NEC 376.22"},{"t":2,"c":"Art. 376 Metal wireways","f":"When does ampacity adjustment apply in a metal wireway?","b":"When there are more than 30 current-carrying conductors at any cross section. Signal and control conductors are not counted.","r":"NEC 376.22"},{"t":2,"c":"Art. 376 Metal wireways","f":"How are horizontal metal wireways supported?","b":"At each end and at intervals not exceeding 5 ft, with no more than 10 ft between supports.","r":"NEC 376.30"},{"t":2,"c":"Art. 376 Metal wireways","f":"How are vertical metal wireways supported?","b":"At intervals not over 15 ft, with no more than one joint between supports.","r":"NEC 376.30"},{"t":2,"c":"Art. 376 Metal wireways","f":"What is the fill limit for splices and taps in a wireway?","b":"75 percent of the wireway cross-section at that point.","r":"NEC 376.56"},{"t":2,"c":"Art. 378 Nonmetallic wireways","f":"What is the conductor fill limit in a nonmetallic wireway?","b":"20 percent of the interior cross-sectional area.","r":"NEC 378.22"},{"t":2,"c":"Art. 378 Nonmetallic wireways","f":"What is the horizontal support spacing for nonmetallic wireways?","b":"Every 3 ft (900 mm), unless listed for other intervals.","r":"NEC 378.30"},{"t":2,"c":"Art. 378 Nonmetallic wireways","f":"What is the vertical support spacing for nonmetallic wireways?","b":"Every 4 ft (1.2 m), with no more than one joint between supports.","r":"NEC 378.30"},{"t":2,"c":"Art. 378 Nonmetallic wireways","f":"When are expansion fittings needed in nonmetallic wireways?","b":"Where the length change due to temperature is expected to be 1/4 in. (6 mm) or more.","r":"NEC 378.44"},{"t":2,"c":"Art. 382 Nonmetallic extensions","f":"What does Article 382 cover?","b":"Listed nonmetallic extensions that are surface extensions from an existing branch circuit outlet.","r":"NEC 382.1"},{"t":2,"c":"Art. 382 Nonmetallic extensions","f":"What circuit sizes may supply a nonmetallic extension?","b":"An existing 15 or 20 ampere branch circuit only.","r":"NEC 382.10"},{"t":2,"c":"Art. 382 Nonmetallic extensions","f":"What voltage limit applies to nonmetallic extensions?","b":"150 volts or less.","r":"NEC 382.10"},{"t":2,"c":"Art. 384 Strut-type channel raceway","f":"What is the conductor fill limit in a strut-type channel raceway?","b":"25 percent of the cross-sectional area.","r":"NEC 384.22"},{"t":2,"c":"Art. 384 Strut-type channel raceway","f":"What is the support spacing for strut-type channel raceway?","b":"At intervals not exceeding 10 ft (3 m), and within 3 ft (900 mm) of each outlet box, junction box, cabinet or fitting.","r":"NEC 384.30"},{"t":2,"c":"Art. 384 Strut-type channel raceway","f":"What is the fill limit for splices and taps in strut-type channel raceway?","b":"75 percent of the cross-section at that point.","r":"NEC 384.56"},{"t":2,"c":"Art. 386 Surface metal raceways","f":"Where are surface metal raceways permitted?","b":"In dry locations, exposed.","r":"NEC 386.10"},{"t":2,"c":"Art. 386 Surface metal raceways","f":"When must surface metal raceway have extra metal thickness?","b":"Where the voltage is 300 volts or more between conductors, the metal must be at least 1 mm (0.040 in.) thick.","r":"NEC 386.12"},{"t":2,"c":"Art. 386 Surface metal raceways","f":"May a surface metal raceway pass through a wall?","b":"Yes, through dry walls, dry partitions and dry floors if the length passing through is unbroken.","r":"NEC 386.10"},{"t":2,"c":"Art. 390 Underfloor raceways","f":"Where are underfloor raceways permitted?","b":"Beneath the surface of concrete or other flooring material, or in office occupancies where laid flush with the floor surface.","r":"NEC 390.10"},{"t":2,"c":"Art. 390 Underfloor raceways","f":"What fill limit applies to underfloor raceway?","b":"Conductors must not fill more than 40 percent of the raceway cross-section.","r":"NEC 390.22"},{"t":2,"c":"Art. 394 Concealed knob-and-tube wiring","f":"When is concealed knob-and-tube wiring permitted for new work?","b":"Only for extensions of existing installations, or elsewhere by special permission.","r":"NEC 394.10"},{"t":2,"c":"Art. 394 Concealed knob-and-tube wiring","f":"What clearance is required between knob-and-tube conductors?","b":"At least 3 in. (75 mm) between conductors, and at least 1 in. (25 mm) from the surface wired over.","r":"NEC 394.19"},{"t":2,"c":"Art. 394 Concealed knob-and-tube wiring","f":"How often is knob-and-tube conductor supported?","b":"At intervals not over 4-1/2 ft (1.4 m), and within 6 in. (150 mm) of each tap or splice.","r":"NEC 394.30"},{"t":2,"c":"Art. 396 Messenger-supported wiring","f":"Where is messenger-supported wiring permitted?","b":"In industrial establishments where conditions of maintenance and supervision ensure that only qualified persons service the installation.","r":"NEC 396.10"},{"t":2,"c":"Art. 398 Open wiring on insulators","f":"Where is open wiring on insulators permitted?","b":"Only in industrial or agricultural establishments, indoors or outdoors, in wet or dry locations, and where subject to corrosive vapors, as well as for services.","r":"NEC 398.10"},{"t":2,"c":"Art. 402 Fixture wires","f":"What is the minimum size of fixture wire?","b":"18 AWG.","r":"NEC 402.6"},{"t":2,"c":"Art. 402 Fixture wires","f":"What is the ampacity of 18 AWG fixture wire per Table 402.5?","b":"6 amperes.","r":"NEC 402.5"},{"t":2,"c":"Art. 402 Fixture wires","f":"What is the ampacity of 16 AWG fixture wire per Table 402.5?","b":"8 amperes.","r":"NEC 402.5"},{"t":2,"c":"Art. 402 Fixture wires","f":"What is the ampacity of 14 AWG fixture wire per Table 402.5?","b":"17 amperes.","r":"NEC 402.5"},{"t":2,"c":"Art. 402 Fixture wires","f":"What is the ampacity of 12 AWG fixture wire per Table 402.5?","b":"23 amperes.","r":"NEC 402.5"},{"t":2,"c":"Art. 409 Industrial control panels","f":"What does Article 409 cover?","b":"Industrial control panels intended for general use and operating at 1000 volts or less.","r":"NEC 409.1"},{"t":2,"c":"Art. 409 Industrial control panels","f":"What must an industrial control panel be marked with for short-circuit protection?","b":"A short-circuit current rating (SCCR).","r":"NEC 409.110"},{"t":2,"c":"Art. 409 Industrial control panels","f":"May an industrial control panel be installed where the available fault current exceeds its SCCR?","b":"No. The SCCR must not be less than the available fault current at the point of installation.","r":"NEC 409.22"},{"t":2,"c":"Art. 411 Lighting systems operating at 30 volts or less","f":"What voltage limits define a 30-volt lighting system?","b":"30 volts rms or less (42.4 volts peak) for ac, or 60 volts dc or less.","r":"NEC 411.1"},{"t":2,"c":"Art. 411 Lighting systems operating at 30 volts or less","f":"What is the maximum secondary circuit rating for 30-volt lighting systems?","b":"25 amperes.","r":"NEC 411.5"},{"t":2,"c":"Art. 426 Fixed outdoor electric deicing and snow-melting equipment","f":"What does Article 426 cover?","b":"Fixed outdoor electric deicing and snow-melting equipment, such as heating cables and panels on roofs, pavements and similar surfaces.","r":"NEC 426.1"},{"t":2,"c":"Art. 426 Fixed outdoor electric deicing and snow-melting equipment","f":"What load factor applies to deicing and snow-melting branch circuits?","b":"Treat as continuous: branch-circuit conductors and devices sized at 125 percent of the load.","r":"NEC 426.4"},{"t":2,"c":"Art. 426 Fixed outdoor electric deicing and snow-melting equipment","f":"What ground-fault protection is required for deicing and snow-melting equipment?","b":"Ground-fault protection of equipment (GFPE).","r":"NEC 426.28"},{"t":2,"c":"Art. 427 Fixed electric heating equipment for pipelines and vessels","f":"What does Article 427 cover?","b":"Electrically energized heating systems and the installation of such systems used with pipelines or vessels.","r":"NEC 427.1"},{"t":2,"c":"Art. 427 Fixed electric heating equipment for pipelines and vessels","f":"What load factor applies to pipeline and vessel heating branch circuits?","b":"Continuous load: size circuit conductors and devices at 125 percent.","r":"NEC 427.4"},{"t":2,"c":"Art. 427 Fixed electric heating equipment for pipelines and vessels","f":"What ground-fault protection is required for pipeline heating?","b":"Ground-fault protection of equipment (GFPE) for each branch circuit supplying electric heating equipment.","r":"NEC 427.22"},{"t":2,"c":"Art. 460 Capacitors","f":"What is the minimum ampacity of capacitor circuit conductors?","b":"135 percent of the rated current of the capacitor.","r":"NEC 460.8"},{"t":2,"c":"Art. 460 Capacitors","f":"How fast must a capacitor of 1000 volts or less discharge after disconnection?","b":"Residual voltage must drop to 50 volts or less within 1 minute.","r":"NEC 460.6"},{"t":2,"c":"Art. 460 Capacitors","f":"How fast must a capacitor over 1000 volts discharge after disconnection?","b":"Residual voltage must drop to 50 volts or less within 5 minutes.","r":"NEC 460.6"},{"t":2,"c":"Art. 460 Capacitors","f":"What is the minimum rating of a capacitor disconnecting means?","b":"Not less than 135 percent of the rated current of the capacitor.","r":"NEC 460.8"},{"t":2,"c":"Art. 470 Resistors and reactors","f":"What does Article 470 cover?","b":"Resistors and reactors installed in electric circuits, including those used in motor starting and in power systems.","r":"NEC 470.1"},{"t":2,"c":"Art. 470 Resistors and reactors","f":"How far must a resistor or reactor be from combustible material?","b":"At least 12 in. (305 mm), or be separated from it by an effective thermal barrier.","r":"NEC 470.3"},{"t":2,"c":"Art. 520 Theaters and similar locations","f":"What does Article 520 cover?","b":"Theaters, audience areas of motion picture and television studios, performance areas, and similar locations, indoors or outdoors, for permanent or temporary use.","r":"NEC 520.1"},{"t":2,"c":"Art. 525 Carnivals, circuses, fairs, and similar events","f":"What does Article 525 cover?","b":"Installation of portable wiring and equipment for carnivals, circuses, exhibitions, fairs, traveling attractions and similar events.","r":"NEC 525.1"},{"t":2,"c":"Art. 525 Carnivals, circuses, fairs, and similar events","f":"How close may amusement rides be to overhead conductors of 600 volts or less?","b":"Rides must not be under or within 15 ft (4.5 m) horizontally of the conductors, with limited exceptions.","r":"NEC 525.5"},{"t":2,"c":"Art. 525 Carnivals, circuses, fairs, and similar events","f":"What GFCI protection is required in carnival and fair wiring?","b":"All 125-volt, single-phase, 15-, 20- and 30-ampere receptacles in areas covered by Article 525 need GFCI protection for personnel.","r":"NEC 525.23"},{"t":2,"c":"Art. 525 Carnivals, circuses, fairs, and similar events","f":"What is the minimum size for single-conductor cable used at carnivals?","b":"2 AWG or larger for portable single-conductor cables.","r":"NEC 525.20"},{"t":2,"c":"Art. 525 Carnivals, circuses, fairs, and similar events","f":"Where must the disconnecting means for a ride be located?","b":"Within sight of and within 6 ft of the operator's station of each ride or attraction, and must be readily accessible to the operator.","r":"NEC 525.21"},{"t":2,"c":"Art. 547 Agricultural buildings","f":"What does Article 547 cover?","b":"Agricultural buildings or parts of buildings where excessive dust, dust with water, corrosive atmospheres, or both exist.","r":"NEC 547.1"},{"t":2,"c":"Art. 547 Agricultural buildings","f":"What is an equipotential plane in an agricultural building?","b":"A bonded area, such as a wire mesh or other conductive elements in the concrete floor, that reduces voltage differences from livestock contact.","r":"NEC 547.2"},{"t":2,"c":"Art. 547 Agricultural buildings","f":"Where must an equipotential plane be installed?","b":"In livestock confinement areas with concrete floors where metallic equipment is located that may become energized and is accessible to livestock.","r":"NEC 547.10"},{"t":2,"c":"Art. 547 Agricultural buildings","f":"What is the minimum size bonding conductor for the equipotential plane?","b":"8 AWG solid copper, insulated, covered or bare.","r":"NEC 547.10"},{"t":2,"c":"Art. 547 Agricultural buildings","f":"Which wiring methods are allowed in damp, wet or corrosive areas of agricultural buildings?","b":"Types such as UF, NMC, copper SE, jacketed MC cable, PVC and RTRC conduit, LFNC, and other corrosion-resistant methods.","r":"NEC 547.5"},{"t":2,"c":"Art. 550 Mobile homes","f":"What power-supply cord rating does a mobile home use?","b":"One listed 50-ampere cord, 120/240 volts, 3-pole, 4-wire, with a molded attachment plug.","r":"NEC 550.10"},{"t":2,"c":"Art. 550 Mobile homes","f":"How far may mobile home service equipment be from the home?","b":"In sight from and not more than 30 ft (9 m) from the exterior wall of the home it serves.","r":"NEC 550.32"},{"t":2,"c":"Art. 550 Mobile homes","f":"May mobile home service equipment be mounted on the home?","b":"No. It must be located adjacent to the home, not mounted in or on it.","r":"NEC 550.32"},{"t":2,"c":"Art. 550 Mobile homes","f":"How must the neutral and equipment grounding conductors be handled in a mobile home?","b":"Insulated from each other in the home. The neutral and ground are bonded only at the service equipment.","r":"NEC 550.16"},{"t":2,"c":"Art. 551 Recreational vehicles and recreational vehicle parks","f":"What does Article 551 cover?","b":"Electrical conductors and equipment in recreational vehicles and recreational vehicle parks.","r":"NEC 551.1"},{"t":2,"c":"Art. 551 Recreational vehicles and recreational vehicle parks","f":"What is a recreational vehicle?","b":"A vehicular-type unit primarily designed as temporary living quarters for recreational, camping or seasonal use, either self-propelled or towed.","r":"NEC 551.2"},{"t":2,"c":"Art. 551 Recreational vehicles and recreational vehicle parks","f":"What power-supply cord rating is common on RVs?","b":"30-ampere 120-volt, or 50-ampere 120/240-volt 4-wire.","r":"NEC 551.46"},{"t":2,"c":"Art. 552 Park trailers","f":"What does Article 552 cover?","b":"Electrical conductors and equipment installed in park trailers.","r":"NEC 552.1"},{"t":2,"c":"Art. 552 Park trailers","f":"What defines a park trailer?","b":"A unit built on a single chassis mounted on wheels, with a gross trailer area not exceeding 400 sq ft in set-up mode.","r":"NEC 552.2"},{"t":2,"c":"Art. 553 Floating buildings","f":"What does Article 553 cover?","b":"Wiring, services, feeders and grounding for floating buildings, which are buildings secured in one location and floating on water.","r":"NEC 553.1"},{"t":2,"c":"Art. 553 Floating buildings","f":"Where must the service equipment for a floating building be located?","b":"On shore adjacent to the floating building, not on or in the floating building.","r":"NEC 553.4"},{"t":2,"c":"Art. 555 Marinas, boatyards, docks","f":"What is the electrical datum plane for a fixed pier subject to tidal fluctuation?","b":"A plane 2 ft (610 mm) above the highest tide level for the area.","r":"NEC 555.2"},{"t":2,"c":"Art. 555 Marinas, boatyards, docks","f":"What is the electrical datum plane for a floating pier?","b":"A plane 12 in. (305 mm) above the deck of the floating pier.","r":"NEC 555.2"},{"t":2,"c":"Art. 555 Marinas, boatyards, docks","f":"How high above the deck must electrical connections be on a floating pier?","b":"At least 12 in. (305 mm) above the deck, and not below the electrical datum plane.","r":"NEC 555.9"},{"t":2,"c":"Art. 610 Cranes and hoists","f":"What does Article 610 cover?","b":"Electrical equipment and wiring used in connection with cranes, monorail hoists, hoists and all runways.","r":"NEC 610.1"},{"t":2,"c":"Art. 610 Cranes and hoists","f":"Where do you find ampacities for conductors used with short-time rated crane and hoist motors?","b":"Table 610.14(A).","r":"NEC 610.14"},{"t":2,"c":"Art. 610 Cranes and hoists","f":"What must be grounded on a crane?","b":"All exposed non-current-carrying metal parts of cranes, hoists and accessories, including pendant controls.","r":"NEC 610.61"},{"t":2,"c":"Art. 620 Elevators","f":"What type of circuit supplies elevator car lighting, receptacles and ventilation?","b":"A separate branch circuit for each elevator car, not shared with machine room loads.","r":"NEC 620.22"},{"t":2,"c":"Art. 620 Elevators","f":"Which receptacles in elevator pits, hoistways and machine rooms need GFCI protection?","b":"All 125-volt, single-phase, 15- and 20-ampere receptacles installed in pits, hoistways, on car tops, in machine rooms and machinery spaces.","r":"NEC 620.85"},{"t":2,"c":"Art. 620 Elevators","f":"When is selective coordination required for elevators?","b":"Where more than one driving machine is supplied by a single feeder, the overcurrent devices must be selectively coordinated.","r":"NEC 620.62"},{"t":2,"c":"Art. 620 Elevators","f":"Where must the elevator disconnecting means be located?","b":"Where readily accessible to qualified persons, and lockable in the open position.","r":"NEC 620.51"},{"t":2,"c":"Art. 620 Elevators","f":"What are the minimum conductor sizes for elevator lighting and control circuits?","b":"14 AWG for lighting circuits, 20 AWG for control and operating circuits in raceways, and 24 AWG for traveling cable parallel pairs.","r":"NEC 620.12"},{"t":2,"c":"Art. 626 Electrified truck parking spaces","f":"What does Article 626 cover?","b":"Electrical conductors and equipment for supplying power to transport refrigeration units, trucks and other vehicles parked at electrified truck parking spaces.","r":"NEC 626.1"},{"t":2,"c":"Art. 630 Electric welders","f":"What does Article 630 cover?","b":"Electric arc welding, resistance welding and plasma cutting equipment and associated wiring.","r":"NEC 630.1"},{"t":2,"c":"Art. 630 Electric welders","f":"What is the supply conductor multiplier for a 100 percent duty cycle nonmotor-generator arc welder?","b":"1.00 times the rated primary current.","r":"NEC 630.11"},{"t":2,"c":"Art. 630 Electric welders","f":"What is the multiplier for a 50 percent duty cycle nonmotor-generator arc welder?","b":"0.71.","r":"NEC 630.11"},{"t":2,"c":"Art. 630 Electric welders","f":"What is the multiplier for a 20 percent or less duty cycle nonmotor-generator arc welder?","b":"0.45.","r":"NEC 630.11"},{"t":2,"c":"Art. 630 Electric welders","f":"What is the maximum rating of the overcurrent device for an arc welder?","b":"200 percent of the rated primary current of the welder (or 200 percent of I1max).","r":"NEC 630.12"},{"t":2,"c":"Art. 630 Electric welders","f":"What is the maximum overcurrent device rating for a resistance welder?","b":"300 percent of the rated primary current.","r":"NEC 630.32"},{"t":2,"c":"Art. 640 Audio signal processing","f":"What does Article 640 cover?","b":"Equipment and wiring for audio signal generation, recording, processing, amplification and reproduction, including public address and intercom systems.","r":"NEC 640.1"},{"t":2,"c":"Art. 645 Information technology equipment","f":"What does Article 645 cover?","b":"Equipment, power-supply wiring, grounding and fire protection in designated information technology equipment rooms.","r":"NEC 645.1"},{"t":2,"c":"Art. 645 Information technology equipment","f":"What is the minimum ampacity of branch-circuit conductors to IT equipment?","b":"125 percent of the total connected load.","r":"NEC 645.5"},{"t":2,"c":"Art. 645 Information technology equipment","f":"Where must the disconnecting means for an IT equipment room be located?","b":"Readily accessible at the principal exit doors, controlling all electronic equipment power and HVAC in the room.","r":"NEC 645.10"},{"t":2,"c":"Art. 645 Information technology equipment","f":"What must an IT equipment room have to use Article 645 relaxations?","b":"Listed IT equipment, disconnecting means, separate HVAC, fire-resistant construction and qualified maintenance personnel.","r":"NEC 645.4"},{"t":2,"c":"Art. 646 Modular data centers","f":"What does Article 646 cover?","b":"Modular data centers: prefabricated units housing IT equipment, in self-contained enclosures, installed as a unit.","r":"NEC 646.1"},{"t":2,"c":"Art. 647 Sensitive electronic equipment","f":"What does Article 647 cover?","b":"Use of a 60/120-volt single-phase system for sensitive electronic equipment, with 60 volts to ground.","r":"NEC 647.1"},{"t":2,"c":"Art. 650 Pipe organs","f":"What does Article 650 cover?","b":"Electrically operated pipe organs, including the electric supply and the console and chamber wiring.","r":"NEC 650.1"},{"t":2,"c":"Art. 660 X-ray equipment","f":"What does Article 660 cover?","b":"X-ray equipment operating at any frequency or voltage for industrial or other non-medical or non-dental use.","r":"NEC 660.1"},{"t":2,"c":"Art. 660 X-ray equipment","f":"How are supply conductors and overcurrent devices sized for X-ray equipment?","b":"Not less than 50 percent of the momentary rating or 100 percent of the long-time rating, whichever is greater.","r":"NEC 660.6"},{"t":2,"c":"Art. 665 Induction and dielectric heating equipment","f":"What does Article 665 cover?","b":"Induction and dielectric heating equipment and accessories for industrial and scientific applications, not for medical or dental.","r":"NEC 665.1"},{"t":2,"c":"Art. 668 Electrolytic cells","f":"What does Article 668 cover?","b":"Installation of the electrical components and accessory equipment of electrolytic cells, cell lines and process power supply for the production of aluminum, cadmium, chlorine and similar materials.","r":"NEC 668.1"},{"t":2,"c":"Art. 668 Electrolytic cells","f":"What is the cell line working zone?","b":"The space envelope where operation or maintenance is normally performed on or in the vicinity of exposed energized surfaces of cell lines or their attachments.","r":"NEC 668.2"},{"t":2,"c":"Art. 669 Electroplating","f":"What does Article 669 cover?","b":"Electroplating, anodizing, electropolishing, electrostripping and similar processes that use a dc power supply.","r":"NEC 669.1"},{"t":2,"c":"Art. 669 Electroplating","f":"What is the minimum ampacity of conductors supplying electroplating equipment?","b":"125 percent of the nameplate input rating of the rectifier or power supply.","r":"NEC 669.5"},{"t":2,"c":"Art. 670 Industrial machinery","f":"What does Article 670 cover?","b":"Electrical equipment, controls and wiring of industrial machinery as defined, driven by electric motors.","r":"NEC 670.1"},{"t":2,"c":"Art. 670 Industrial machinery","f":"How are supply conductors to industrial machinery sized?","b":"At least 125 percent of the full-load current of resistance heating loads, plus 125 percent of the highest-rated motor, plus the sum of all other loads.","r":"NEC 670.4"},{"t":2,"c":"Art. 670 Industrial machinery","f":"What must the industrial machinery nameplate show?","b":"Supply voltage, phase, frequency, full-load current, the maximum ampere rating of the short-circuit and ground-fault protective device, and the SCCR.","r":"NEC 670.3"},{"t":2,"c":"Art. 670 Industrial machinery","f":"Where must the machinery SCCR be marked?","b":"On the machine nameplate, and it must not be less than the available fault current at the supply terminals.","r":"NEC 670.3"},{"t":2,"c":"Art. 675 Electrically driven or controlled irrigation machines","f":"What does Article 675 cover?","b":"Electrical equipment and wiring for electrically driven or controlled irrigation machines, not including the supply wiring.","r":"NEC 675.1"},{"t":2,"c":"Art. 675 Electrically driven or controlled irrigation machines","f":"Where is the main disconnect for an irrigation machine located?","b":"Within sight of or on the machine, lockable in the open position.","r":"NEC 675.8"},{"t":2,"c":"Art. 682 Natural and artificially made bodies of water","f":"What does Article 682 cover?","b":"Electrical wiring and equipment in, on or adjacent to natural or artificially made bodies of water not otherwise covered, such as lakes, ponds, canals and irrigation channels.","r":"NEC 682.1"},{"t":2,"c":"Art. 685 Integrated electrical systems","f":"What does Article 685 cover?","b":"Integrated electrical systems other than unit equipment, in which orderly shutdown is necessary to ensure safe operation.","r":"NEC 685.1"},{"t":2,"c":"Art. 691 Large-scale photovoltaic electric supply stations","f":"What size system does Article 691 cover?","b":"Large-scale PV electric supply stations with an inverter generating capacity of no less than 5000 kW, not under exclusive utility control.","r":"NEC 691.1"},{"t":2,"c":"Art. 692 Fuel cell systems","f":"What does Article 692 cover?","b":"Installation of fuel cell power systems, which may be stand-alone or interactive with other electric power sources and may or may not include storage.","r":"NEC 692.1"},{"t":2,"c":"Art. 692 Fuel cell systems","f":"What is a fuel cell?","b":"An electrochemical system that consumes fuel to produce an electric current.","r":"NEC 692.2"},{"t":2,"c":"Art. 694 Wind electric systems","f":"What does Article 694 cover?","b":"Wind electric systems that include a wind turbine, wiring and controls, in stand-alone or interactive systems.","r":"NEC 694.1"},{"t":2,"c":"Art. 694 Wind electric systems","f":"What size is a small wind electric system?","b":"A system using a wind turbine of up to 100 kW rated output.","r":"NEC 694.2"},{"t":2,"c":"Art. 695 Fire pumps","f":"What is the minimum ampacity of fire pump supply conductors?","b":"125 percent of the fire pump motor full-load current, plus 100 percent of the pressure maintenance pump motor and accessory loads.","r":"NEC 695.6"},{"t":2,"c":"Art. 695 Fire pumps","f":"How much voltage drop is allowed at the fire pump controller during starting?","b":"No more than 15 percent below the controller-rated voltage at the line terminals.","r":"NEC 695.7"},{"t":2,"c":"Art. 695 Fire pumps","f":"How much voltage drop is allowed at the fire pump motor when running?","b":"No more than 5 percent below the voltage rating of the motor with the motor at 115 percent of its full-load current.","r":"NEC 695.7"},{"t":2,"c":"Art. 695 Fire pumps","f":"What must the overcurrent device for a fire pump carry?","b":"It must be selected or set to carry indefinitely the locked-rotor current of the fire pump motor.","r":"NEC 695.4"},{"t":2,"c":"Art. 701 Legally required standby systems","f":"How quickly must a legally required standby system supply power?","b":"Within 60 seconds of loss of normal power.","r":"NEC 701.12"},{"t":2,"c":"Art. 701 Legally required standby systems","f":"What does Article 701 cover?","b":"Standby systems required and classed as legally required by municipal, state, federal or other codes or authorities having jurisdiction.","r":"NEC 701.1"},{"t":2,"c":"Art. 701 Legally required standby systems","f":"Is selective coordination required for legally required standby overcurrent devices?","b":"Yes, they must be selectively coordinated with all supply-side overcurrent devices.","r":"NEC 701.32"},{"t":2,"c":"Art. 701 Legally required standby systems","f":"May legally required standby wiring share raceways with general wiring?","b":"Yes, it is permitted to occupy the same raceways, cables, boxes and cabinets as other general wiring.","r":"NEC 701.10"},{"t":2,"c":"Art. 702 Optional standby systems","f":"What does Article 702 cover?","b":"Optional standby systems intended to protect public or private facilities or property where life safety does not depend on the performance of the system.","r":"NEC 702.1"},{"t":2,"c":"Art. 702 Optional standby systems","f":"Is transfer equipment required for optional standby?","b":"Yes, transfer equipment must prevent inadvertent interconnection of normal and alternate sources.","r":"NEC 702.5"},{"t":2,"c":"Art. 702 Optional standby systems","f":"Where is a sign required for optional standby sources?","b":"At the service-entrance equipment, showing the type and location of on-site optional standby power sources.","r":"NEC 702.7"},{"t":2,"c":"Art. 706 Energy storage systems","f":"What does Article 706 cover?","b":"All energy storage systems (ESS) that may be stand-alone or interactive with other power production sources.","r":"NEC 706.1"},{"t":2,"c":"Art. 706 Energy storage systems","f":"Must ESS equipment be listed?","b":"Yes, ESS must be listed.","r":"NEC 706.5"},{"t":2,"c":"Art. 706 Energy storage systems","f":"Is a disconnecting means required for an ESS?","b":"Yes, a disconnecting means must be provided to disconnect the ESS from all wiring systems, including other ESS, power production sources and utilization equipment.","r":"NEC 706.15"},{"t":2,"c":"Art. 708 Critical operations power systems","f":"What does Article 708 cover?","b":"Power systems for facilities or parts of facilities that require continuous operation for public safety, emergency management, national security or business continuity.","r":"NEC 708.1"},{"t":2,"c":"Art. 708 Critical operations power systems","f":"How long must COPS onsite fuel supply last?","b":"At least 72 hours of full-demand operation.","r":"NEC 708.20"},{"t":2,"c":"Art. 708 Critical operations power systems","f":"Is selective coordination required in COPS?","b":"Yes, overcurrent devices must be selectively coordinated.","r":"NEC 708.54"},{"t":2,"c":"Art. 710 Stand-alone systems","f":"What does Article 710 cover?","b":"Electric power production systems that operate in stand-alone mode, not connected to a utility.","r":"NEC 710.1"},{"t":2,"c":"Art. 712 Direct current microgrids","f":"What does Article 712 cover?","b":"Direct current microgrids that may be stand-alone or interactive with other electric power sources.","r":"NEC 712.1"},{"t":2,"c":"Art. 712 Direct current microgrids","f":"What is a dc microgrid?","b":"A power distribution system with more than one interconnected dc power source, energy storage and dc loads, operating as a system.","r":"NEC 712.2"},{"t":2,"c":"Art. 770 Optical fiber cables and raceways","f":"What does Article 770 cover?","b":"Optical fiber cables and raceways, installation of optical fiber cables, and the loads they may power.","r":"NEC 770.1"},{"t":2,"c":"Art. 770 Optical fiber cables and raceways","f":"What is the difference between OFN and OFC?","b":"OFN (nonconductive) has no metallic members. OFC (conductive) contains non-current-carrying conductive members such as metallic strength members or armor.","r":"NEC 770.2"},{"t":2,"c":"Art. 770 Optical fiber cables and raceways","f":"Which optical fiber cable type is a plenum cable?","b":"OFNP or OFCP.","r":"NEC 770.179"},{"t":2,"c":"Art. 770 Optical fiber cables and raceways","f":"Which optical fiber cable type is a riser cable?","b":"OFNR or OFCR.","r":"NEC 770.179"},{"t":2,"c":"Art. 770 Optical fiber cables and raceways","f":"Which optical fiber cable type is general purpose?","b":"OFNG or OFN (nonconductive); OFCG or OFC (conductive).","r":"NEC 770.179"},{"t":2,"c":"Art. 805 Communications circuits","f":"What does Article 805 cover?","b":"Communications circuits and equipment installed within buildings, such as telephone and data systems.","r":"NEC 805.1"},{"t":2,"c":"Art. 805 Communications circuits","f":"Which communications cable is a plenum cable?","b":"CMP.","r":"NEC 805.179"},{"t":2,"c":"Art. 805 Communications circuits","f":"Which communications cable is a riser cable?","b":"CMR.","r":"NEC 805.179"},{"t":2,"c":"Art. 805 Communications circuits","f":"Which communications cable is general purpose?","b":"CM, or CMG.","r":"NEC 805.179"},{"t":2,"c":"Art. 805 Communications circuits","f":"Which communications cable is limited use?","b":"CMX, which is limited to dwellings and raceways.","r":"NEC 805.179"},{"t":2,"c":"Art. 810 Radio and television equipment","f":"What does Article 810 cover?","b":"Radio and television receiving equipment, amateur radio transmitting and receiving equipment, and the antennas and lead-ins.","r":"NEC 810.1"},{"t":2,"c":"Art. 810 Radio and television equipment","f":"What is the minimum size of an antenna mast grounding conductor?","b":"10 AWG copper, 8 AWG aluminum, or 17 AWG copper-clad steel or bronze.","r":"NEC 810.21"},{"t":2,"c":"Art. 810 Radio and television equipment","f":"What is the minimum size of bonding jumper between antenna and power grounding electrodes?","b":"6 AWG copper or equivalent.","r":"NEC 810.21"},{"t":2,"c":"Art. 820 Community antenna television and radio distribution systems","f":"What does Article 820 cover?","b":"Coaxial cable distribution of radio frequency signals typically employed in CATV systems.","r":"NEC 820.1"},{"t":2,"c":"Art. 820 Community antenna television and radio distribution systems","f":"What is the minimum size of a coaxial cable shield grounding conductor?","b":"14 AWG with current-carrying capacity approximately that of the shield, but not required to be larger than 6 AWG.","r":"NEC 820.100"},{"t":2,"c":"Art. 820 Community antenna television and radio distribution systems","f":"Where is the outer shield of a coaxial cable grounded?","b":"At the building premises, as close as practicable to the point of cable entrance or attachment.","r":"NEC 820.93"},{"t":2,"c":"Art. 820 Community antenna television and radio distribution systems","f":"Which CATV cable is plenum?","b":"CATVP.","r":"NEC 820.179"},{"t":2,"c":"Art. 820 Community antenna television and radio distribution systems","f":"Which CATV cable is riser?","b":"CATVR.","r":"NEC 820.179"},{"t":2,"c":"Art. 830 Network-powered broadband communications systems","f":"What does Article 830 cover?","b":"Network-powered broadband communications systems, which provide voice, audio, video, data and interactive services through a network interface unit.","r":"NEC 830.1"},{"t":2,"c":"Art. 840 Premises-powered broadband communications systems","f":"What does Article 840 cover?","b":"Premises-powered broadband communications systems, which provide voice, video, data and interactive services through a premises network interface unit.","r":"NEC 840.1"},{"t":3,"c":"Ohm's law and power","f":"State Ohm's law in all three forms.","b":"E = I x R, I = E / R, R = E / I. Example: 120 V across a 24 ohm load gives I = 120 / 24 = 5 A.","r":"Electrical theory"},{"t":3,"c":"Ohm's law and power","f":"What are the three basic power formulas?","b":"P = I x E, P = I squared x R, P = E squared / R (P in watts). Example: a 10 ohm element on 120 V uses P = 120 x 120 / 10 = 1,440 W.","r":"Electrical theory"},{"t":3,"c":"Ohm's law and power","f":"Power formula using current and voltage.","b":"P = I x E. Example: 20 A at 240 V = 4,800 W. Rearranged: I = P / E, E = P / I.","r":"Electrical theory"},{"t":3,"c":"Ohm's law and power","f":"Power formula using current and resistance.","b":"P = I squared x R. Example: 15 A through 2 ohms = 15 x 15 x 2 = 450 W. Use it to find heat (watts lost) in a conductor.","r":"Electrical theory"},{"t":3,"c":"Ohm's law and power","f":"Power formula using voltage and resistance.","b":"P = E squared / R. Example: 120 V across 14.4 ohms = 14,400 / 14.4 = 1,000 W.","r":"Electrical theory"},{"t":3,"c":"Ohm's law and power","f":"How do you find the resistance of a heater from its nameplate?","b":"R = E squared / P. Example: a 4,800 W, 240 V heater has R = 240 x 240 / 4,800 = 12 ohms.","r":"Electrical theory"},{"t":3,"c":"Ohm's law and power","f":"How do you find current from a watt rating?","b":"I = P / E for single-phase (add PF if the load is not resistive). Example: a 1,500 W, 120 V heater draws 1,500 / 120 = 12.5 A.","r":"Electrical theory"},{"t":3,"c":"Ohm's law and power","f":"What happens to power if voltage changes and resistance stays the same?","b":"Power changes with the SQUARE of the voltage ratio: P2 = P1 x (E2 / E1) squared. Example: a 4,000 W, 240 V heater on 208 V gives 4,000 x (208/240) squared = about 3,004 W.","r":"Electrical theory"},{"t":3,"c":"Ohm's law and power","f":"What happens to current and power if you double the current in a fixed resistance?","b":"Power goes up four times because P = I squared x R. Example: 10 A in 5 ohms = 500 W; 20 A in 5 ohms = 2,000 W.","r":"Electrical theory"},{"t":3,"c":"Ohm's law and power","f":"Formula for kilowatt-hours and energy cost.","b":"kWh = kW x hours. Cost = kWh x rate per kWh. Example: 3 kW for 4 hours = 12 kWh; at $0.12 per kWh the cost is 12 x 0.12 = $1.44.","r":"Electrical theory"},{"t":3,"c":"Ohm's law and power","f":"Watts and BTU per hour conversion.","b":"1 W = 3.412 BTU/hr, so 1 kW = 3,412 BTU/hr. Example: a 5 kW heat strip makes 5 x 3,412 = 17,060 BTU/hr.","r":"Electrical theory"},{"t":3,"c":"Ohm's law and power","f":"Joule heating in a conductor: how do you find the power wasted?","b":"Loss (W) = I squared x R of the conductor (use total round-trip resistance). Example: 20 A through 0.4 ohm of wire loses 20 x 20 x 0.4 = 160 W.","r":"Electrical theory"},{"t":3,"c":"Series and parallel circuits","f":"Total resistance of resistors in series.","b":"Rt = R1 + R2 + R3 ... Example: 10 + 20 + 30 = 60 ohms. Current is the same everywhere in a series circuit.","r":"Electrical theory"},{"t":3,"c":"Series and parallel circuits","f":"Voltage in a series circuit.","b":"Source voltage = sum of the voltage drops (Kirchhoff's voltage law). Example: drops of 30 V, 45 V and 45 V on a 120 V source add to 120 V.","r":"Electrical theory"},{"t":3,"c":"Series and parallel circuits","f":"Total resistance of resistors in parallel (general formula).","b":"1/Rt = 1/R1 + 1/R2 + 1/R3 ... Example: 10, 20 and 20 ohms: 0.1 + 0.05 + 0.05 = 0.2, so Rt = 5 ohms. Rt is always smaller than the smallest branch.","r":"Electrical theory"},{"t":3,"c":"Series and parallel circuits","f":"Shortcut for two resistors in parallel.","b":"Rt = (R1 x R2) / (R1 + R2) (product over sum). Example: 12 and 4 ohms: 48 / 16 = 3 ohms.","r":"Electrical theory"},{"t":3,"c":"Series and parallel circuits","f":"Shortcut for equal resistors in parallel.","b":"Rt = R / n. Example: four 40 ohm lamps in parallel = 40 / 4 = 10 ohms.","r":"Electrical theory"},{"t":3,"c":"Series and parallel circuits","f":"How do you solve a combination (series-parallel) circuit?","b":"Reduce each parallel group to one equivalent resistance, then add it to the series resistors. Example: 6 ohm in series with (12 || 4): 12 || 4 = 3, so Rt = 6 + 3 = 9 ohms.","r":"Electrical theory"},{"t":3,"c":"Series and parallel circuits","f":"Current rule for parallel circuits.","b":"Voltage is the same across every branch; total current = sum of branch currents (Kirchhoff's current law). Example: 120 V across 24 ohm and 12 ohm branches: 5 A + 10 A = 15 A.","r":"Electrical theory"},{"t":3,"c":"Series and parallel circuits","f":"Kirchhoff's current law.","b":"Current into a node equals current out of the node. Example: 15 A enters a junction and splits 5 A and 10 A; 5 + 10 = 15 A.","r":"Electrical theory"},{"t":3,"c":"Series and parallel circuits","f":"Voltage divider formula for series resistors.","b":"V across R1 = E x R1 / Rt. Example: 120 V across 30 and 90 ohms in series; the 30 ohm drop = 120 x 30 / 120 = 30 V.","r":"Electrical theory"},{"t":3,"c":"Series and parallel circuits","f":"What happens to total current if one resistor in a series circuit opens?","b":"Total current drops to zero because the path is broken (the full source voltage appears across the open). In parallel only that branch stops; the others keep their current.","r":"Electrical theory"},{"t":3,"c":"Single-phase and three-phase power","f":"Single-phase current from VA, kVA or kW.","b":"I = VA / E, or I = (kVA x 1,000) / E, or I = W / (E x PF). Example: 10 kVA at 240 V = 10,000 / 240 = 41.7 A.","r":"Electrical theory"},{"t":3,"c":"Single-phase and three-phase power","f":"Three-phase current from kVA.","b":"I = (kVA x 1,000) / (1.732 x E). Example: 75 kVA at 208 V = 75,000 / (1.732 x 208) = 208 A.","r":"Electrical theory"},{"t":3,"c":"Single-phase and three-phase power","f":"Three-phase power formula.","b":"P (W) = 1.732 x E(line) x I(line) x PF. VA = 1.732 x E x I. Example: 208 V, 30 A, PF 1.0 gives 1.732 x 208 x 30 = 10,808 W (about 10.8 kW).","r":"Electrical theory"},{"t":3,"c":"Single-phase and three-phase power","f":"Where does 1.732 come from?","b":"It is the square root of 3, the ratio between line and phase values in a balanced three-phase system. sqrt(3) = 1.732.","r":"Electrical theory"},{"t":3,"c":"Single-phase and three-phase power","f":"Wye connection: line and phase relationships.","b":"Line voltage = 1.732 x phase voltage; line current = phase current. Example: 120 V phase voltage gives 1.732 x 120 = 208 V line-to-line.","r":"Electrical theory"},{"t":3,"c":"Single-phase and three-phase power","f":"Delta connection: line and phase relationships.","b":"Line voltage = phase voltage; line current = 1.732 x phase current. Example: 20 A phase current gives 1.732 x 20 = 34.6 A in each line.","r":"Electrical theory"},{"t":3,"c":"Single-phase and three-phase power","f":"How do you get line-to-neutral voltage from line-to-line voltage on a wye system?","b":"Divide by 1.732. Example: 208 / 1.732 = 120 V; 480 / 1.732 = 277 V.","r":"Electrical theory"},{"t":3,"c":"Single-phase and three-phase power","f":"What is the high leg (wild leg) voltage on a 120/240 V 4-wire delta?","b":"The high leg measures 208 V to neutral: 1.732 x 120 = 208 V. It must be identified by orange color or other effective means.","r":"110.15"},{"t":3,"c":"Single-phase and three-phase power","f":"Relationship of kW, kVA and power factor.","b":"kW = kVA x PF; kVA = kW / PF; PF = kW / kVA. Example: 50 kVA at 0.8 PF = 40 kW.","r":"Electrical theory"},{"t":3,"c":"Single-phase and three-phase power","f":"How do you find kVAR (reactive power)?","b":"kVAR = square root of (kVA squared - kW squared). Example: 50 kVA and 40 kW: sqrt(2,500 - 1,600) = sqrt(900) = 30 kVAR.","r":"Electrical theory"},{"t":3,"c":"Single-phase and three-phase power","f":"What does power factor tell you?","b":"PF = true power (W) / apparent power (VA) = cosine of the phase angle. Example: 8,000 W and 10,000 VA gives PF = 0.8 (angle about 36.9 degrees).","r":"Electrical theory"},{"t":3,"c":"Single-phase and three-phase power","f":"Power factor correction: capacitor kVAR needed.","b":"kVAR(cap) = kW x (tan of old angle - tan of new angle). Example: 100 kW from PF 0.8 (tan 0.75) to 1.0 (tan 0) needs 100 x 0.75 = 75 kVAR.","r":"Electrical theory"},{"t":3,"c":"Single-phase and three-phase power","f":"Total current in a balanced three-phase resistive load, delta vs wye.","b":"Wye (R each leg): I(line) = E(L-N) / R. Delta: I(phase) = E(L-L) / R and I(line) = 1.732 x I(phase). Example: 10 ohm on 208 V wye: 120 / 10 = 12 A; delta: 208 / 10 = 20.8 A phase, 36 A line.","r":"Electrical theory"},{"t":3,"c":"Single-phase and three-phase power","f":"What does the neutral carry in a balanced three-phase wye system?","b":"Essentially zero current for linear balanced loads; with unbalance it carries the vector difference. Example: three 12 A phase currents balanced = 0 A on the neutral.","r":"Electrical theory"},{"t":3,"c":"Voltage drop","f":"Single-phase voltage drop formula.","b":"VD = (2 x K x I x L) / CM, L is one-way length in feet. Example: 12 AWG Cu (6,530 CM), 20 A, 100 ft: 2 x 12.9 x 20 x 100 / 6,530 = 7.9 V.","r":"Electrical theory"},{"t":3,"c":"Voltage drop","f":"Three-phase voltage drop formula.","b":"VD = (1.732 x K x I x L) / CM. Example: 8 AWG Cu (16,510 CM), 40 A, 150 ft: 1.732 x 12.9 x 40 x 150 / 16,510 = 8.1 V.","r":"Electrical theory"},{"t":3,"c":"Voltage drop","f":"What are the K values used in the voltage drop formula?","b":"K = 12.9 ohm-CM per foot for copper and 21.2 for aluminum (at 75 degrees C). Example: aluminum drops about 21.2 / 12.9 = 1.64 times as much as copper of the same size.","r":"Electrical theory"},{"t":3,"c":"Voltage drop","f":"How do you find percent voltage drop?","b":"% VD = (VD / source voltage) x 100. Example: 7.9 V drop on a 240 V circuit = 7.9 / 240 x 100 = 3.3 percent.","r":"Electrical theory"},{"t":3,"c":"Voltage drop","f":"What voltage drop percentages does the NEC recommend for branch circuits and feeders?","b":"3 percent maximum on the branch circuit or feeder, and 5 percent total for feeder plus branch circuit combined. Informational notes, so not mandatory. Example: 3 percent of 120 V = 3.6 V.","r":"210.19(A) Informational Note"},{"t":3,"c":"Voltage drop","f":"How do you size a conductor for a voltage drop limit?","b":"CM = (2 x K x I x L) / VD(allowed) for single-phase (use 1.732 for three-phase), then pick the smallest AWG whose CM is at least that. Example: 20 A, 150 ft, 120 V, 3 percent (3.6 V): 2 x 12.9 x 20 x 150 / 3.6 = 21,500 CM, so 6 AWG (26,240 CM).","r":"Electrical theory"},{"t":3,"c":"Voltage drop","f":"How do you find the maximum length for a voltage drop limit?","b":"L = (VD x CM) / (2 x K x I) single-phase. Example: 12 AWG Cu, 16 A, 120 V, 3 percent (3.6 V): 3.6 x 6,530 / (2 x 12.9 x 16) = 56.9 ft.","r":"Electrical theory"},{"t":3,"c":"Voltage drop","f":"What voltage reaches the load after drop?","b":"E(load) = E(source) - VD. Example: 240 V source with 7.2 V drop gives 232.8 V at the load.","r":"Electrical theory"},{"t":3,"c":"Voltage drop","f":"Circular mil (CM) definition and formula.","b":"CM = diameter in mils squared (1 mil = 0.001 in). Example: a 0.1 in (100 mil) round wire is 100 x 100 = 10,000 CM.","r":"NEC Chapter 9 Table 8"},{"t":3,"c":"Voltage drop","f":"Circular mil areas of common copper sizes.","b":"14 AWG 4,110; 12 AWG 6,530; 10 AWG 10,380; 8 AWG 16,510; 6 AWG 26,240; 4 AWG 41,740; 2 AWG 66,360; 1/0 105,600. Example: going from 12 to 10 AWG adds 10,380 / 6,530 = 1.6 times the area.","r":"NEC Chapter 9 Table 8"},{"t":3,"c":"Voltage drop","f":"Resistance of a conductor from K, length and area.","b":"R = (K x L) / CM. Example: 500 ft of 12 AWG Cu: 12.9 x 500 / 6,530 = 0.99 ohm.","r":"Electrical theory"},{"t":3,"c":"Voltage drop","f":"How does temperature change conductor resistance?","b":"R2 = R1 x [1 + alpha x (T2 - T1)]; alpha is about 0.00393 per degree C for copper (referenced to 20 C). Example: 1.00 ohm at 20 C becomes 1 x (1 + 0.00393 x 55) = 1.22 ohms at 75 C.","r":"Electrical theory"},{"t":3,"c":"Transformers","f":"Transformer turns ratio and voltage.","b":"Ep / Es = Np / Ns. Example: 480 V primary, 240 turns primary and 120 turns secondary gives Es = 480 x 120 / 240 = 240 V.","r":"Electrical theory"},{"t":3,"c":"Transformers","f":"Transformer current ratio.","b":"Ip / Is = Ns / Np (current is inversely proportional to voltage). Example: 480 V to 120 V step down: 10 A secondary current reflects as 10 x 120 / 480 = 2.5 A primary.","r":"Electrical theory"},{"t":3,"c":"Transformers","f":"Single-phase transformer full-load current.","b":"I = (kVA x 1,000) / E. Example: 25 kVA, 240 V secondary: 25,000 / 240 = 104.2 A; 480 V primary: 52.1 A.","r":"Electrical theory"},{"t":3,"c":"Transformers","f":"Three-phase transformer full-load current.","b":"I = (kVA x 1,000) / (1.732 x E). Example: 45 kVA, 480 V primary = 54.1 A; 208 V secondary = 124.9 A.","r":"Electrical theory"},{"t":3,"c":"Transformers","f":"Maximum kVA a transformer can supply.","b":"Single-phase kVA = E x I / 1,000; three-phase kVA = 1.732 x E x I / 1,000. Example: 208 V at 300 A three-phase = 1.732 x 208 x 300 / 1,000 = 108 kVA.","r":"Electrical theory"},{"t":3,"c":"Transformers","f":"Transformer loading percentage.","b":"% load = (connected kVA / rated kVA) x 100. Example: 36 kVA load on a 45 kVA transformer = 80 percent.","r":"Electrical theory"},{"t":3,"c":"Transformers","f":"Transformer primary overcurrent protection (primary only, 1,000 V or less).","b":"9 A or more primary current: up to 125 percent of primary FLA, next standard size permitted. Under 9 A: 167 percent. Under 2 A: 300 percent. Example: 54.1 A x 1.25 = 67.6 A, next standard size 70 A.","r":"Table 450.3(B)"},{"t":3,"c":"Transformers","f":"Available short-circuit current at a transformer secondary (rule of thumb).","b":"I(sc) = FLA / per-unit impedance (infinite primary source assumed). Example: 150 kVA, 208 V three-phase has FLA 416 A; at 2 percent Z: 416 / 0.02 = 20,800 A.","r":"Electrical theory"},{"t":3,"c":"Transformers","f":"Are kVA ratings the same on the primary and secondary of an ideal transformer?","b":"Yes, VA in = VA out (ideal). Example: 480 V x 10 A = 4,800 VA primary equals 120 V x 40 A = 4,800 VA secondary.","r":"Electrical theory"},{"t":3,"c":"AC theory","f":"Convert RMS to peak voltage.","b":"Peak = 1.414 x RMS. Example: 120 V RMS has a peak of 1.414 x 120 = 169.7 V.","r":"Electrical theory"},{"t":3,"c":"AC theory","f":"Convert peak to RMS, and average of a sine wave.","b":"RMS = 0.707 x peak; average (half cycle) = 0.637 x peak. Example: 170 V peak = 120.2 V RMS.","r":"Electrical theory"},{"t":3,"c":"AC theory","f":"Frequency and period.","b":"T = 1 / f, f = 1 / T. Example: 60 Hz has a period of 1 / 60 = 0.01667 s (16.67 ms).","r":"Electrical theory"},{"t":3,"c":"AC theory","f":"Inductive reactance formula.","b":"XL = 2 x pi x f x L (ohms; L in henries). Example: 0.1 H at 60 Hz = 6.283 x 60 x 0.1 = 37.7 ohms. XL rises with frequency.","r":"Electrical theory"},{"t":3,"c":"AC theory","f":"Capacitive reactance formula.","b":"XC = 1 / (2 x pi x f x C) (C in farads). Example: 100 microfarads at 60 Hz = 1 / (6.283 x 60 x 0.0001) = 26.5 ohms. XC falls as frequency rises.","r":"Electrical theory"},{"t":3,"c":"AC theory","f":"Impedance of a series RL circuit.","b":"Z = square root of (R squared + XL squared). Example: R = 30, XL = 40: sqrt(900 + 1,600) = 50 ohms. I = E / Z.","r":"Electrical theory"},{"t":3,"c":"AC theory","f":"Impedance of a series RLC circuit.","b":"Z = square root of (R squared + (XL - XC) squared). Example: R = 10, XL = 30, XC = 18: sqrt(100 + 144) = 15.6 ohms.","r":"Electrical theory"},{"t":3,"c":"AC theory","f":"Phase relationship in inductive and capacitive circuits.","b":"ELI the ICE man: in an inductor, E leads I (current lags); in a capacitor, I leads E. Motors are inductive, so current lags voltage.","r":"Electrical theory"},{"t":3,"c":"AC theory","f":"Resonant frequency of a series LC circuit.","b":"f = 1 / (2 x pi x sqrt(L x C)). At resonance XL = XC and Z = R. Example: L = 0.1 H, C = 100 microfarads: sqrt(0.00001) = 0.003162, f = 1 / (6.283 x 0.003162) = 50.3 Hz.","r":"Electrical theory"},{"t":3,"c":"AC theory","f":"Capacitors in parallel and in series.","b":"Parallel: Ct = C1 + C2. Series: Ct = (C1 x C2) / (C1 + C2) (opposite of resistors). Example: 10 and 40 microfarads in series = 400 / 50 = 8 microfarads.","r":"Electrical theory"},{"t":3,"c":"AC theory","f":"Power factor and true power in single-phase AC.","b":"P = E x I x PF. Example: 240 V, 25 A, PF 0.85 = 240 x 25 x 0.85 = 5,100 W.","r":"Electrical theory"},{"t":3,"c":"Motors","f":"Horsepower to watts.","b":"1 HP = 746 W. Example: 5 HP = 5 x 746 = 3,730 W output.","r":"Electrical theory"},{"t":3,"c":"Motors","f":"Motor efficiency formula.","b":"Efficiency = output / input. Input watts = HP x 746 / efficiency. Example: 10 HP at 90 percent efficiency draws 7,460 / 0.9 = 8,289 W.","r":"Electrical theory"},{"t":3,"c":"Motors","f":"Three-phase motor current from horsepower.","b":"I = (HP x 746) / (1.732 x E x efficiency x PF). Example: 10 HP, 460 V, 0.90 eff, 0.85 PF: 7,460 / (1.732 x 460 x 0.9 x 0.85) = 12.2 A.","r":"Electrical theory"},{"t":3,"c":"Motors","f":"Single-phase motor current from horsepower.","b":"I = (HP x 746) / (E x efficiency x PF). Example: 2 HP, 230 V, 0.85 eff, 0.8 PF: 1,492 / (230 x 0.85 x 0.8) = 9.5 A.","r":"Electrical theory"},{"t":3,"c":"Motors","f":"Synchronous speed formula.","b":"Ns = 120 x f / P (P = number of poles). Example: 60 Hz, 4 poles: 120 x 60 / 4 = 1,800 RPM.","r":"Electrical theory"},{"t":3,"c":"Motors","f":"Slip formula.","b":"% slip = (Ns - Nr) / Ns x 100. Example: 1,800 RPM sync and 1,750 RPM rotor: 50 / 1,800 = 2.8 percent.","r":"Electrical theory"},{"t":3,"c":"Motors","f":"Motor torque from horsepower and speed.","b":"Torque (lb-ft) = HP x 5,252 / RPM. Example: 10 HP at 1,750 RPM = 52,520 / 1,750 = 30 lb-ft.","r":"Electrical theory"},{"t":3,"c":"Motors","f":"Which table do you use for motor full-load current when sizing conductors and disconnects?","b":"The NEC tables, not the nameplate: Table 430.248 (single-phase), 430.250 (three-phase). Example: 10 HP, 460 V three-phase = 14 A (230 V = 28 A, 208 V = 30.8 A).","r":"430.6(A)(1)"},{"t":3,"c":"Motors","f":"Table 430.250 anchors, three-phase induction motors.","b":"At 460 V: 1 HP 1.8 A; 5 HP 7.6 A; 7.5 HP 11 A; 10 HP 14 A; 15 HP 21 A; 20 HP 27 A; 25 HP 34 A. At 230 V the current is double. Example: 5 HP at 230 V = 15.2 A.","r":"Table 430.250"},{"t":3,"c":"Motors","f":"Table 430.248 anchors, single-phase motors.","b":"1 HP: 16 A at 115 V and 8 A at 230 V. 2 HP: 24 A at 115 V and 12 A at 230 V. 1/2 HP: 9.8 A at 115 V and 4.9 A at 230 V. Example: 1 HP on 230 V uses 8 A.","r":"Table 430.248"},{"t":3,"c":"Motors","f":"Branch-circuit conductor size for a single motor.","b":"At least 125 percent of motor FLC from the table. Example: 10 HP, 460 V: 14 A x 1.25 = 17.5 A minimum ampacity.","r":"430.22"},{"t":3,"c":"Motors","f":"Motor overload protection setting.","b":"Nameplate FLA x 125 percent (service factor 1.15 or more, or temperature rise 40 C or less), otherwise x 115 percent. Example: 12.2 A nameplate x 1.25 = 15.25 A.","r":"430.32(A)(1)"},{"t":3,"c":"Motors","f":"Maximum short-circuit/ground-fault protection for a motor branch circuit (squirrel cage).","b":"Percent of FLC from the table: nontime-delay fuse 300; dual-element fuse 175; instantaneous-trip breaker 800; inverse-time breaker 250. Example: 14 A x 2.5 = 35 A, next standard size up is 35 A breaker.","r":"Table 430.52"},{"t":3,"c":"Motors","f":"Conductors supplying several motors (feeder).","b":"125 percent of the largest motor FLC plus the sum of the FLCs of all the other motors. Example: 14 A, 11 A and 7.6 A motors: 14 x 1.25 + 11 + 7.6 = 36.1 A.","r":"430.24"},{"t":3,"c":"Motors","f":"Feeder overcurrent protection for several motors.","b":"Largest branch-circuit protective device rating plus the sum of the FLCs of the other motors. Example: 35 A device for the 14 A motor plus 11 A plus 7.6 A = 53.6 A, next lower standard size 50 A.","r":"430.62(A)"},{"t":3,"c":"Motors","f":"Motor disconnecting means rating.","b":"Not less than 115 percent of the motor's full-load current from the table. Example: 28 A motor x 1.15 = 32.2 A, so a 30 A switch is too small; use the next size up.","r":"430.110(A)"},{"t":3,"c":"Motors","f":"Approximate locked-rotor current of an induction motor.","b":"About 6 times full-load current at starting. Example: 14 A FLC motor draws roughly 84 A at start.","r":"Electrical theory"},{"t":3,"c":"Motors","f":"Hermetic refrigerant motor-compressor conductors and protection.","b":"Conductors at least 125 percent of rated-load current (or branch-circuit selection current if larger). Maximum short-circuit device 175 percent of RLC (225 percent if that will not start the motor). Example: 20 A RLC: 25 A minimum ampacity.","r":"440.32, 440.22(A)"},{"t":3,"c":"Load calculations and ampacity","f":"Continuous load rule for branch circuits and feeders.","b":"Size OCPD and conductors at 125 percent of the continuous load plus 100 percent of noncontinuous load. Example: 16 A continuous needs 16 x 1.25 = 20 A, so a 20 A breaker.","r":"210.20(A), 215.3"},{"t":3,"c":"Load calculations and ampacity","f":"The 80 percent rule: maximum continuous load on an OCPD.","b":"Continuous load must not exceed 80 percent of the OCPD rating (the same rule as 125 percent). Example: a 20 A breaker supports 16 A continuous; a 100 A breaker supports 80 A.","r":"210.20(A)"},{"t":3,"c":"Load calculations and ampacity","f":"Cord-and-plug connected equipment on a 15 or 20 A branch circuit.","b":"One cord-and-plug load not fastened in place may not exceed 80 percent of the circuit rating. Example: 20 A circuit: 16 A maximum. Fastened-in-place appliances on a circuit with other loads: 50 percent.","r":"210.23(A)"},{"t":3,"c":"Load calculations and ampacity","f":"Small conductor overcurrent protection limits.","b":"14 AWG Cu max 15 A, 12 AWG Cu max 20 A, 10 AWG Cu max 30 A (unless allowed otherwise). Example: 12 AWG on a 25 A breaker is a violation.","r":"240.4(D)"},{"t":3,"c":"Load calculations and ampacity","f":"Standard ampere ratings for fuses and circuit breakers.","b":"15, 20, 25, 30, 35, 40, 45, 50, 60, 70, 80, 90, 100, 110, 125, 150, 175, 200, 225, 250, 300, 350, 400, 450, 500, 600, 700, 800, 1000, 1200, 1600, 2000, 2500, 3000, 4000, 5000, 6000. Example: a calculated 67.6 A rounds to 70 A.","r":"240.6(A)"},{"t":3,"c":"Load calculations and ampacity","f":"When can you round up to the next standard OCPD size?","b":"When the conductor ampacity does not match a standard size and the device is 800 A or less (and other conditions in 240.4(B) are met). Example: 55 A conductor ampacity can use a 60 A breaker.","r":"240.4(B)"},{"t":3,"c":"Load calculations and ampacity","f":"Table 310.16 anchors for copper at 75 C.","b":"14 AWG 20 A; 12 AWG 25 A; 10 AWG 35 A; 8 AWG 50 A; 6 AWG 65 A; 4 AWG 85 A; 3 AWG 100 A; 2 AWG 115 A; 1 AWG 130 A; 1/0 150 A; 2/0 175 A; 3/0 200 A; 4/0 230 A. Example: 100 A load calls for 3 AWG (75 C column).","r":"Table 310.16"},{"t":3,"c":"Load calculations and ampacity","f":"Table 310.16 anchors for copper at 60 C and 90 C.","b":"60 C: 14=15, 12=20, 10=30, 8=40, 6=55, 4=70, 3=85, 2=95, 1=110 A. 90 C: 14=25, 12=30, 10=40, 8=55, 6=75, 4=95 A. Example: 10 AWG is 30 A at 60 C and 40 A at 90 C.","r":"Table 310.16"},{"t":3,"c":"Load calculations and ampacity","f":"Table 310.16 anchors for aluminum at 75 C.","b":"12 AWG 20 A; 10 AWG 30 A; 8 AWG 40 A; 6 AWG 50 A; 4 AWG 65 A; 3 AWG 75 A; 2 AWG 90 A; 1 AWG 100 A; 1/0 120 A; 2/0 135 A; 3/0 155 A; 4/0 180 A. Example: 4 AWG Al is 65 A at 75 C.","r":"Table 310.16"},{"t":3,"c":"Load calculations and ampacity","f":"Which temperature column do you use at terminations?","b":"Circuits rated 100 A or less (or 14 to 1 AWG) use the 60 C column unless equipment is listed for 75 C; over 100 A use the 75 C column. Higher-rated conductors may be used for adjustment/correction only. Example: 10 AWG THHN at a 60 C-only termination is limited to 30 A.","r":"110.14(C)"},{"t":3,"c":"Load calculations and ampacity","f":"Conductor bundling adjustment factors.","b":"More than 3 current-carrying conductors: 4-6 = 80 percent; 7-9 = 70 percent; 10-20 = 50 percent; 21-30 = 45 percent; 31-40 = 40 percent; 41 or more = 35 percent. Example: 8 current-carrying 12 AWG THHN (30 A at 90 C): 30 x 0.70 = 21 A.","r":"Table 310.15(C)(1)"},{"t":3,"c":"Load calculations and ampacity","f":"Ambient temperature correction (base ambient 30 C / 86 F).","b":"Multiply the ampacity by the table factor. Example: 90 C-rated 12 AWG (30 A) in a 40 C (104 F) ambient: factor 0.91, so 30 x 0.91 = 27.3 A.","r":"Table 310.15(B)(1)"},{"t":3,"c":"Load calculations and ampacity","f":"Neutral load demand on a feeder or service.","b":"Neutral can be reduced: first 200 A at 100 percent, the portion over 200 A at 70 percent (no reduction for nonlinear/harmonic loads of the types listed). Example: 300 A neutral load = 200 + 0.7 x 100 = 270 A.","r":"220.61(B)"},{"t":3,"c":"Load calculations and ampacity","f":"Storage-type water heater branch circuit.","b":"Treated as a continuous load: size at 125 percent of nameplate rating (120 gal or less). Example: 4,500 W at 240 V = 18.75 A x 1.25 = 23.4 A, so 10 AWG on a 25 A breaker.","r":"422.13"},{"t":3,"c":"Load calculations and ampacity","f":"Single-phase dwelling service/feeder conductor size shortcut (83 percent).","b":"For 120/240 V single-phase dwelling services and feeders rated 100-400 A, conductors may be sized at 83 percent of the service rating. Example: 200 A x 0.83 = 166 A, so 2/0 Cu (175 A) or 4/0 Al (180 A).","r":"310.12"},{"t":3,"c":"Boxes and conduit fill","f":"Box fill volume allowance per conductor (Table 314.16(B)).","b":"14 AWG 2.00 cu in; 12 AWG 2.25; 10 AWG 2.50; 8 AWG 3.00; 6 AWG 5.00. Example: five 12 AWG conductors need 5 x 2.25 = 11.25 cu in.","r":"Table 314.16(B)"},{"t":3,"c":"Boxes and conduit fill","f":"Box fill deductions for clamps, devices and grounds.","b":"Clamps (all together): 1 allowance on largest conductor. Each yoke/device: 2 allowances (largest conductor connected to it). All equipment grounding conductors together: 1 allowance. Each support fitting (stud/hickey): 1 allowance. Example: a 12 AWG device counts 2 x 2.25 = 4.5 cu in.","r":"314.16(B)"},{"t":3,"c":"Boxes and conduit fill","f":"Sample box fill calculation.","b":"Two 12-2 NM cables (4 insulated conductors) + 1 for grounds + 2 for one device + 1 for clamps = 8 allowances x 2.25 = 18.0 cu in minimum box volume.","r":"314.16(B)"},{"t":3,"c":"Boxes and conduit fill","f":"Conduit fill percentages for conductors.","b":"1 conductor 53 percent; 2 conductors 31 percent; over 2 conductors 40 percent of the conduit cross-section. Example: 3/4 in EMT total area 0.533 sq in x 40 percent = 0.213 sq in.","r":"Chapter 9 Table 1"},{"t":3,"c":"Boxes and conduit fill","f":"Conduit fill for a nipple 24 in or shorter.","b":"Fill may go up to 60 percent of the raceway cross-sectional area. Example: 1/2 in EMT (0.304 sq in) allows 0.304 x 0.60 = 0.182 sq in.","r":"Chapter 9 Table 1 Note 4"},{"t":3,"c":"Boxes and conduit fill","f":"How do you count conductors in a conduit?","b":"Add the Table 5 areas of all conductors and compare to the 40 percent column of Table 4. Example: 12 AWG THHN is 0.0133 sq in; 0.122 sq in (40 percent of 1/2 in EMT) / 0.0133 = 9 conductors.","r":"Chapter 9 Tables 4 and 5"},{"t":3,"c":"Boxes and conduit fill","f":"Conduit fill for 3/4 in and 1 in EMT with 12 AWG THHN.","b":"3/4 in EMT: 0.213 / 0.0133 = 16 conductors. 1 in EMT: 0.346 / 0.0133 = 26 conductors. (EMT 40 percent areas: 1/2 in 0.122, 3/4 in 0.213, 1 in 0.346 sq in.)","r":"Chapter 9 Table 4 and 5"},{"t":3,"c":"Boxes and conduit fill","f":"Wireway and auxiliary gutter fill.","b":"Conductors may fill no more than 20 percent of the interior cross-sectional area. Example: a wireway with 16 sq in interior allows 3.2 sq in of conductors.","r":"376.22(A), 366.22(A)"},{"t":3,"c":"Grounding and bonding sizing","f":"Grounding electrode conductor (GEC) sizing basis.","b":"Size the GEC by the largest ungrounded service-entrance conductor (or equivalent area for parallel sets). Example: 4/0 Cu service conductors need a 2 AWG Cu GEC.","r":"Table 250.66"},{"t":3,"c":"Grounding and bonding sizing","f":"Table 250.66 anchors for copper GEC.","b":"Service conductor 2 AWG or smaller: 8 AWG Cu. 1 or 1/0: 6 Cu. 2/0 or 3/0: 4 Cu. Over 3/0 to 350 kcmil: 2 Cu. Over 350 to 600: 1/0 Cu. Example: 3/0 Cu service = 4 AWG Cu GEC.","r":"Table 250.66"},{"t":3,"c":"Grounding and bonding sizing","f":"GEC to a ground rod, pipe or plate electrode: size limit.","b":"Not required to be larger than 6 AWG copper when it is the sole connection to rod, pipe or plate electrodes. Example: 4/0 service conductor with a rod only: 6 AWG Cu is enough.","r":"250.66(A)"},{"t":3,"c":"Grounding and bonding sizing","f":"GEC to a concrete-encased electrode: size limit.","b":"Not required to be larger than 4 AWG copper when it is the sole connection to a concrete-encased electrode. Example: 600 kcmil service with a ufer only: 4 AWG Cu is enough.","r":"250.66(B)"},{"t":3,"c":"Grounding and bonding sizing","f":"Equipment grounding conductor (EGC) sizing basis.","b":"Size the EGC from the rating of the OCPD ahead of the circuit. Table values: 15 A = 14 AWG, 20 A = 12, 30-60 A = 10, 100 A = 8, 200 A = 6, 300 A = 4, 400 A = 3, 500 A = 2, 600 A = 1, 800 A = 1/0. Example: 60 A breaker needs 10 AWG Cu EGC.","r":"Table 250.122"},{"t":3,"c":"Grounding and bonding sizing","f":"EGC when conductors are increased for voltage drop.","b":"The EGC is increased in proportion to the circular-mil area of the upsized ungrounded conductors. Example: 12 AWG upsized to 10 AWG on a 20 A circuit: EGC goes from 12 AWG to 10 AWG.","r":"250.122(B)"},{"t":3,"c":"Dwelling load calculations","f":"General lighting load for a dwelling.","b":"3 VA per square foot, using outside dimensions and not counting open porches, garages or unfinished spaces not adaptable for use. Example: 2,000 sq ft x 3 = 6,000 VA.","r":"220.12, Table 220.12"},{"t":3,"c":"Dwelling load calculations","f":"Small-appliance branch circuits in a dwelling.","b":"At least two 20 A circuits, each calculated at 1,500 VA. Example: 2 x 1,500 = 3,000 VA.","r":"220.52(A)"},{"t":3,"c":"Dwelling load calculations","f":"Laundry branch circuit load in a dwelling.","b":"At least one 20 A laundry circuit calculated at 1,500 VA. Example: 1 x 1,500 = 1,500 VA.","r":"220.52(B)"},{"t":3,"c":"Dwelling load calculations","f":"Dwelling lighting and general-use demand factors.","b":"Table 220.42: first 3,000 VA at 100 percent; 3,001 to 120,000 VA at 35 percent; over 120,000 VA at 25 percent. Example: 9,500 VA total = 3,000 + 0.35 x 6,500 = 5,275 VA.","r":"Table 220.42"},{"t":3,"c":"Dwelling load calculations","f":"Household electric range demand (single range, not over 12 kW).","b":"Table 220.55 Column C: one range not over 12 kW = 8 kW demand. Over 12 kW up to 27 kW: increase 8 kW by 5 percent for each kW above 12. Example: 14 kW range = 8 x 1.10 = 8.8 kW.","r":"Table 220.55"},{"t":3,"c":"Dwelling load calculations","f":"Household electric clothes dryer load.","b":"Use 5,000 W or the nameplate rating, whichever is larger (demand factors apply for 5 or more dryers). Example: 5.8 kW nameplate dryer = 5,800 VA.","r":"220.54"},{"t":3,"c":"Dwelling load calculations","f":"Four or more fixed appliances in a dwelling.","b":"Apply a 75 percent demand factor to the nameplate rating of four or more fastened-in-place appliances (not ranges, dryers, space heating or AC). Example: 8,000 VA of appliances x 0.75 = 6,000 VA.","r":"220.53"},{"t":3,"c":"Dwelling load calculations","f":"Optional method for an existing or new dwelling: general load demand.","b":"First 10 kVA of general loads at 100 percent, the remainder at 40 percent. Example: 30 kVA general load = 10 + 0.40 x 20 = 18 kVA.","r":"220.82(B)"},{"t":3,"c":"Dwelling load calculations","f":"Optional method: heating and air-conditioning load.","b":"Add the largest of: AC at 100 percent, heat pump without supplemental heat at 100 percent, or electric space heat at 65 percent (fewer than four separately controlled units) or 40 percent (four or more units). Example: 10 kW heat strips as one unit: 10 x 0.65 = 6.5 kVA.","r":"220.82(C)"},{"t":3,"c":"Dwelling load calculations","f":"Convert a dwelling load in VA to service amps.","b":"Amps = VA / 240 for 120/240 V single-phase. Example: 28,800 VA / 240 = 120 A, so a 125 A or larger service.","r":"Electrical theory"},{"t":3,"c":"Dwelling load calculations","f":"Receptacle load for commercial/nondwelling occupancies.","b":"180 VA per single or multiple receptacle on one yoke. Example: ten duplex receptacles = 10 x 180 = 1,800 VA.","r":"220.14"},{"t":3,"c":"Dwelling load calculations","f":"Unit loads for office buildings and warehouses.","b":"Office buildings 3.5 VA per sq ft; warehouses (storage) 0.25 VA per sq ft; hospitals 2 VA per sq ft. Example: a 10,000 sq ft warehouse = 2,500 VA.","r":"Table 220.12"},{"t":3,"c":"Temperature and unit conversions","f":"Convert Fahrenheit to Celsius.","b":"C = (F - 32) / 1.8. Example: 104 F is (104 - 32) / 1.8 = 40 C.","r":"Electrical theory"},{"t":3,"c":"Temperature and unit conversions","f":"Convert Celsius to Fahrenheit.","b":"F = (C x 1.8) + 32. Example: 75 C is 75 x 1.8 + 32 = 167 F.","r":"Electrical theory"},{"t":3,"c":"Temperature and unit conversions","f":"Conductor insulation temperature ratings in Fahrenheit.","b":"60 C = 140 F; 75 C = 167 F; 90 C = 194 F; 30 C ambient base = 86 F. Example: THWN at 75 C equals 167 F.","r":"Electrical theory"},{"t":3,"c":"Temperature and unit conversions","f":"Quick conversions for electrical math.","b":"1 HP = 746 W; 1 kW = 1,000 W; 1 kW = 3,412 BTU/hr; 1 mil = 0.001 in; 1 ft = 12 in. Example: a 7.5 HP motor delivers 7.5 x 746 = 5,595 W.","r":"Electrical theory"}];